import{a as e}from"./jsx-runtime-Bzw2jH9X.js";var t=e({default:()=>n}),n=JSON.parse(`[{"id":"qx-h-001","clusterId":"H","werkstueckRef":"H.0","stufe":1,"question":"Welche Frage bringt dich in diesem Gespräch am ehesten weiter?","options":["Welche Denkfehler stecken in der Erklärung vom geheimen Plan, und wie zeige ich sie ihm ohne Vorwurf?","Welches Bedürfnis stillt ihm die Erklärung vom geheimen Plan, und wie nehme ich es zuerst ernst?","Wie belastbar sind die Quellen seines Online-Forums, und wie prüfe ich sie gemeinsam mit ihm?","Welches Gegenbeispiel zum geheimen Plan kann er nicht abtun, und wie bringe ich es behutsam ein?"],"correctIndex":1,"explanation":"Die Fakten sind schon zweimal abgeprallt, und das Gespräch dreht sich erkennbar um etwas anderes: Er erzählt von seinem Forum und seiner Entlassung, nicht von Zahlen. Das spricht dafür, dass der Glaube vor allem etwas anderes leistet, als Wissenslücken zu füllen. Eine Erklärung mit geheimem Plan ersetzt Zufall und Ohnmacht durch Absicht, und das Forum liefert Zugehörigkeit. Verschwörungsglaube wird laut Douglas, Sutton und Cichocka (2017) von epistemischen, existenziellen und sozialen Motiven angetrieben; die fünf Versprechen Sinn, Kontrolle, Einfachheit, Gemeinschaft und Selbstwert lassen sich diesen Motivgruppen zuordnen. Wer das Bedürfnis dahinter zuerst anerkennt, bleibt im Gespräch. Ob der Glaube es auf Dauer wirklich stillt, ist eine andere Frage: Für viele ist er eher verlockend als befriedigend.","coreRule":"⚡ Wer einen Irrglauben verstehen will, fragt zuerst, welchen Durst er stillt.","quote":"","quoteLabel":"","beleg":"Werkstück H.0 (Kernidee; Die fünf großen Versprechen; Das Härten im Feuer, Aktivierungs-Frage); Fn. gl-h-beduerfnisse (Douglas/Sutton/Cichocka 2017, S. 538)","status":"entwurf","scenario":"Dein Onkel ist überzeugt, hinter den steigenden Preisen stecke ein geheimer Plan weniger Mächtiger. Du hast ihm zweimal Statistiken zu Lieferketten und Energiepreisen gezeigt. Er winkt ab, wird gereizt und erzählt stattdessen begeistert von seinem Online-Forum, in dem sich alle „endlich verstanden“ fühlen. Seit seiner Entlassung im letzten Jahr beschäftigt ihn das Thema fast täglich.","kurz":"Zweimal sind Zahlen abgeprallt, und er spricht lieber von Forum und Entlassung. Der Plan-Glaube gibt ihm wohl Absicht statt Zufall und Zugehörigkeit. Weitere Fakten treffen daran vorbei, erst wer dieses Bedürfnis ernst nimmt, bleibt im Gespräch.","prueffrage":"Wovon redet er eigentlich begeistert, wenn die Statistiken schon abgeprallt sind?","rueckmeldung":[{"option":0,"text":"Denkfehler gibt es in der Plan-Erklärung tatsächlich, und ein freundlicher Ton ist gut. Doch auch ohne Vorwurf wäre es der dritte Anlauf über die Sachebene, und er trifft sein Weltbild, solange das Bedürfnis dahinter unbeachtet bleibt."},{"option":2,"text":"Gemeinsam Quellen zu prüfen ist eine gute Gewohnheit, wenn man sich um Belege streitet. Hier dreht sich das Gespräch aber um etwas anderes: Er erzählt vom Gefühl, im Forum verstanden zu werden, und kaum von dem, was dort steht."},{"option":3,"text":"Ein Gegenbeispiel, behutsam vorgebracht, kann in manchen Gesprächen durchaus etwas bewegen. Hier wäre es aber derselbe Weg wie die beiden Statistiken, die schon abgeprallt sind, und es lässt offen, was ihm der Glaube gibt."}],"familie":"wohlwollend-verstehen","fertigkeit":"F3","quellen":[{"typ":"doi","kurz":"Douglas, Sutton & Cichocka (2017): The Psychology of Conspiracy Theories. Current Directions in Psychological Science 26(6)","oeffentlich":true,"doi":"10.1177/0963721417718261","abruf":"2026-10-12"},{"typ":"url","kurz":"Lewandowsky & Cook (2020): The Conspiracy Theory Handbook","oeffentlich":true,"url":"https://skepticalscience.com/docs/ConspiracyTheoryHandbook.pdf","seite":"4","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"27a03774496fcd5f"}},{"id":"qx-h-002","clusterId":"H","werkstueckRef":"H.0","stufe":2,"question":"Welcher Gesprächsanfang ist am wahrscheinlichsten hilfreich, wenn du das Gespräch offen halten und zugleich die Entscheidung auf eine gute Grundlage stellen willst?","scenario":"Deine Schwägerin sagt, sie lasse ihr Kind nicht impfen, weil sie Angst hat, die falsche Entscheidung zu treffen.","options":["„Du willst das Beste für dein Kind, das kenne ich von mir auch. Bei meinem Kind hat die Impfung nie Probleme gemacht, du wirst sehen, dass es gut geht.“","„Du willst das Beste für dein Kind und fürchtest eine Fehlentscheidung. Das ist ganz allein deine Entscheidung, und ich mische mich da nicht ein.“","„Du willst das Beste für dein Kind und fürchtest eine Fehlentscheidung. Ich erkläre dir kurz, wie die Impfung wirkt, dann kannst du dich entscheiden.“","„Du willst das Beste für dein Kind und fürchtest eine Fehlentscheidung. Lass uns gemeinsam anschauen, was für und was gegen die Impfung spricht.“"],"correctIndex":3,"explanation":"Hinter der Entscheidung steht hier erkennbar ein Bedürfnis: Sicherheit und das Gefühl, keine folgenschwere Fehlentscheidung zu treffen. Der Gesprächsanfang, der die Angst als Wunsch nach der richtigen Entscheidung aufgreift und zum gemeinsamen Prüfen von Für und Wider einlädt, erkennt das Bedürfnis an, ohne dem Verzicht auf die Impfung zuzustimmen. So bleibt das Gespräch offen, und die Sache selbst kann überhaupt erst zur Sprache kommen.","coreRule":"⚡ Erst das Bedürfnis hinter einer Überzeugung anerkennen, dann gemeinsam die Sache prüfen.","beleg":"Werkstück H.0 (Anwendung & Relevanz: ‚Statt die Überzeugung anzugreifen, adressiere das Bedürfnis‘)","status":"entwurf","kurz":"Wer die Angst als Wunsch nach der richtigen Entscheidung aufgreift und zum gemeinsamen Abwägen einlädt, hält das Gespräch offen und bringt die Sache zur Sprache. Der naheliegende Fehler ist, nur zu beruhigen, zu informieren oder zu schweigen.","prueffrage":"Wie würdest du an ihrer Stelle auf einen Satz reagieren, der deine Sorge gleich zu Beginn für unbegründet oder für erledigt erklärt?","rueckmeldung":[{"option":0,"text":"Deine gute Erfahrung kann beruhigen, und der erste Satz nimmt ihr Anliegen ernst. Eine einzelne Erfahrung prüft aber keine Gründe und macht ihre Angst klein, statt sie ernst zu nehmen."},{"option":1,"text":"Hier wird ihre Selbstbestimmung geachtet, das ist ein echter Pluspunkt. Wer sich aber ganz heraushält, lässt sie mit ihrer Angst allein, und die Entscheidung steht danach auf keiner besseren Grundlage als vorher."},{"option":2,"text":"Eine kurze Erklärung klingt hilfsbereit und kann nützlich sein. Sie beantwortet aber nicht die Sorge hinter der Entscheidung, nämlich nichts Falsches zu tun, und macht sie eher zur Zuhörerin als zur Mitprüfenden."}],"familie":"wohlwollend-verstehen","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Gagneur, A. (2020): Motivational interviewing: A powerful tool to address vaccine hesitancy. Canada Communicable Disease Report 46(4), 93–97","oeffentlich":true,"url":"https://www.canada.ca/en/public-health/services/reports-publications/canada-communicable-disease-report-ccdr/monthly-issue/2020-46/issue-4-april-2-2020/article-6-canvax-addressing-vaccine-hesitancy.html","abruf":"2026-10-12"},{"typ":"url","kurz":"Lewandowsky & Cook (2020): The Conspiracy Theory Handbook, Abschnitt „How to talk to a conspiracy theorist“","oeffentlich":true,"url":"https://skepticalscience.com/docs/ConspiracyTheoryHandbook.pdf","seite":"10","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"89af8b92eedefc16"}},{"id":"qx-h-003","clusterId":"H","werkstueckRef":"H.0","stufe":3,"question":"Du liest in einem Forum den Satz: „Wer einem Gruppenmitglied Fakten gegen dessen Überzeugung zeigt, bestärkt es damit nur noch mehr in seinem Irrtum.“ Die Debatte dreht sich im Kern um Zugehörigkeit und Identität. Was ist an dieser Behauptung am ehesten problematisch?","options":["Sie überschätzt den Effekt: Fakten verhärten in Identitätsdebatten oft die Fronten, dass sie den Irrtum aber aktiv bestärken, kommt selten vor.","Sie ist zu allgemein: In Identitätsdebatten bestärken Fakten den Irrtum tatsächlich, bei sachlichen Streitfragen aber kaum, und das übergeht sie.","Sie verwechselt die Ursache: Nicht die Fakten selbst bestärken den Irrtum, sondern die belehrende Art, in der sie oft vorgetragen werden.","Sie verallgemeinert vorschnell: Wie jemand auf Fakten reagiert, hängt von der Person ab, darüber lässt sich kaum etwas Allgemeines sagen."],"correctIndex":0,"explanation":"Wenn es im Kern um Identität und Zugehörigkeit geht, erlebt die Person Fakten oft als Angriff auf ihre Gruppe, und die Fronten verhärten sich. Daraus folgt aber nicht, dass Fakten den Irrtum aktiv verstärken: Ein solcher Backfire-Effekt ist empirisch selten. Die Behauptung verwechselt also „wirkt oft nicht“ mit „wirkt ins Gegenteil“. Fakten sind in solchen Debatten häufig nicht die richtige Währung, aber nicht per se schädlich. Wer das Bedürfnis hinter dem Glauben anspricht, hat oft bessere Chancen als mit einem weiteren Faktenstrom.","coreRule":"⚡ In Identitätsdebatten sind Fakten allein oft nicht die richtige Währung und verhärten die Fronten, bestärken den Irrtum aber nur selten (Backfire-Effekt).","beleg":"Werkstück H.0 (Anwendung & Relevanz: ‚Erkennen, dass Fakten oft nicht die richtige Währung sind‘)","status":"entwurf","scenario":"","quote":"","quoteLabel":"","kurz":"Verhärtete Fronten sind in Identitätsdebatten häufig, eine aktive Verstärkung des Irrtums durch Fakten ist dagegen selten. Der Fehler liegt darin, „wirkt oft nicht“ mit „wirkt ins Gegenteil“ gleichzusetzen.","prueffrage":"Wie oft halten Menschen nach einer Korrektur tatsächlich stärker am Irrtum fest als vorher?","rueckmeldung":[{"option":1,"text":"Dass Identitätsdebatten anders laufen als Sachfragen, stimmt. Aber auch dort bestärken Fakten den Irrtum nur selten aktiv; meist verhärten sich bloß die Fronten. Genau diese Verstärkung stellt die Option als gegeben hin."},{"option":2,"text":"Ton und Auftreten können in solchen Debatten tatsächlich viel ausmachen. Der Kern der Behauptung ist damit aber nicht getroffen: Ein Gegenteil-Effekt der Fakten ist ohnehin selten, die Frage nach der Ursache stellt sich also gar nicht erst."},{"option":3,"text":"Menschen reagieren verschieden, das ist richtig. Trotzdem lässt sich Allgemeines sagen: Fronten verhärten sich oft, ein Bestärken des Irrtums bleibt selten. Der Fehler der Behauptung liegt in ihrem Schluss, nicht in fehlender Pauschalisierbarkeit."}],"familie":"befund-reichweite","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Nyhan, B. (2021): Why the backfire effect does not explain the durability of political misperceptions. PNAS 118(15)","oeffentlich":true,"doi":"10.1073/pnas.1912440117","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Wood, T. & Porter, E. (2019): The Elusive Backfire Effect: Mass Attitudes' Steadfast Factual Adherence. Political Behavior 41(1), 135–163","oeffentlich":false}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"f2b61b04d876ce34"}},{"id":"qx-h-004","clusterId":"H","werkstueckRef":"H.0","stufe":4,"question":"Was ist an der Aussage deines Bekannten problematisch?","scenario":"Ein Bekannter sagt: „Bei Verschwörungsgläubigen sind Belege sinnlos. Man kann nur ihre Bedürfnisse bedienen.“ Du weißt, dass in einem großen Experiment von 2024 ein Sprachmodell in Einzelgesprächen mit gut zugeschnittenen Belegen auf die jeweiligen Überzeugungen der Teilnehmenden einging. Der Verschwörungsglaube der Teilnehmenden ließ danach nach – auch bei denen, die fest überzeugt waren.","options":["Sie ist zu abwertend: Sie unterstellt Verschwörungsgläubigen mangelnde Intelligenz, obwohl auch kluge Menschen solchen Erzählungen anhängen.","Sie ist zu pauschal: Das Experiment zeigt, dass auch gut zugeschnittene Belege den Glauben lockern können, selbst bei fest Überzeugten.","Sie ist zu einseitig: Sie übergeht die Bedürfnisse nach Sinn, Kontrolle und Gemeinschaft, die den Glauben der Teilnehmenden in erster Linie tragen.","Sie ist zu kurzsichtig: Sie fragt nicht, ob der Glaube nach den Einzelgesprächen dauerhaft nachließ, obwohl erst ein anhaltender Rückgang zählt."],"correctIndex":1,"explanation":"Dass Verschwörungsglaube oft psychologische Bedürfnisse nach Sinn, Kontrolle, Gemeinschaft oder Selbstwert stillt, ist gut begründet, und dann ist es klug, ein Bedürfnis zuerst ernst zu nehmen. Daraus folgt aber nicht, dass Belege wirkungslos sind. Das widerlegt schon ein einziges gut gemachtes Gegenbeispiel: Im Experiment von 2024 lockerten gut zugeschnittene Belege den Glauben, auch bei fest Überzeugten. Die Aussage „Belege sind sinnlos“ ist ein Alles-oder-nichts-Schluss aus einer richtigen Teilbeobachtung. Die anderen Antworten klingen nach naheliegenden Einwänden, treffen aber nicht: Der Bekannte unterstellt keine mangelnde Intelligenz, und er übergeht die Bedürfnisse nicht, sondern hebt sie im Gegenteil allein hervor. Ob der Rückgang anhielt, ist eine berechtigte Anschlussfrage, ändert aber nichts daran, dass ein Allsatz wie „sinnlos“ schon durch einen gut gemachten Gegenfall angreifbar wird; die Wiederholung durch andere Gruppen wäre erst nötig, um die Wirkung der Belege genauer zu bestimmen.","coreRule":"⚡ Bedürfnisse ernst nehmen, aber Belege nicht pauschal für wirkungslos erklären: Ein einziges gut belegtes Gegenbeispiel genügt gegen „nie“ und „sinnlos“.","beleg":"Werkstück H.0 (Anwendung & Relevanz: ‚Ein besseres Angebot machen‘; Verweis auf Anhang VII.1; keine Fußnote für diese Aussage)","status":"entwurf","kurz":"Aus der richtigen Beobachtung, dass Bedürfnisse den Glauben oft tragen, wird ein Alles-oder-nichts-Schluss. Schon ein gut gemachtes Gegenbeispiel widerlegt „sinnlos“: Im Experiment lockerten zugeschnittene Belege den Glauben, auch bei fest Überzeugten.","prueffrage":"Wer nahm am Experiment von 2024 teil, und was geschah mit dem Glauben der Teilnehmenden nach den Gesprächen?","rueckmeldung":[{"option":0,"text":"Dass auch kluge Menschen Verschwörungserzählungen glauben, stimmt. Nur steht davon nichts in der Aussage deines Bekannten: Er spricht nicht über Intelligenz, sondern behauptet, Belege wirkten nicht. Der Einwand trifft also nicht ihren Kern."},{"option":2,"text":"Bedürfnisse nach Sinn, Kontrolle und Gemeinschaft tragen den Glauben oft tatsächlich. Dein Bekannter übergeht sie aber nicht, im Gegenteil: Er stellt allein sie in den Vordergrund. Das Problem liegt im Schluss, Belege seien deshalb wirkungslos."},{"option":3,"text":"Ob der Rückgang anhielt, ist eine berechtigte Anschlussfrage. Gegen die Behauptung „sinnlos“ reicht aber schon ein gut gemachter Gegenfall. Die Dauer wäre erst wichtig, um die Wirkung der Belege genauer zu bestimmen."}],"familie":"befund-reichweite","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Douglas, Sutton & Cichocka (2017): The Psychology of Conspiracy Theories. Current Directions in Psychological Science 26(6)","oeffentlich":true,"doi":"10.1177/0963721417718261","abruf":"2026-10-12"},{"typ":"doi","kurz":"Costello, Pennycook & Rand (2024): Durably reducing conspiracy beliefs through dialogues with AI. Science 385(6714), eadq1814","oeffentlich":false,"doi":"10.1126/science.adq1814","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"beb0da38d8e48182"}},{"id":"qx-h-005","clusterId":"H","werkstueckRef":"H.0.1","stufe":1,"question":"Welche Deutung des Ergebnisses ist angemessen, und wie sicher darfst du dir dabei sein?","options":["Der Gedanke an den eigenen Tod verstärkte bei den Richtern das Bedürfnis, ihre Weltanschauung zu verteidigen; bei 22 Personen und gescheiterten Wiederholungen verwandter Befunde bleibt das eine vorläufige Vermutung.","Der Gedanke an den eigenen Tod verstärkte bei den Richtern das Bedürfnis, ihre Weltanschauung zu verteidigen; weil eine Kontrollgruppe ohne Todesfragen zum Vergleich diente, ist der Befund recht gut gesichert.","Der Gedanke an den eigenen Tod verstärkte bei den Richtern das Bedürfnis, ihre Weltanschauung zu verteidigen; die gescheiterten Wiederholungen betrafen nur verwandte Befunde, dieses Ergebnis selbst gilt daher weiter.","Bei nur 22 Richtern ist der große Unterschied zwischen den Gruppen am ehesten ein Zufallsbefund; nach den gescheiterten Wiederholungen verwandter Befunde sollte man ihn deshalb gar nicht inhaltlich deuten."],"correctIndex":0,"explanation":"Ein auffälliger Unterschied zwischen zwei Gruppen verlangt zwei Prüfungen: Welche Erklärung passt zu den Daten, und wie belastbar sind die Daten selbst? Dass die Todeserinnerung das Bedürfnis weckt, die eigene Weltanschauung zu verteidigen, ist eine naheliegende Deutung, denn die mutmaßliche Prostituierte verstieß gegen die Normen dieser Weltanschauung. Bei nur 22 Richtern und gescheiterten Wiederholungsversuchen zu verwandten Todeserinnerungs-Befunden (das Richter-Experiment selbst wurde nicht wiederholt) bleibt es aber eine vorläufige Vermutung und keine gesicherte Tatsache.","coreRule":"⚡ Passende Erklärung nennen, Gewissheit an der Datenlage messen: Kleine Stichprobe plus gescheiterte Wiederholungen heißt vorläufig.","beleg":"Werkstück H.0.1 (Kernidee: zwei Hauptstrategien)","status":"entwurf","scenario":"In einem Experiment bekommen Richter vor ihrem Urteil zwei Fragen zum eigenen Tod. Anschließend setzen sie für eine mutmaßliche Prostituierte eine durchschnittliche Kaution von 455 Dollar fest. Die Kontrollgruppe, die diese Fragen nicht bekommen hat, setzt im Schnitt 50 Dollar fest. Das Experiment umfasste 22 Richter; mehrere große Wiederholungsversuche zu verwandten Befunden sind seither gescheitert.","kurz":"Die Deutung passt zu den Daten, denn die Frau verstieß gegen die Normen der Richter. Doch bei 22 Richtern und gescheiterten Wiederholungen verwandter Befunde bleibt sie eine Vermutung. Ein klarer Unterschied macht sie noch nicht sicher.","prueffrage":"Wie viele Personen liegen den Zahlen zugrunde, und hat jemand das Experiment später mit anderen Teilnehmern wiederholt?","rueckmeldung":[{"option":1,"text":"Die Kontrollgruppe ist nötig, um den Unterschied überhaupt zu sehen. Mit nur 22 Richtern und gescheiterten Wiederholungen verwandter Befunde macht sie ihn aber nicht belastbar. Der Vergleich zeigt einen Unterschied, nicht dessen Verlässlichkeit."},{"option":2,"text":"Stimmt, das Richter-Experiment selbst wurde nicht wiederholt. Daraus folgt aber keine Bestätigung: Ungeprüft ist nicht gesichert, und die kleine Stichprobe wie die gescheiterten verwandten Wiederholungen mahnen zur Vorsicht."},{"option":3,"text":"Die Vorsicht ist berechtigt, schießt aber über das Ziel hinaus. Schwache Daten widerlegen die Deutung nicht, und sie bleibt naheliegend. Sie ist eine Vermutung, die man nicht für gesichert halten, aber auch nicht verwerfen muss."}],"familie":"wiederholung-abwarten","fertigkeit":"F1","quellen":[{"typ":"literatur","kurz":"Rosenblatt, Greenberg, Solomon, Pyszczynski & Lyon (1989): Evidence for terror management theory I. Journal of Personality and Social Psychology 57(4), 681–690","oeffentlich":false},{"typ":"doi","kurz":"Klein, R. A. u. a. (2022): Many Labs 4: Failure to Replicate Mortality Salience Effect With and Without Original Author Involvement. Collabra: Psychology 8(1), 35271","oeffentlich":true,"doi":"10.1525/collabra.35271","abruf":"2026-10-12"},{"typ":"doi","kurz":"Treger, Benau & Timko (2023): Not so terrifying after all? PLOS ONE 18(5), e0285267","oeffentlich":true,"doi":"10.1371/journal.pone.0285267","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v9","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"57506991a403d66d"}},{"id":"qx-h-006","clusterId":"H","werkstueckRef":"H.0.1","stufe":2,"question":"Welche Erklärung für seinen Sog zum Mythos passt am besten zu allem, was du über ihn weißt, und lässt sich gut prüfen?","scenario":"Ein Bekannter hat kurz nacheinander seinen Job verloren und eine schwere Krankheit durchgemacht. Seitdem erzählt er begeistert, er gehöre zu den „Erwachten“, die einen verborgenen Plan durchschauen und gegen ihn kämpfen. Eine Freundin vermutet, er habe einfach zu viel Zeit und zu wenig zu tun. Ein anderer meint: „Der war schon immer leichtgläubig.“ Du willst verstehen, was ihn wirklich anzieht.","options":["Der Mythos ersetzt weggebrochene Stützen: Er stiftet Sinn statt Chaos, macht ihn als „Wissenden“ zu jemandem mit Rolle und verbindet ihn mit etwas Größerem.","Der Mythos füllt vor allem leere Zeit: Er gibt dem Bekannten nach dem Jobverlust eine spannende Aufgabe, die ihn beschäftigt hält und von der Krankheit ablenkt.","Der Mythos schließt eine Wissenslücke: Wer die Zusammenhänge hinter Entlassungen und Krankheiten nicht kennt, greift zur einfachsten Erklärung, die ihm begegnet.","Der Mythos gibt einem Misstrauen Ausdruck, das sich über Jahre gegen Arbeitgeber und Ärzte aufgebaut hat und nun ein passendes Weltbild gefunden hat."],"correctIndex":0,"explanation":"Die Erklärung muss zu dem passen, was der Mythos ihm bietet, und zu dem, was bei ihm gerade zusammengebrochen ist. Jobverlust und Krankheit sind typische Phasen existenzieller Unsicherheit, in denen das bisherige „Terror-Management-System“ (die Stützen, die Sinn und Selbstwert tragen) zusammenbricht. Der Mythos ersetzt gleich mehrere Stützen auf einmal: Er macht aus einer chaotischen, bedeutungslosen Welt eine geordnete, in der alles einen Plan hat (Sinn). Er macht aus einem Menschen, dem Dinge zustoßen, einen „Erwachten“ mit heldenhafter Rolle (Selbstwert). Und er lässt ihn für „die Wahrheit“ oder eine bessere Welt kämpfen, also für etwas, das größer ist als er selbst (symbolische Unsterblichkeit). Eine Einschränkung gehört dazu: Ob unbewusste Todesangst dahintersteckt, ist empirisch umstritten, denn große Wiederholungsstudien dazu sind gescheitert. Als Erklärung des Motivs „Sinn, Selbstwert, Zugehörigkeit zu etwas Größerem nach dem Zusammenbruch der bisherigen Stützen“ trägt die Überlegung aber auch ohne diese Zusatzannahme. Das ist eine Hypothese, die du im Gespräch prüfen kannst, kein Urteil über ihn.","coreRule":"⚡ Frag bei einer Überzeugung: Was bietet sie, und was ist gerade weggebrochen? Wer Sinn, Rolle und Größeres zugleich verspricht, lockt am stärksten.","beleg":"Werkstück H.0.1 (Anwendung & Relevanz: Verschwörungsmythos, Anfälligkeit); Fn. gl-h-1 (Rosenblatt u. a. 1989; Transparenzhinweis zu Klein u. a. 2022, Many Labs 4)","status":"entwurf","kurz":"Jobverlust und Krankheit haben dem Bekannten mehrere Stützen genommen, der Mythos ersetzt sie: Er stiftet Sinn, macht ihn zum „Erwachten“ und verbindet ihn mit etwas Größerem. Wer nur nach einer einzelnen Lücke sucht, übersieht, wie viel auf einmal wegbrach.","prueffrage":"Was erzählt er selbst, wenn er begeistert vom „Erwachtsein“ spricht, und was hat er seit Jobverlust und Krankheit verloren?","rueckmeldung":[{"option":1,"text":"Leere Zeit kann ein Thema tatsächlich füllen und von der Krankheit ablenken. Sie erklärt aber nicht, warum es ausgerechnet dieser Mythos ist und warum er sich als Wissender fühlt und für etwas kämpft."},{"option":2,"text":"Eine Wissenslücke erklärt gut, warum eine einfache Erklärung gefällt. Sie erklärt aber nicht, warum der Wandel gerade nach Jobverlust und Krankheit kam und warum er so begeistert ist."},{"option":3,"text":"Misstrauen kann ein Weltbild anziehen. Doch begann sein Wandel laut Szenario erst nach den beiden Schlägen, ein über Jahre gewachsenes Misstrauen passt also nicht zu diesem Zeitpunkt."}],"familie":"wohlwollend-verstehen","fertigkeit":"F3","quellen":[{"typ":"doi","kurz":"Douglas, Sutton & Cichocka (2017): The Psychology of Conspiracy Theories. Current Directions in Psychological Science 26(6)","oeffentlich":true,"doi":"10.1177/0963721417718261","abruf":"2026-10-12"},{"typ":"doi","kurz":"Treger, Benau & Timko (2023): Not so terrifying after all? PLOS ONE 18(5), e0285267","oeffentlich":true,"doi":"10.1371/journal.pone.0285267","abruf":"2026-10-12"},{"typ":"url","kurz":"Lewandowsky & Cook (2020): The Conspiracy Theory Handbook (Ohnmacht, Bedrohung, Unsicherheit als Treiber)","oeffentlich":true,"url":"https://skepticalscience.com/docs/ConspiracyTheoryHandbook.pdf","seite":"4","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"c77674ceade49b85"}},{"id":"qx-h-007","clusterId":"H","werkstueckRef":"H.0.1","stufe":3,"question":"Wie solltest du die Behauptung deiner Freundin am besten einschätzen?","scenario":"Eine Freundin sagt: „Das Richter-Experiment mit 455 statt 50 Dollar Kaution beweist doch, dass Todesangst Menschen härter urteilen lässt.“ Du weißt: Der Befund stammt aus einer Studie von 1989 mit 22 Richtern. Seither sind mehrere große Wiederholungsversuche zur Todeserinnerung gescheitert, und ein anderer klassischer Befund desselben Forschungsfelds ließ sich in einer großen Wiederholung unter keiner Bedingung bestätigen. Das Richter-Experiment selbst wurde bisher nicht groß wiederholt.","options":["Als Hinweis, aber nicht als Beweis: Mit 22 Richtern ist die Stichprobe klein, und verwandte Befunde des Feldes ließen sich nicht wiederholen.","Als weitgehend bestätigt, weil der Befund seit 1989 im Fach anerkannt ist: Was über Jahrzehnte gilt, hat sich in der Regel bewährt.","Als aussagekräftig, weil der Unterschied von 455 zu 50 Dollar groß ist: Das spricht trotz nur 22 Richtern für einen echten Effekt.","Als wertlos, weil verwandte Wiederholungen gescheitert sind: Misslingen sie im selben Feld, scheitert damit auch diese Studie."],"correctIndex":0,"explanation":"Eine Studie mit nur 22 Richtern ist klein, ihr Ergebnis taugt deshalb nicht als Beweis. Dazu kommt, dass mehrere große Wiederholungsversuche zur Todeserinnerung gescheitert sind. In der großen Replikation „Many Labs 4“ (Klein u. a. 2022) ließ sich ein anderer klassischer Befund desselben Forschungsfelds unter keiner Bedingung bestätigen; das Richter-Experiment von 1989 selbst wurde dort nicht wiederholt. Es gilt heute nicht mehr als unangefochten gesichert. Ein gescheiterter Befund aus demselben Forschungsfeld ist ein Warnsignal, aber kein Gegenbeweis für diese eine Studie. Angemessen ist ein vorsichtiges Urteil: ein Hinweis, der geprüft werden müsste, weder ein Beweis noch einfach Unsinn.","coreRule":"⚡ Eine kleine Einzelstudie ist ein Hinweis, kein Beweis: Erst Wiederholungen entscheiden, und ein Warnsignal aus dem Umfeld ist noch keine Widerlegung.","beleg":"Werkstück H.0.1 (Der Richter und das Kruzifix); Fn. gl-h-1 (Rosenblatt u. a. 1989, JPSP 57(4), S. 681–690, Exp. 1 S. 682; Klein u. a. 2022, Collabra 8(1))","status":"entwurf","kurz":"Mit 22 Richtern ist die Studie klein, und verwandte Befunde des Feldes ließen sich nicht wiederholen. Das ist ein Grund für Vorsicht. Wer hier „bewiesen“ sagt, nimmt einen Hinweis für einen Beweis.","prueffrage":"Wie oft und in welcher Größe wurde dieser Befund seit 1989 unabhängig nachgeprüft?","rueckmeldung":[{"option":1,"text":"Dass ein Befund lange im Fach gilt, wirkt wie eine bestandene Probe. Das sagt aber wenig über seine Belastbarkeit, solange Wiederholungen im selben Feld misslingen. Gesichert ist er daher nicht."},{"option":2,"text":"Ein großer Unterschied klingt nach einem starken Effekt. Bei nur 22 Richtern kann er aber leicht zufällig entstehen, und große Zahlenunterschiede in kleinen Gruppen sind eher ein Warnzeichen als ein Beleg."},{"option":3,"text":"Daran stimmt: Gescheiterte Wiederholungen im selben Feld sind ein Warnsignal. Widerlegt ist diese Studie dadurch aber nicht, sie wurde nie groß wiederholt. „Wertlos“ geht deshalb zu weit."}],"familie":"wiederholung-abwarten","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Klein, R. A. u. a. (2022): Many Labs 4: Failure to Replicate Mortality Salience Effect With and Without Original Author Involvement. Collabra: Psychology 8(1), 35271","oeffentlich":true,"doi":"10.1525/collabra.35271","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Rosenblatt, Greenberg, Solomon, Pyszczynski & Lyon (1989): Evidence for terror management theory I. Journal of Personality and Social Psychology 57(4), 681–690","oeffentlich":false}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"dcd5035903e68831"}},{"id":"qx-h-008","clusterId":"H","werkstueckRef":"H.0.1","stufe":3,"question":"Was ist an dieser Schlussfolgerung fehlerhaft?","options":["Er schließt vom Zweck einer Überzeugung auf ihren Wert; dass sie vor Angst schützt, macht sie nicht schädlich, das zeigt sich erst an ihren Folgen.","Er verallgemeinert zu stark; dass manche Überzeugungen vor Angst schützen, gilt nicht für jede, und nur für diese wäre sein Schluss berechtigt.","Er setzt eine unsichere Theorie voraus; erst wenn belegt wäre, dass Überzeugungen vor Todesangst schützen, dürfte er so weit schließen.","Er urteilt über Menschen statt über ihre Gründe; ob eine Pflegerin oder eine Gläubige sich etwas vormacht, kann er von außen nicht wissen."],"correctIndex":0,"explanation":"Der Fehlschluss springt vom Ursprung oder Zweck einer Überzeugung auf ihren Wert. Dass etwas ein Bedürfnis erfüllt, sagt weder, dass es wahr ist, noch, dass es schädlich ist. Folgt man der Theorie, kann dieselbe Quelle Kathedralen, Forschung und Familiengründungen antreiben, aber auch Hass. Kritisch wird es dort, wo die Verteidigung der eigenen Weltanschauung wichtiger wird als Realität oder Menschlichkeit, etwa wenn man Andersdenkende verletzt oder Fakten leugnet. Ob eine Überzeugung ungesund ist, zeigt sich also an ihren Folgen, nicht an ihrer Herkunft. Die bewusste Selbstprüfung, ob die Wut vom Argument oder von der Bedrohung des eigenen Glaubenssatzes kommt, hilft, diese Grenze rechtzeitig zu bemerken.","coreRule":"⚡ Von der Herkunft einer Überzeugung auf ihren Wert zu schließen, ist ein Fehlschluss. Prüfe, was sie im Verhalten bewirkt.","beleg":"Werkstück H.0.1 (Das Adaptive Talent; Der Kipppunkt; Das Anti-Denkmuster)","status":"entwurf","scenario":"In einer Diskussion sagt jemand: „Menschen schützen sich mit festen Überzeugungen vor der Angst vor dem Tod. Also ist jede feste Überzeugung ungesund, und wer sich wie eine Pflegerin, ein Patriot oder eine Gläubige auf einen Sinn stützt, macht sich etwas vor.“","kurz":"Dass eine Überzeugung ein Bedürfnis erfüllt, sagt weder, dass sie wahr, noch, dass sie schädlich ist. Der Fehler ist der Sprung von Zweck oder Herkunft auf den Wert; ob sie ungesund ist, zeigt sich an ihren Folgen.","prueffrage":"Was nennt der Sprecher als Grund, und was behauptet er am Ende über die Überzeugungen?","rueckmeldung":[{"option":1,"text":"Aus „Menschen schützen sich“ wird tatsächlich ungeprüft „jede Überzeugung“. Auch bei einer Überzeugung, die vor Angst schützt, folgte aber nicht, dass sie ungesund ist. Der Schluss trägt also auch dort nicht."},{"option":2,"text":"Die Annahme über Todesangst ist eine Theorie, die er wie eine Tatsache behandelt. Der Schluss scheitert aber auch, wenn man sie als wahr unterstellt: Ein Schutz vor Angst macht eine Überzeugung nicht schädlich."},{"option":3,"text":"Sein Urteil über die Pflegerin oder die Gläubige ist tatsächlich vorschnell, denn ihre Gründe kennt er nicht. Selbst wenn er sie kennte, bliebe der Schluss aber brüchig, weil der Zweck einer Überzeugung nichts über ihre Folgen sagt."}],"familie":"inhalt-statt-absender","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Internet Encyclopedia of Philosophy: Fallacies, Eintrag „Genetic Fallacy“","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"ok","pruefsumme":"4bab1da647470804"}},{"id":"qx-h-009","clusterId":"H","werkstueckRef":"H.1.1","stufe":1,"question":"Welche Haltung hilft Karim am ehesten, mit dieser Kritik produktiv umzugehen?","options":["Er sollte den Wochenplan gegen Lenas Einwand der Schichtarbeit verteidigen, denn wer bei der ersten Kritik nachgibt, wirkt auf die anderen unglaubwürdig.","Er sollte die übrigen Mitbewohner nach dem Wochenplan fragen und sich der Mehrheit anschließen, damit die Entscheidung gerecht ausfällt.","Er sollte das Thema Hausflur für diese Woche ruhen lassen und erst später auf Lenas Einwand eingehen, damit sich die Stimmung beruhigt.","Er sollte sich klarmachen, dass sein Wochenplan nur eine Hypothese ist, die an der Schichtarbeit scheitern darf, ohne dass sein eigener Wert daran hängt."],"correctIndex":3,"explanation":"Karims Gedanke „Wenn mein Plan nichts taugt, tauge ich nichts“ verschmilzt Person und Idee. Genau dadurch wird Kritik als Angriff auf ihn selbst erlebt, und das Ziel kippt von „den besten Plan finden“ zu „mich verteidigen“. Hilfreich ist der mentale Abstand: Der Plan ist etwas, das Karim hat, nicht etwas, das er ist. Dann kann er Lenas Einwand ernsthaft prüfen, vielleicht nachbessern oder verwerfen, ohne sich selbst infrage zu stellen.","coreRule":"⚡ Du hast deine Idee, du bist nicht deine Idee.","beleg":"Werkstück H.1.1 (Kernidee; Kontext & Tiefe)","status":"freigegeben","freigabe":{"datum":"2026-10-15","pruefsumme":"be7f6c66ea742a35","vermerk":"Prüfpult (Sturm, erste Charge nach den neuen falschen Optionen)"},"scenario":"Karim hat vorgeschlagen, den Hausflur der Wohngemeinschaft jede Woche im Wechsel zu putzen. Auf der Hausversammlung nimmt Lena den Plan auseinander: Bei drei Mitbewohnern in Schichtarbeit sei er unrealistisch. Karim merkt, wie ihm die Hitze ins Gesicht steigt, und denkt: „Wenn mein Plan nichts taugt, tauge ich nichts.“","kurz":"Karim kann Lenas Einwand nur ernsthaft prüfen, wenn der Plan etwas ist, das er hat, und nicht etwas, das er ist. Sonst wird aus „den besten Plan finden“ schnell „mich verteidigen“. Ärger darf da sein, soll aber nicht über die Prüfung entscheiden.","prueffrage":"Was genau wirft Lena dem Plan vor, und lässt sich das an den Schichtzeiten der drei Mitbewohner nachprüfen?","rueckmeldung":[{"option":0,"text":"Standhaft zu bleiben ist bei unberechtigter Kritik sinnvoll. Hier würde Karim aber vor allem sich selbst verteidigen, und ob die Schichtarbeit den Plan tatsächlich unrealistisch macht, bliebe ungeprüft."},{"option":1,"text":"Die Mitbewohner einzubeziehen ist als Entscheidungsweg durchaus legitim. Karims Gleichsetzung von Plan und Person bleibt dadurch aber bestehen, und auch Lenas Einwand wird nicht inhaltlich geprüft."},{"option":2,"text":"Eine Pause kann den Ärger dämpfen und die Stimmung beruhigen. Wenn Karim Kritik am Plan danach weiter als Urteil über sich erlebt, kehrt dieselbe Abwehr beim nächsten Einwand zurück."}],"familie":"selbstrechtfertigung-erkennen","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Hayes, Levin, Plumb-Vilardaga, Villatte & Pistorello (2013): Acceptance and Commitment Therapy and Contextual Behavioral Science. Behavior Therapy 44(2), 180–198 (PMC-Fassung)","oeffentlich":true,"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC3635495/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"be7f6c66ea742a35"}},{"id":"qx-h-010","clusterId":"H","werkstueckRef":"H.1.1","stufe":2,"question":"Wie ist dieses Signal am sinnvollsten zu deuten?","scenario":"Du merkst mitten in einer Diskussion über Politik, wie dir heiß wird und du nur noch deine Seite verteidigen willst, statt zuzuhören.","options":["Als Zeichen von Engagement: Wer sich für eine Sache einsetzt, wird eben warm, und bei politischen Fragen zeigt das, dass dir das Thema wirklich am Herzen liegt.","Als Alarmsignal: Vermutlich verschmilzt gerade deine Identität mit deiner Idee, das schnelle Denken übernimmt, und dir geht es mehr um Selbstschutz als um Wahrheit.","Als Hinweis, dass dein Gegenüber einen wunden Punkt getroffen hat: Wer so heftig reagiert, spürt vermutlich, dass an dem Einwand etwas Wahres dran ist.","Als Zeichen, dass du deine Sicht noch nicht klar genug erklärt hast: Begründest du sie besser, versteht dich dein Gegenüber, und die Hitze legt sich vermutlich."],"correctIndex":1,"explanation":"Wenn eine Kritik an der Idee wie ein Angriff auf die eigene Person wirkt, springt das automatische, emotionale Verteidigungssystem an. Die Logik schaltet sich dabei nicht ab, sie wechselt die Seite: Sie dient nun dazu, die eigene Identität zu schützen, nicht dazu, die Wahrheit zu finden. Dazu passt ein viel zitiertes Experiment: Bei einer Hautcreme entschied das Rechenkönnen über die richtige Antwort auf eine Vierfeldertafel, beim Waffenverbot spaltete sich die Auswertung entlang der Weltanschauung. Spätere Wiederholungen bestätigten die weltanschauliche Färbung nur teilweise, die Verstärkung durch Rechenkönnen fanden sie nicht. Hitze und Abwehr sagen also etwas über deinen inneren Zustand, nicht über die Wahrheit der Sache. Hilfreich ist Abstand zur eigenen Idee: Sie ist etwas, das du hast, nicht etwas, das du bist.","coreRule":"⚡ Wirst du wütend und defensiv, verteidigst du vermutlich gerade dich und nicht die Wahrheit.","beleg":"Werkstück H.1.1 (Anwendung & Relevanz: ‚In jeder hitzigen Debatte‘; Kontext & Tiefe); Fn. gl-h-motiviert (Kahan u. a. 2017, zur motivierten Verarbeitung bei politischen Themen; Wiederholungen: Persson u. a. 2021, Stagnaro u. a. 2023)","status":"entwurf","kurz":"Wenn du nur noch verteidigen willst, schützt dein schnelles, emotionales Denken vermutlich gerade deine Identität statt die Wahrheit zu suchen. Naheliegend ist, Hitze für Leidenschaft oder für ein Zeichen zu halten, dass der Einwand sitzt.","prueffrage":"Was weißt du über die Sache selbst jetzt mehr als vor dem Moment, in dem dir heiß wurde?","rueckmeldung":[{"option":0,"text":"Dass dir ein Thema am Herzen liegt, kann durchaus stimmen. Hitze zeigt aber nur, wie stark du gerade beteiligt bist, nicht, dass du gut denkst, und dass du nur noch verteidigst statt zuzuhören, spricht eher dagegen."},{"option":2,"text":"Ein Einwand kann durchaus zutreffen. Aber die Heftigkeit einer Reaktion sagt etwas über den inneren Zustand des Reagierenden, nicht über die Wahrheit der Sache; hier geht es zudem um deine eigene Hitze, und die lässt sich so nicht lesen."},{"option":3,"text":"Eine klare Begründung hilft einer Diskussion fast immer. Dein Signal ist aber nicht, dass man dich nicht versteht, sondern dass du selbst nicht mehr zuhörst. Hilfreicher ist deshalb Abstand zur eigenen Idee als eine bessere Erklärung."}],"familie":"selbstrechtfertigung-erkennen","fertigkeit":"F5","quellen":[{"typ":"doi","kurz":"Stagnaro, Tappin & Rand (2023): No association between numerical ability and politically motivated reasoning in a large US probability sample. PNAS 120(32), e2301491120","oeffentlich":true,"doi":"10.1073/pnas.2301491120","abruf":"2026-10-12"},{"typ":"doi","kurz":"Persson, Andersson, Koppel, Västfjäll & Tinghög (2021): A preregistered replication of motivated numeracy. Cognition 214, 104768","oeffentlich":true,"doi":"10.1016/j.cognition.2021.104768","abruf":"2026-10-12"},{"typ":"doi","kurz":"Kahan, Peters, Dawson & Slovic (2017): Motivated numeracy and enlightened self-government. Behavioural Public Policy 1(1), 54–86","oeffentlich":false,"doi":"10.1017/bpp.2016.2","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"431cd368f1bc934f"}},{"id":"qx-h-011","clusterId":"H","werkstueckRef":"H.1.1","stufe":4,"question":"Du begutachtest den Aufsatz. Was rätst du der Forscherin zu ihrem Satz?","options":["Sie sollte den Satz beibehalten und als umstritten kennzeichnen, denn Original und Wiederholungen kommen beim Rechenkönnen zu verschiedenen Ergebnissen.","Sie sollte den Satz auf die Färbung beschränken, denn die Wiederholungen stützen diese zumindest teilweise, die Verstärkung durch Rechenkönnen aber nicht.","Sie sollte den Satz abschwächen, etwa zu „Rechenkönnen kann die Färbung verstärken“, denn zwei Wiederholungen schließen die Verstärkung nicht ganz aus.","Sie sollte den Satz streichen, denn seine Hauptaussage, dass Rechenkönnen die Färbung verstärkt, ließ sich in zwei großen vorregistrierten Wiederholungen nicht bestätigen."],"correctIndex":1,"explanation":"Ein Befund ist nur so belastbar wie seine Wiederholung. Die große vorregistrierte Wiederholung (Persson u. a. 2021, 3.154 Teilnehmer) fand die weltanschauliche Färbung zum Teil wieder, die Verstärkung durch Rechenkönnen aber nicht. Die zweite vorregistrierte Wiederholung mit einer repräsentativen US-Stichprobe (Stagnaro u. a. 2023, n = 2.355) fand ebenfalls keine Verstärkung durch Rechenkönnen, wohl aber um 9,3 Prozentpunkte häufiger richtige Antworten bei einem zur eigenen Politik passenden Ergebnis. Die Originalstudie ließ sich also nur teilweise wiederholen: Die Kernaussage „Weltanschauung färbt die Datenauswertung“ ist besser gestützt als der Zusatz „Rechenkönnen verstärkt das“, und als Beleg für „Logik als Anwalt der Identität“ taugt der Befund nur mit diesem Vorbehalt.","coreRule":"⚡ Ein Befund ist nur so belastbar wie seine Wiederholung: Was sich nur teilweise bestätigt, darf nur teilweise behauptet werden.","beleg":"Werkstück H.1.1 (Kontext & Tiefe); Fn. gl-h-motiviert (Kahan u. a. 2017, Behavioural Public Policy 1(1), S. 54–86; Persson u. a. 2021, Cognition 214, Art. 104768, S. 1 und 6)","status":"entwurf","scenario":"Eine Forscherin schreibt in einem Aufsatz: „Rechenkönnen verstärkt die weltanschauliche Färbung; die Logik wechselt die Seite, wenn die Identität bedroht ist.“ Als Beleg nennt sie ein Experiment mit einer Vierfeldertafel: Bei einer neutralen Hautcreme-Aufgabe schnitten die Rechenstärksten deutlich besser ab, bei derselben Aufgabe zu einem Waffenverbot spaltete sich die Auswertung politisch, bei den Rechenstarken sogar stärker. Eine große vorregistrierte Wiederholung mit 3.154 Teilnehmern fand die politische Färbung zum Teil wieder, die Verstärkung durch Rechenkönnen aber nicht. Eine zweite vorregistrierte Wiederholung mit 2.355 Personen fand ebenfalls keine Verstärkung durch Rechenkönnen, aber um 9,3 Prozentpunkte häufiger richtige Antworten, wenn das Ergebnis zur eigenen Politik passte.","kurz":"Ein Befund ist nur so belastbar wie seine Wiederholung. Die weltanschauliche Färbung fand sich zumindest teilweise wieder, die Verstärkung durch Rechenkönnen in beiden großen Wiederholungen nicht. Der Satz sollte sich daher auf die Färbung beschränken.","prueffrage":"Welche Teile der Aussage haben sich in neuen, unabhängigen Erhebungen wiedergefunden, welche nicht?","rueckmeldung":[{"option":0,"text":"Dass Original und Wiederholungen beim Rechenkönnen verschiedene Ergebnisse liefern, stimmt. Zwei große vorregistrierte Wiederholungen ohne Verstärkung sind aber mehr als ein offener Streit, und ein Vermerk „umstritten“ trennt nicht den gestützten Teil des Satzes vom ungestützten."},{"option":2,"text":"Dass fehlende Belege einen Effekt nicht ausschließen, stimmt. Ein „kann“ bliebe aber bei einer Aussage, für die beide großen Wiederholungen nichts fanden, und klingt, als sei sie gestützt. Der Satz sollte sich daran halten, was die Wiederholungen tatsächlich tragen."},{"option":3,"text":"Die Verstärkung durch Rechenkönnen wurde zweimal nicht bestätigt, das stimmt. Der Satz enthält aber auch die Färbung, die sich zumindest teilweise wiederfand. Ihn ganz zu streichen, würde den gestützten Teil mit verwerfen, und „nicht bestätigt“ heißt auch nicht „widerlegt“."}],"familie":"wiederholung-abwarten","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Stagnaro, Tappin & Rand (2023): No association between numerical ability and politically motivated reasoning in a large US probability sample. PNAS 120(32), e2301491120","oeffentlich":true,"doi":"10.1073/pnas.2301491120","abruf":"2026-10-12"},{"typ":"doi","kurz":"Persson, Andersson, Koppel, Västfjäll & Tinghög (2021): A preregistered replication of motivated numeracy. Cognition 214, 104768","oeffentlich":true,"doi":"10.1016/j.cognition.2021.104768","abruf":"2026-10-12"},{"typ":"doi","kurz":"Kahan, Peters, Dawson & Slovic (2017): Motivated numeracy and enlightened self-government. Behavioural Public Policy 1(1), 54–86","oeffentlich":false,"doi":"10.1017/bpp.2016.2","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v9","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"28b892285184d577"}},{"id":"qx-h-012","clusterId":"H","werkstueckRef":"H.1.1","stufe":3,"question":"Wie gehst du mit dem Vorschlag deines Freundes um?","scenario":"Du schreibst einen Text mit dem Kernsatz: „Meine Idee ist etwas, das ich habe, nicht etwas, das ich bin.“ Ein Freund aus der Psychologie schlägt vor, dafür den Fachbegriff „kognitive Entkopplung“ von Keith Stanovich zu verwenden, das sei genau dasselbe. Du schlägst nach: Stanovich versteht unter „cognitive decoupling“ die Fähigkeit, probeweise Annahmen von der Vorstellung der wirklichen Welt getrennt zu halten und die schnelle, automatische Antwort zu übersteuern.","options":["Du übernimmst den Begriff, weil Stanovich damit wie dein Satz das Lösen der eigenen Identität von den eigenen Überzeugungen meint.","Du übernimmst den Begriff, weil Stanovich damit wie dein Satz das Trennen von Gefühl und Verstand beim Nachdenken über eigene Ideen meint.","Du verzichtest auf den Begriff, weil Stanovich damit zwar dasselbe meint wie dein Satz, das Fachwort für Laien aber zu sperrig ist.","Du verzichtest auf den Begriff, weil Stanovich damit das Trennen von Annahmen und Welt meint, nicht das Lösen des Selbst von Ideen."],"correctIndex":3,"explanation":"Ein gleicher Name sagt noch nichts über eine gleiche Sache. Bei Stanovich bedeutet „cognitive decoupling“, probeweise Annahmen von der Vorstellung der wirklichen Welt getrennt zu halten und die schnelle, automatische Antwort zu übersteuern; das ist eine Denkfähigkeit beim probeweisen Durchspielen von Annahmen. Dein Satz meint etwas anderes: Selbstwert und Identität von den eigenen Überzeugungen zu lösen, betrifft das Verhältnis zu den eigenen Ideen, nicht das Durchspielen von Annahmen. Näher kommen dem zwei Begriffe aus der Akzeptanz- und Commitment-Therapie, die „kognitive Defusion“ (Gedanken als Gedanken bemerken, statt sie wörtlich zu nehmen) und das „Selbst als Kontext“ (die Bindung an die eigene Selbsterzählung lockern). Dass Stanovich das Lösen der Identität meine, steht nicht in seiner Definition, und von Gefühl und Verstand ist dort ebenfalls keine Rede. Mit „zu sperrig“ zu verzichten wirkt umsichtig, beruht aber auf der falschen Annahme, beide meinten dasselbe.","coreRule":"⚡ Prüfe bei Fachbegriffen, ob derselbe Name dieselbe Bedeutung trägt.","beleg":"Werkstück H.1.1; Fn. gl-h-entkopplung (nach Woods 2012, Informal Logic 32(3), S. 375 f., zu Stanovich: Rationality and the Reflective Mind, 2011); Anmerkung anm-gl-h-entkopplung","status":"entwurf","kurz":"Der Begriff passt nicht: Stanovich meint das Trennen probeweiser Annahmen von der wirklichen Welt, dein Satz das Lösen des Selbst von Ideen. Ein gleicher Name macht noch keine gleiche Sache.","prueffrage":"Was genau wird in Stanovichs Definition wovon getrennt, und was in deinem Kernsatz?","rueckmeldung":[{"option":0,"text":"Dein Satz meint tatsächlich das Lösen der Identität von Überzeugungen. Das steht aber nicht in Stanovichs Definition: Bei ihm geht es um probeweise Annahmen und die Vorstellung der wirklichen Welt, nicht um das Selbst."},{"option":1,"text":"Von Gefühl und Verstand ist in Stanovichs Definition keine Rede. Er meint, Annahmen probeweise von der Wirklichkeit getrennt zu halten und die automatische Antwort zu übersteuern. Dein Satz betrifft das Verhältnis zur eigenen Idee."},{"option":2,"text":"Auf den Begriff zu verzichten ist richtig, der Grund aber nicht. Es geht nicht um Sperrigkeit für Laien, sondern darum, dass beide nicht dasselbe meinen: Das Fachwort würde deinen Satz falsch fassen."}],"familie":"begriff-messbar-machen","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Woods, C. (2012): Rezension zu Stanovich, Rationality and the Reflective Mind. Informal Logic 32(3), 373–380","oeffentlich":true,"doi":"10.22329/il.v32i3.3721","abruf":"2026-10-12"},{"typ":"url","kurz":"Hayes, Levin, Plumb-Vilardaga, Villatte & Pistorello (2013): Acceptance and Commitment Therapy and Contextual Behavioral Science. Behavior Therapy 44(2) (PMC-Fassung)","oeffentlich":true,"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC3635495/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Evans, J. St. B. T. & Stanovich, K. E. (2013): Dual-Process Theories of Higher Cognition: Advancing the Debate. Perspectives on Psychological Science 8(3), 223–241","oeffentlich":false}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"8ce307ed50874059"}},{"id":"qx-h-013","clusterId":"H","werkstueckRef":"H.1.2","stufe":1,"question":"Jemand beschreibt seinen Alltag so: „Ich korrigiere jeden falschen Kommentar, den ich sehe, und diskutiere mit jedem, der Unsinn verbreitet. Inzwischen bin ich nach den Diskussionen ständig erschöpft und wütend, und für das Gespräch mit meinem Vater, der gerade eine ärztlich empfohlene Behandlung ablehnen will, habe ich kaum noch Kraft.“ Welche Schlussfolgerung ist am besten begründet?","options":["Er sollte seine Korrekturen freundlicher formulieren, weil ein sachlicher Ton die Chance erhöht, dass die Diskussionspartner Argumente annehmen.","Er sollte seine Kraft nach Dringlichkeit einteilen, weil das Gespräch mit seinem Vater, wo ein echter Schaden droht, Vorrang vor den Kommentaren hat.","Er sollte vor jeder Korrektur die eigene Quelle gegenprüfen, weil auch gut gemeinte Richtigstellungen in den Kommentaren selbst fehlerhaft sein können.","Er sollte seine Wut nach den Diskussionen als Hinweis auf eigene Voreingenommenheit prüfen, weil starke Gefühle oft zeigen, dass man nicht neutral urteilt."],"correctIndex":1,"explanation":"Mentale und emotionale Energie ist begrenzt. Wer jeden Irrtum sofort bekämpft, hat am Ende keine Kraft mehr für die Situation, in der Nichtstun echten Schaden anrichtet, hier die drohende Ablehnung einer ärztlich empfohlenen Behandlung. Sinnvoll ist eine Triage: Wo unmittelbarer Schaden droht, lohnt sich der volle Einsatz. Wo ein Gespräch noch offen und konstruktiv wirkt, kann man vorsichtig Energie investieren. Bei aussichtslosen Streitereien spart man sie. Die anderen Gedanken sind für sich vernünftig, lösen aber das geschilderte Problem nicht: Ein freundlicher Ton erhöht die Chance auf Gehör, ändert aber nichts daran, dass die Kraft schon aufgebraucht ist. Die eigene Quelle zu prüfen ist guter Stil, doch das Problem sind nicht fehlerhafte Korrekturen, sondern Überlastung. Die Wut als Signal zu lesen kann aufschlussreich sein, verteilt die begrenzte Kraft aber nicht neu.","coreRule":"⚡ Energie ist begrenzt: erst einteilen, dann kämpfen.","quote":"","quoteLabel":"","beleg":"Werkstück H.1.2 (Die Geschichte; Kernidee; Kontext & Tiefe)","status":"entwurf","scenario":"","kurz":"Wer jeden Irrtum bekämpft, hat für den Ernstfall keine Kraft mehr. Hier droht beim Vater echter Schaden, also verdient dieses Gespräch den vollen Einsatz, während aussichtslose Kommentarstreits Energie sparen dürfen.","prueffrage":"Was geschieht in den kommenden Wochen, wenn er so weitermacht wie bisher?","rueckmeldung":[{"option":0,"text":"Ein sachlicher Ton erhöht die Chance, dass Argumente ankommen. Die Erschöpfung ändert er aber nicht: Mit freundlicheren Korrekturen bliebe die Kraft trotzdem im Kommentarstreit stecken und fehlte weiter beim Vater."},{"option":2,"text":"Die eigene Quelle zu prüfen ist guter Stil, doch im Szenario fehlt jeder Hinweis, dass seine Korrekturen fehlerhaft wären. Das Problem ist die Überlastung durch zu viele Diskussionen, nicht die Qualität der einzelnen Richtigstellung."},{"option":3,"text":"Wut kann tatsächlich etwas über die eigene Haltung verraten. Hier erklärt sie sich aber schon durch die ständigen Diskussionen und die Erschöpfung. Sie zu deuten schafft keine Kraft für das Gespräch mit dem Vater."}],"familie":"kraefte-und-ausstieg","fertigkeit":"F3","thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"55fcd032cc2581b9"}},{"id":"qx-h-014","clusterId":"H","werkstueckRef":"H.1.2","stufe":2,"question":"In welcher dieser Situationen ist es am besten begründet, deine Energie voll einzusetzen, auch wenn es anstrengend wird?","scenario":"Du hast nur begrenzt Kraft für Auseinandersetzungen und musst sie einteilen. Drei Situationen stehen an: (1) Ein anonymer Kommentator unter einem Video behauptet Unsinn und beschimpft jeden, der widerspricht. (2) Ein Kollege fragt dich ehrlich, ob an einer Gesundheitsmeldung etwas dran ist, und wirkt unsicher. (3) Dein Onkel will eine ärztlich empfohlene, lebensrettende Behandlung absagen und stattdessen auf eine unbewiesene Methode setzen.","options":["Beim Kommentator, weil seine Behauptung öffentlich steht und ein Widerspruch dort viele Mitlesende erreicht.","Beim Kollegen, weil er ehrlich fragt und offen ist, sodass sich der Aufwand bei ihm am ehesten auszahlt.","Beim Onkel, weil hier Nichtstun direkten Schaden anrichtet und sich der volle Einsatz daher am meisten lohnt.","Beim Kommentator, weil Unsinn, der unwidersprochen stehen bleibt, für Mitlesende wie eine anerkannte Tatsache wirkt."],"correctIndex":2,"explanation":"Wer seine Kräfte einteilt, fragt: Wo richtet Nichtstun direkten, unmittelbaren Schaden an? Beim Onkel will ein naher Angehöriger eine lebensrettende Behandlung zugunsten von Pseudomedizin ablehnen. Hier schadet Untätigkeit direkt, und das rechtfertigt vollen Einsatz, auch wenn er anstrengt.","coreRule":"⚡ Wo Nichtstun unmittelbaren Schaden anrichtet, lohnt der volle Einsatz.","beleg":"Werkstück H.1.2 (Kontext & Tiefe: Triage, Kategorie 1 „Die Schlachten, die man kämpfen muss“; Geschichte vom Feuerwehrmann)","status":"freigegeben","freigabe":{"datum":"2026-10-15","pruefsumme":"fffb11622a717bcb","vermerk":"Prüfpult (Sturm, erste Charge nach den neuen falschen Optionen)"},"kurz":"Maßgeblich ist, wo Nichtstun direkten Schaden anrichtet, und das ist beim Onkel der Fall, wenn er eine lebensrettende Behandlung absagt. Wer nur auf Reichweite oder Erfolgsaussicht schaut, übersieht, was auf dem Spiel steht.","prueffrage":"Was steht in jeder der drei Situationen konkret auf dem Spiel, und für wen?","rueckmeldung":[{"option":0,"text":"Ein öffentlicher Kommentar erreicht tatsächlich viele Menschen. Der Schaden durch einen einzelnen Unsinnskommentar ist aber diffus, und wer jeden Widerspruch beschimpft, lässt sich selten überzeugen. Das rechtfertigt nicht den vollen Einsatz."},{"option":1,"text":"Dass der Kollege ehrlich fragt und offen ist, stimmt, und dort lohnt sich ein Gespräch. Doch er unsicher nachfragt, ohne dass ihm unmittelbar etwas droht; die Erfolgsaussicht allein macht den Einsatz noch nicht am besten begründet."},{"option":3,"text":"Unwidersprochener Unsinn kann Mitlesenden glaubwürdiger erscheinen, aber das ist eher eine Möglichkeit als ein sicherer, unmittelbarer Schaden. Ein Wortgefecht mit einem Beschimpfer kostet viel Kraft und bringt vermutlich wenig."}],"familie":"kraefte-und-ausstieg","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Lewandowsky & Cook (2020): The Conspiracy Theory Handbook, Abschnitt „How to talk to a conspiracy theorist“","oeffentlich":true,"url":"https://skepticalscience.com/docs/ConspiracyTheoryHandbook.pdf","seite":"10","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v9","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"ok","pruefsumme":"fffb11622a717bcb"}},{"id":"qx-h-015","clusterId":"H","werkstueckRef":"H.1.2","stufe":2,"question":"Welches Ziel für den nächsten Besuch ist vernünftig, und warum?","scenario":"Dein Vater hat sich in einen Mythos vertieft. Zwei längere Gespräche endeten im Streit, ohne dass er sich bewegt hat. Beim nächsten Besuch überlegst du, ob du wieder diskutierst.","options":["Ihm eine Liste mit Aussagen von Fachleuten mitzubringen, damit er die Übermacht der Belege gegen den Mythos erkennt.","Die Beziehung zu deinem Vater zu halten und den Mythos diesmal nicht anzusprechen, damit das Vertrauen nach den zwei Streitgesprächen nicht weiter leidet.","Dich vorab so gründlich über den Mythos zu informieren, dass du seine Argumente beim Besuch lückenlos widerlegen kannst.","Vor der übrigen Familie klarzustellen, was am Mythos falsch ist, damit sie nicht wie dein Vater darauf hereinfällt."],"correctIndex":1,"explanation":"Maßstab ist, was im Familiengespräch wirklich zählt. Das Ziel ist oft nicht, die Person in einer einzigen Diskussion zu überzeugen, sondern die Beziehung zu erhalten und ein langfristiger, vertrauenswürdiger Ansprechpartner zu bleiben. Dazu gehört zu wissen, wann man ein Thema ruhen lassen muss, um die emotionale Verbindung nicht zu zerstören. Die anderen Ziele klingen für sich brauchbar, passen aber nicht: Weitere Belege oder Fachmeinungen vorzulegen setzt fort, was in zwei Gesprächen schon nichts bewegt hat. Bessere Vorbereitung hilft, wenn Wissen fehlt, ändert aber am Streitmuster zwischen euch wenig. Andere vor einem Mythos zu schützen ist ein gutes Ziel, wenn Dritte betroffen sind, hier geht es aber nur um deinen Vater.","coreRule":"⚡ In der Familie zählt zuerst die Verbindung, nicht der Sieg im Gespräch.","beleg":"Werkstück H.1.2 (Anwendung & Relevanz: ‚Bei Familiengesprächen („Mann über Bord“)‘)","status":"entwurf","kurz":"Wenn zwei Gespräche nichts bewegt haben, hilft ein dritter Anlauf kaum. Wichtiger ist, die Beziehung zu halten und ein vertrauenswürdiger Ansprechpartner zu bleiben. Dafür kann es nötig sein, ein Thema ruhen zu lassen.","prueffrage":"Was haben die beiden langen Gespräche an der Meinung deines Vaters bewirkt, und wie endeten sie?","rueckmeldung":[{"option":0,"text":"Eine Liste mit Fachaussagen wirkt sachlich und gründlich. Doch in zwei Gesprächen hat es schon nichts bewegt, mehr Belege vorzulegen, und noch einmal dasselbe zu versuchen führt vermutlich zum selben Streit."},{"option":2,"text":"Gute Vorbereitung hilft, wenn Wissen fehlt. Hier fehlt es aber nicht an Wissen, sondern es hakt im Streitmuster zwischen euch. Wer auf lückenloses Widerlegen zielt, verfolgt weiter das Gewinnen und nicht den Draht zu deinem Vater."},{"option":3,"text":"Andere vor einem Mythos zu schützen ist ein gutes Ziel, wenn Dritte betroffen sind. In deiner Lage geht es aber nur um deinen Vater, und vor der Familie Klarstellungen zu machen löst das Problem zwischen euch nicht."}],"familie":"kraefte-und-ausstieg","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Lewandowsky & Cook (2020): The Conspiracy Theory Handbook, Abschnitt „How to talk to a conspiracy theorist“","oeffentlich":true,"url":"https://skepticalscience.com/docs/ConspiracyTheoryHandbook.pdf","seite":"10","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"87617618c50af70c"}},{"id":"qx-h-016","clusterId":"H","werkstueckRef":"H.1.2","stufe":3,"question":"Was ist hier die klügste Schlussfolgerung, und warum?","scenario":"Du diskutierst seit Wochen regelmäßig online mit Leuten über Verschwörungsmythen. Du merkst: Nach den Diskussionen bist du oft erschöpft, wütend und hoffnungslos, deine Antworten werden zynischer und aggressiver, und andere Dinge in deinem Leben kommen zu kurz. Überzeugt hast du bisher niemanden.","options":["Deine Wut zeigt, wie wichtig dir das Thema ist. Du solltest durchhalten, denn Überzeugen braucht Zeit, und wer aufgibt, überlässt den Mythen das Feld.","Deine Mühe hat bisher niemanden überzeugt, die Debatten bringen also wenig. Du solltest dich aus ihnen zurückziehen und das Thema anderen überlassen.","Deine Antworten werden zynischer und aggressiver. Du solltest an deinem Ton arbeiten und ruhiger antworten, damit die Diskussionen besser verlaufen.","Deine Kraft ist begrenzt und wird gerade verbraucht. Du solltest neu einteilen, welche Debatten sich lohnen, und aus den übrigen aussteigen."],"correctIndex":3,"explanation":"Erschöpfung, Wut, Hoffnungslosigkeit, wachsender Zynismus und vernachlässigte andere Lebensbereiche sind typische Warnzeichen für Überlastung. Mentale und emotionale Energie ist begrenzt, und wer an jeder Front kämpft, brennt aus und hat dann für die wirklich wichtigen Auseinandersetzungen keine Kraft mehr. Vernünftig ist eine Triage: Muss ich diesen Kampf führen (etwa weil Untätigkeit direkten Schaden anrichtet), kann ich ihn sinnvoll führen (das Gegenüber fragt ehrlich nach) oder sollte ich ihn vermeiden (Trolle, Ideologen, reines Gewinnen-Wollen)? Bei Gegenübern, die nur gewinnen wollen, ist jede investierte Energie vergeblich, wie Wasser in ein Fass ohne Boden. Dazu gehört auch, Debatten zu verlassen oder Feeds stummzuschalten.","coreRule":"⚡ Erschöpfung ist ein Signal zum Umplanen, kein Beweis für Einsatz.","beleg":"Werkstück H.1.2 (Red Flags; Die Schmiede-Übung: Das Energie-Audit; Anwendung & Relevanz)","status":"entwurf","kurz":"Erschöpfung, Wut und wachsender Zynismus zeigen, dass deine begrenzte Kraft gerade verbraucht wird. Naheliegend ist, entweder weiterzukämpfen oder nur den Ton zu ändern; klüger ist, auszuwählen, welche Debatten sich lohnen.","prueffrage":"Was hat dir der bisherige Einsatz gebracht, und was hat er dich gekostet?","rueckmeldung":[{"option":0,"text":"Dass dich das Thema so aufwühlt, zeigt tatsächlich, wie wichtig es dir ist. Genau diese Wut, zusammen mit Erschöpfung und Hoffnungslosigkeit, ist aber ein Warnzeichen für Überlastung, und wer überall kämpft, hat für die wichtigen Fälle bald keine Kraft mehr."},{"option":1,"text":"Bei manchen Gegenübern ist Aussteigen klug, nämlich wenn es nur ums Gewinnen geht. Das gilt aber nicht für jede Debatte: Wer ehrlich fragt oder wo Untätigkeit Schaden anrichtet, kann ein Gespräch lohnen. Es geht um Auswahl, nicht um Totalrückzug."},{"option":2,"text":"Ein ruhigerer Ton kann nicht schaden. Der wachsende Zynismus ist hier aber eher ein Symptom der Überlastung als ihre Ursache, und gegenüber Leuten, die nur gewinnen wollen, hilft auch der freundlichste Ton nicht. Das eigentliche Problem bleibt bestehen."}],"familie":"kraefte-und-ausstieg","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"WHO (2019): Burn-out an „occupational phenomenon“: International Classification of Diseases","oeffentlich":true,"url":"https://www.who.int/news/item/28-05-2019-burn-out-an-occupational-phenomenon-international-classification-of-diseases","abruf":"2026-10-12"},{"typ":"url","kurz":"Lewandowsky & Cook (2020): The Conspiracy Theory Handbook, Abschnitt „How to talk to a conspiracy theorist“","oeffentlich":true,"url":"https://skepticalscience.com/docs/ConspiracyTheoryHandbook.pdf","seite":"10","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"e7425107599aadb1"}},{"id":"qx-h-017","clusterId":"H","werkstueckRef":"H.1.3","stufe":1,"question":"Was macht Jonas anders, und was ändert das für das Gespräch?","options":["Er unterstellt dem Patienten eine gute Absicht, nämlich Sorge um seine Gesundheit, und prüft dann das Bleichmittel mit ihm gemeinsam. So bleibt der Patient gesprächsbereit.","Er spricht freundlicher als Lena und verzichtet auf jede Beleidigung. So fühlt sich der Patient nicht angegriffen, und schon der ruhige Ton macht ihn für Einwände zugänglich.","Er nimmt die Überzeugung des Patienten ernst und lässt sie als dessen Sicht gelten. So fühlt sich der Patient respektiert und muss seine Meinung nicht mehr verteidigen.","Er lässt den Patienten selbst herausfinden, was Bleichmittel bewirkt, statt es ihm zu sagen. So hält der Patient die Einsicht für seine eigene und hält eher an ihr fest."],"correctIndex":0,"explanation":"Jonas deutet das Motiv des Patienten wohlwollend (Sorge um die Gesundheit) und greift trotzdem die Idee an, nicht die Person. Wer sich verachtet fühlt, schaltet auf Verteidigung und hört nicht mehr zu; wer sich in seinen guten Absichten verstanden fühlt, ist eher bereit, Gegenargumente zu prüfen. Die Sachprüfung bleibt dabei vollständig erhalten: Wohlwollen gegenüber dem Motiv ersetzt weder die Kritik noch die Fakten. Das Prinzip ergänzt das logische Stahlmann-Argument um die Ebene der Motive; es ersetzt die sachliche Prüfung nicht.","coreRule":"⚡ Deute das Motiv wohlwollend, prüfe die Idee trotzdem hart: Barmherzigkeit gilt der Person, nicht der falschen Behauptung.","beleg":"Werkstück H.1.3 (Kernidee; Kontext & Tiefe)","status":"entwurf","scenario":"Ein Patient will Bleichmittel trinken, weil er fest überzeugt ist, dass es ihn von einer Krankheit heilt. Ärztin Lena reagiert: „Wie kann man nur so dumm sein?“ Arzt Jonas sagt: „Du willst unbedingt gesund werden, das verstehe ich. Lass uns gemeinsam prüfen, was Bleichmittel im Körper bewirkt.“","kurz":"Jonas deutet das Motiv wohlwollend (Sorge um die Gesundheit) und prüft trotzdem die Idee. Wer sich verachtet fühlt, verteidigt sich; wer sich in seiner guten Absicht verstanden fühlt, ist eher bereit, Gegenargumente zu prüfen.","prueffrage":"Worauf zielt jede der beiden Reaktionen: auf den Patienten als Person oder auf seine Idee?","rueckmeldung":[{"option":1,"text":"Der ruhige Ton ohne Beleidigung hilft, das stimmt. Entscheidend ist aber, was Jonas inhaltlich tut: Er deutet das Motiv wohlwollend und prüft die Idee. Freundlichkeit allein macht noch niemanden sicher zugänglich."},{"option":2,"text":"Respekt vor dem Menschen ist wichtig. Jonas lässt die Überzeugung aber gerade nicht als bloße Sicht stehen, sondern will sie mit dem Patienten prüfen. Wohlwollen gilt dem Motiv, die Kritik an der Idee bleibt."},{"option":3,"text":"Im Szenario schlägt Jonas vor, gemeinsam zu prüfen, nicht den Patienten allein suchen zu lassen. Und dass er die Einsicht dann als eigene sieht und eher daran festhält, wird nirgends behauptet. Der Gewinn liegt im Wohlwollen gegenüber dem Motiv."}],"familie":"wohlwollend-verstehen","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Lewandowsky & Cook (2020): The Conspiracy Theory Handbook, Abschnitt „How to talk to a conspiracy theorist“","oeffentlich":true,"url":"https://skepticalscience.com/docs/ConspiracyTheoryHandbook.pdf","seite":"10","abruf":"2026-10-12"},{"typ":"url","kurz":"Malpas, J.: Donald Davidson. Stanford Encyclopedia of Philosophy (rev. 28.04.2023), Abschnitt 3.3","oeffentlich":true,"url":"https://plato.stanford.edu/entries/davidson/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v9","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"14f53e96d32f3b4e"}},{"id":"qx-h-018","clusterId":"H","werkstueckRef":"H.1.3","stufe":2,"question":"Du willst deinen Onkel verstehen, bevor du widersprichst, ohne seine Position gutzuheißen. Von welcher Annahme gehst du dafür am besten aus?","scenario":"Im Familienchat verteidigt dein Onkel eine politische Position, die du für schädlich hältst. Du ertappst dich beim Gedanken: „Der will doch nur das Land zerstören.“ Du willst ihm trotzdem fair begegnen, ohne deine Kritik aufzugeben.","options":["Er kennt wohl die Folgen seiner Position nicht, darum muss ich ihm vor allem die Fakten dazu erklären.","Er übernimmt wohl nur die Meinung seines Umfelds, darum sagt seine Position mehr über die Gruppe als über ihn.","Er will wohl wie ich, dass es dem Land gut geht, hält aber einen anderen Weg dorthin für den richtigen.","Er hat wohl eigene Gründe dafür, darum ist seine Position aus seiner Sicht so berechtigt wie meine aus meiner."],"correctIndex":2,"explanation":"Wer die Position eines anderen verstehen will, deutet seine Motive zuerst im bestmöglichen Licht: gemeinsame Ziele, andere Mittel. Das ist eine plausible Annahme, und sie lässt zu, dass du die Position weiterhin für falsch und schädlich hältst. Schlechte Motive wie Eigennutz zu unterstellen, ohne es beweisen zu können, ist genau die Dämonisierung, die man vermeiden will.","coreRule":"⚡ Wohlwollend deuten heißt nicht, die Position gutzuheißen.","beleg":"Werkstück H.1.3 (Anwendung & Relevanz: ‚Im politischen Diskurs‘; Kipppunkt; Red Flags)","status":"entwurf","kurz":"Am besten nimmst du an, dass er dasselbe Ziel hat wie du, nämlich dass es dem Land gut geht, und nur einen anderen Weg für richtig hält. So verstehst du ihn im bestmöglichen Licht, kannst seine Position aber weiter für falsch halten. Böse Absichten ohne Beleg zu unterstellen, wäre Dämonisierung.","prueffrage":"Welche Sorgen oder Erfahrungen könnten deinen Onkel zu dieser Position gebracht haben?","rueckmeldung":[{"option":0,"text":"Fakten können später helfen, und manchmal fehlt tatsächlich Wissen. Als Ausgangsannahme unterstellst du ihm aber Unwissenheit, ohne es zu wissen, und wirst eher belehren als verstehen. Zuerst geht es um sein Motiv."},{"option":1,"text":"Dass das Umfeld Meinungen prägt, kommt oft vor. Als Grundannahme erklärt es aber seine Gründe nicht und nimmt ihn als Person nicht ernst. Du behandelst ihn wie ein Sprachrohr, ohne etwas dafür zu haben."},{"option":3,"text":"Dass er eigene Gründe hat, ist plausibel. Dass seine Position deshalb so berechtigt sei wie deine, folgt daraus aber nicht und würde deine Kritik aufgeben. Außerdem bleibt offen, welches Motiv du ihm zutraust: gemeinsames Ziel, anderer Weg."}],"familie":"wohlwollend-verstehen","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Malpas, J.: Donald Davidson. Stanford Encyclopedia of Philosophy (rev. 28.04.2023), Abschnitt 3.3","oeffentlich":true,"url":"https://plato.stanford.edu/entries/davidson/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Bowell, T. & Kemp, G. (2002): Critical Thinking: A Concise Guide. London: Routledge","oeffentlich":false}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"ok","pruefsumme":"0855812b57f29937"}},{"id":"qx-h-019","clusterId":"H","werkstueckRef":"H.1.3","stufe":3,"question":"Was ist an dem Einwand des Freundes problematisch?","scenario":"Ein Redner schürt seit Jahren systematisch Hass gegen eine Gruppe. Du bezeichnest sein Verhalten als gefährlich. Ein Freund widerspricht: „Wir müssen barmherzig sein und von guten Absichten ausgehen.“","options":["Er macht aus wohlwollender Deutung eine Regel, die auch nach Jahren systematischer Hetze gegen die Gruppe durch keine Beobachtung mehr zu erschüttern ist.","Er verlangt von dir Barmherzigkeit, nicht aber vom Redner gegenüber der Gruppe, und misst damit dein Urteil und dessen jahrelange Hetze mit zweierlei Maß.","Er verwechselt Barmherzigkeit mit Billigung, denn wer dem Redner gute Absichten zuschreibt, heißt damit im Ergebnis auch dessen Hetze gegen die Gruppe gut.","Er verlangt etwas, das sich nicht einlösen lässt, denn die Absichten anderer bleiben verborgen, und wohlwollende Deutung ist darum von vornherein bloßes Raten."],"correctIndex":0,"explanation":"Das Prinzip der Barmherzigkeit gilt, bis das Gegenteil bewiesen ist. Wer systematisch Hass schürt, liefert genau dieses Gegenteil: Dann ist es nicht mehr barmherzig, sondern naiv, weiter von guten Absichten auszugehen. Beurteilt werden in diesem Fall die Handlungen, nicht die vermuteten Absichten. Der Fehler des Freundes liegt also darin, eine Ausgangsannahme in eine Regel zu verwandeln, die keine Beobachtung mehr korrigieren kann.","coreRule":"⚡ Wohlwollende Deutung gilt, bis das Verhalten das Gegenteil zeigt; dann zählen die Handlungen, nicht vermutete Absichten.","quote":"Das Prinzip der Barmherzigkeit gilt, bis das Gegenteil bewiesen ist.","quoteLabel":"Merksatz:","beleg":"Werkstück H.1.3 (Der Kipppunkt)","status":"entwurf","kurz":"Barmherzigkeit ist ein Startpunkt, der gilt, bis Gegenteiliges vorliegt. Jahrelange systematische Hetze ist solch ein Gegenteil. Wer trotzdem an guten Absichten festhält, macht daraus eine Regel, die keine Beobachtung mehr korrigiert, und das ist arglos, nicht barmherzig.","prueffrage":"Was weiß man über den Redner aus seinem Handeln, und was wird über ihn nur vermutet?","rueckmeldung":[{"option":1,"text":"Dass der Redner der Gruppe keine Barmherzigkeit zeigt, stimmt. Davon handelt der Einwand des Freundes aber nicht: Er verlangt Wohlwollen als Grundsatz, ohne dich oder den Redner unterschiedlich zu messen. Das Problem liegt woanders."},{"option":2,"text":"Barmherzig zu deuten heißt nicht, Taten gutzuheißen; man kann Absichten wohlwollend annehmen und die Handlungen trotzdem klar ablehnen. Das Problem ist ein anderes: Die Annahme soll auch gelten, wenn alles gegen sie spricht."},{"option":3,"text":"Absichten sind nicht direkt sichtbar, lassen sich aber aus wiederholtem Handeln begründet erschließen. Wohlwollend zu deuten ist als Ausgangspunkt sinnvoll und kein bloßes Raten. Fragwürdig wird es erst, wenn die Annahme gegen jede Beobachtung verteidigt wird."}],"familie":"wohlwollend-verstehen","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Malpas, J.: Donald Davidson. Stanford Encyclopedia of Philosophy (rev. 28.04.2023), Abschnitt 3.3","oeffentlich":true,"url":"https://plato.stanford.edu/entries/davidson/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"ok","pruefsumme":"2e9a203e55dfb3ff"}},{"id":"qx-h-020","clusterId":"H","werkstueckRef":"H.1.3","stufe":4,"question":"Wie bewertest du die Rüge der Trainerin?","options":["Halb berechtigt: Kai hat gegen Regel B verstoßen, Regel A aber erfüllt; Deutung der Aussage und Annahme über das Motiv sind getrennte Schritte.","Berechtigt: Wer eine Aussage wohlwollend deutet, unterstellt damit auch gute Motive; Kais Verdacht zeigt, dass seine Deutung nicht wohlwollend war.","Unberechtigt: Kai hat beide Regeln erfüllt, denn ein Verdacht gegen das Motiv ist erlaubt, solange die Aussage selbst wohlwollend gedeutet wird.","Halb berechtigt: Kai hat gegen Regel A verstoßen, Regel B aber erfüllt; wer ein Motiv hinterfragt, deutet die Aussage zwangsläufig nicht wohlwollend."],"correctIndex":0,"explanation":"Wohlwollende Deutung der Aussage und wohlwollende Annahme über das Motiv sind zwei getrennte Dinge. Regel A entspricht der sprachphilosophischen Fassung des Prinzips der Nachsicht (Donald Davidson): einem Sprecher wo immer plausibel wahre und in sich stimmige Überzeugungen unterstellen. Regel B betrifft dagegen die Annahme, jemand handle aus guten Beweggründen; das Prinzip der intellektuellen Barmherzigkeit erweitert den Fachbegriff bewusst um diese Motivebene. Kai hat das Argument in seiner stärksten, stimmigen Form wiedergegeben und damit Regel A erfüllt; mit seinem Verdacht gegen das Motiv hat er Regel B verletzt. Man kann eine Aussage wohlwollend deuten und die Motive trotzdem für fragwürdig halten, deshalb ist die Rüge nur zur Hälfte berechtigt. Die volle Rüge setzt voraus, dass Deutung und Motivannahme zusammenfallen, was sie nicht tun. „Beide Regeln erfüllt“ übersieht, dass Regel B ausdrücklich gute Motive verlangt, und ein Verstoß gegen Regel A widerspricht Kais tatsächlich wohlwollender Wiedergabe.","coreRule":"⚡ Die Aussage wohlwollend deuten und gute Motive unterstellen sind zwei verschiedene Schritte, die man getrennt prüfen kann.","beleg":"Werkstück H.1.3 (Kontext & Tiefe); Fn. gl-h-charity (Malpas, Stanford Encyclopedia of Philosophy, „Donald Davidson“, Abschn. 3.3)","status":"entwurf","scenario":"Ein Debattierclub hat zwei Regeln für den Umgang mit Gegnern. Regel A: Deute die Aussage des Gegners so, dass er, wo immer plausibel, wahre und in sich stimmige Überzeugungen hat. Regel B: Unterstelle ihm gute Motive. Kai gibt das Argument seines Gegners in dessen stärkster, stimmiger Form wieder und sagt dann: „Ich vermute trotzdem, er vertritt das nur, um seinen Arbeitgeber zu schützen.“ Die Trainerin rügt: „Mit diesem Verdacht ist auch deine Wiedergabe des Arguments nicht mehr wohlwollend.“","kurz":"Aussage und Motiv sind getrennte Dinge: Kai hat das Argument stark und stimmig wiedergegeben, sein Verdacht gegen das Motiv verletzt aber nur die Regel zu guten Motiven. Die Rüge trifft daher nur zur Hälfte.","prueffrage":"Welche Regel betrifft das, was der Gegner sagt, und welche das, warum er es sagt?","rueckmeldung":[{"option":1,"text":"Dass der Verdacht gegen eine der Regeln verstößt, stimmt. Er macht aber Kais Wiedergabe nicht nachträglich unwohlwollend, denn das Argument hat er stark und stimmig dargestellt. Deutung der Aussage und Annahme über das Motiv sind getrennte Schritte."},{"option":2,"text":"Richtig ist, dass Kais Wiedergabe des Arguments wohlwollend war. Doch Regel B verlangt ausdrücklich gute Motive, ein Verdacht gegen das Motiv ist also kein erlaubter Zusatz. Dass Deutung und Motiv getrennt sind, heißt nicht, dass die Motivregel entfällt."},{"option":3,"text":"Wer ein Motiv hinterfragt, verstößt tatsächlich gegen eine der Regeln, nämlich gegen die zu guten Motiven. Die Regel zur Deutung der Aussage hat Kai dagegen erfüllt. Ein Motivzweifel macht die Wiedergabe nicht zwangsläufig unwohlwollend."}],"familie":"wohlwollend-verstehen","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Malpas, J.: Donald Davidson. Stanford Encyclopedia of Philosophy (rev. 28.04.2023), Abschnitt 3.3","oeffentlich":true,"url":"https://plato.stanford.edu/entries/davidson/","abruf":"2026-10-12"},{"typ":"url","kurz":"Dresner, E. (2011): The Principle of Charity and Intercultural Communication. International Journal of Communication 5, 969–982","oeffentlich":true,"url":"https://ijoc.org/index.php/ijoc/article/view/817","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"e26890ac4a7a30dd"}},{"id":"qx-h-021","clusterId":"H","werkstueckRef":"H.1.4","stufe":1,"question":"Was ist an diesem Argument fehlerhaft?","options":["Es nimmt an, dass Logik allein eine Wahl treffen kann, obwohl dem Mann ohne Gefühle Präferenzen, Werte und Dringlichkeit fehlten, um Akten zu ordnen.","Es nimmt an, dass Gefühle das Gedächtnis belasten, obwohl bei dem Mann nach dem Verlust der Gefühle Gedächtnis und Intelligenz unverändert blieben.","Es nimmt an, dass Gefühle vor allem unter Zeitdruck stören, obwohl der Mann einen ganzen Nachmittag Zeit hatte und trotzdem über der Aktenordnung grübelte.","Es nimmt an, dass viele Wahlmöglichkeiten nüchternes Denken überfordern, obwohl der Mann schon bei drei Ordnungsmerkmalen (Datum, Umfang, Bedeutung) nicht weiterkam."],"correctIndex":0,"explanation":"Der Fallbericht widerlegt die Behauptung: Trotz intakter Intelligenz, intaktem logischem Denken und intaktem Gedächtnis konnte der Mann nicht einmal entscheiden, wie er Akten ordnen sollte. Auch bei einem Patienten mit gleichartiger Schädigung zeigte sich dasselbe Muster: Er zählte endlos Gründe für und gegen zwei Termine auf, doch ohne die emotionale Präferenz, die sagt: „Nimm einfach den!“, fand die Abwägung kein Ende. Logik kann Optionen analysieren, aber sie liefert keine Rangfolge der Ziele und kein Gefühl der Dringlichkeit. Wer Gefühle abschaltet, gewinnt deshalb keine Überlegenheit, sondern verliert Orientierung. Die anderen Aussagen klingen nach möglichen Schwachstellen, treffen aber den Fall nicht: Gedächtnis und Intelligenz blieben unverändert, also wurden sie durch die Gefühle weder belastet noch gestützt. Zeitdruck war nicht das Problem, der Mann hatte einen ganzen Nachmittag. Und an der Zahl der Wahlmöglichkeiten lag es nicht, denn schon drei Merkmale reichten, um ihn festzusetzen. Der Vorbehalt: Wie genau Gefühle in die Wahl eingreifen, etwa über Körpersignale, ist wissenschaftlich umstritten. Dass Menschen ohne Gefühlsreaktion in Entscheidungen scheitern, zeigt der Fall aber deutlich.","coreRule":"⚡ Wer Gefühle abschaltet, wird nicht klüger, sondern entscheidungsunfähig: Logik analysiert die Optionen, Gefühle geben Präferenz, Richtung und Dringlichkeit.","quote":"Emotionen sind nicht der Feind der Logik, sondern ihr notwendiger Steuermann.","quoteLabel":"Merksatz:","beleg":"Werkstück H.1.4 (Der handlungsunfähige Vulkanier; Kernidee); Fn. gl-h-2 (Damasio 1994, Descartes' Error, Elliot S. 34–51, Taschenbuchausgabe 1995)","status":"entwurf","scenario":"In einer Diskussion über Entscheidungen sagt jemand: „Gefühle stören nur. Wer seine Emotionen abschaltet, entscheidet automatisch besser. Ein Mensch, der nur noch logisch denkt, hätte alle Vorteile und würde im Alltag souverän klarkommen.“\\n\\nDazu ein Fallbericht: Ein Mann verliert nach einer Operation am Stirnhirn seine Gefühlsreaktionen. Intelligenz, logisches Denken und Gedächtnis bleiben vollständig intakt. Trotzdem grübelt er einen ganzen Nachmittag darüber, ob er Akten nach Datum, Umfang oder Bedeutung ordnen soll, und verliert seine Stelle.","kurz":"Logik kann Optionen analysieren, aber sie liefert keine Rangfolge der Ziele und kein Gefühl der Dringlichkeit. Der Mann ohne Gefühlsreaktion dachte intakt und scheiterte doch schon an der Aktenordnung. Wer Gefühle abschaltet, verliert Orientierung.","prueffrage":"Was konnte der Mann trotz intakter Intelligenz und intaktem Denken im Alltag nicht mehr leisten?","rueckmeldung":[{"option":1,"text":"Dass Gefühle das Gedächtnis belasten, ist als Vermutung nicht abwegig. Beim Mann blieb das Gedächtnis aber nach dem Verlust der Gefühle unverändert; sein Scheitern lag an der Entscheidung, nicht am Erinnern."},{"option":2,"text":"Unter Zeitdruck können Gefühle durchaus stören. Hier passt das aber nicht: Der Mann hatte einen ganzen Nachmittag Zeit und kam trotzdem zu keiner Entscheidung, also lag es nicht an der Eile."},{"option":3,"text":"Viele Wahlmöglichkeiten können überfordern, doch das erklärt diesen Fall nicht. Schon bei drei Ordnungsmerkmalen kam der Mann nicht weiter, die Menge an Optionen war also nicht das Hindernis."}],"familie":"innehalten-bei-druck","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Dunn, Dalgleish & Lawrence (2006): The somatic marker hypothesis: A critical evaluation. Neuroscience and Biobehavioral Reviews 30(2), 239–271 (Autorenmanuskript, MRC CBU)","oeffentlich":true,"url":"https://www.mrc-cbu.cam.ac.uk/personal/tim.dalgleish/dunnsmhreview.pdf","seite":"4–5 (Manuskriptzählung)","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Damasio, A. R. (1994): Descartes' Error: Emotion, Reason, and the Human Brain. New York: Putnam","oeffentlich":false}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"6661cb5c52230408"}},{"id":"qx-h-022","clusterId":"H","werkstueckRef":"H.1.4","stufe":2,"question":"Welche Antwort geht auf diese Aussage am besten ein?","scenario":"Beim Grillen sagt jemand: „Man sollte immer auf sein Herz hören und nicht auf den kalten Verstand.“ Du willst weder einfach zustimmen noch die Aussage abtun, sondern sie in einen Rahmen setzen, in dem beide Seiten ihren Platz haben.","options":["Das lässt sich testen: Man vergleicht, ob Entscheidungen nach Herz oder nach Verstand besser ausgehen, und hält sich an die Seite mit der besseren Bilanz.","Es kommt auf das Wort „Herz“ an: Wer damit die eigenen Werte meint, hat recht, wer damit bloße Launen meint, liegt falsch.","Das Wort „immer“ ist angreifbar: Schon ein einziger Fall, in dem das Herz in die Irre führte, zeigt, dass die Aussage so nicht stimmt.","Beides wird gebraucht: Der Verstand analysiert die Optionen, das Gefühl gibt die Richtung, und keines von beiden ersetzt das andere."],"correctIndex":3,"explanation":"Die Aussage setzt Herz und Verstand als Gegensatz, und beide Extreme scheitern. Ohne Gefühl fehlen Präferenzen, Werte und Dringlichkeit: Der Neurologe Antonio Damasio beschrieb Patienten mit einer Schädigung im unteren, mittleren Stirnhirn (ventromedialer präfrontaler Cortex), deren Intelligenz intakt war und die trotzdem an Banalitäten scheiterten; einer von ihnen, Elliot, grübelte einen ganzen Nachmittag darüber, wie er Akten ordnen sollte, ein anderer brauchte fast eine halbe Stunde für die Wahl zwischen zwei Terminen. Logik kann Optionen analysieren, aber nicht sagen, welches Ziel man anstreben soll. Ohne Prüfung dagegen kann ein einzelnes starkes Gefühl wie Angst oder Gier die Entscheidung kapern. Die tragfähige Antwort lässt daher beides gelten: Der Verstand analysiert die Optionen, das Gefühl gibt Richtung, und keines ersetzt das andere. Die anderen Wege sind gute Denkwerkzeuge, geben der Aussage aber keinen Rahmen: Ein Vergleich der Bilanzen kürt eine Seite zum Sieger, statt beiden einen Platz zu geben. Die Klärung des Worts „Herz“ hilft beim Begriff, sagt aber nichts über das Zusammenspiel mit dem Verstand. Ein Gegenbeispiel zu „immer“ verwirft die Aussage, und genau das wolltest du nicht.","coreRule":"⚡ Herz und Verstand sind Partner: Der eine lenkt, der andere prüft den Weg.","beleg":"Werkstück H.1.4 (Werkbank-Frage; Kernidee; Red Flags)","status":"entwurf","kurz":"Herz und Verstand sind kein Gegensatz: Der Verstand analysiert die Optionen, das Gefühl gibt Richtung und Dringlichkeit, und keines ersetzt das andere. Wer eine Seite zum Sieger erklärt oder verwirft, verfehlt genau das.","prueffrage":"Wie lief deine letzte wichtige Entscheidung ab, und welche Rolle spielten dabei Bauchgefühl und Nachrechnen?","rueckmeldung":[{"option":0,"text":"Ein Vergleich der Bilanzen ist ein sinnvolles Werkzeug, macht aus beiden aber wieder Konkurrenten und kürt einen Sieger. Außerdem bleibt offen, was „besser ausgehen“ heißt, und dieses Maß speist sich selbst aus Werten und Gefühlen."},{"option":1,"text":"Die Unterscheidung zwischen Werten und bloßen Launen ist berechtigt und klärt den Begriff. Wie Gefühl und Verstand bei einer Entscheidung zusammenwirken, sagt sie aber nicht; sie sortiert die Aussage nur in eine richtige und eine falsche Lesart."},{"option":2,"text":"Als Allaussage ist „immer“ tatsächlich angreifbar, und ein Gegenbeispiel genügt zur Widerlegung. Damit ist die Aussage aber nur verworfen, und das Herz hat in deinem Rahmen keinen Platz mehr, den du ihm geben wolltest."}],"familie":"innehalten-bei-druck","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Dunn, Dalgleish & Lawrence (2006): The somatic marker hypothesis: A critical evaluation (Autorenmanuskript, MRC CBU)","oeffentlich":true,"url":"https://www.mrc-cbu.cam.ac.uk/personal/tim.dalgleish/dunnsmhreview.pdf","seite":"4–5 (Manuskriptzählung)","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Damasio, A. R. (1994): Descartes' Error: Emotion, Reason, and the Human Brain. New York: Putnam","oeffentlich":false}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"b341e5e248538bdd"}},{"id":"qx-h-023","clusterId":"H","werkstueckRef":"H.1.4","stufe":3,"question":"Ein Kollege erzählt: „Als die Aktie über Nacht um 30 Prozent fiel, wurde mir ganz heiß vor Angst. Ich habe sofort alles verkauft, ohne nachzurechnen. Eine Stunde später stand sie wieder fast auf dem alten Kurs.“ Was erklärt am besten, warum sein Vorgehen zum Problem wurde?","options":["Die Angst hat sein Denken verdrängt und allein entschieden, sodass eine überstürzte, kurzsichtige Handlung ohne Prüfung der Fakten herauskam.","Er hat ein Gefühl in eine Geldentscheidung einfließen lassen, obwohl dort allein die nüchterne Rechnung zählen sollte und Angst nur stört.","Er hatte Pech mit dem Zeitpunkt, denn dass sich der Kurs binnen einer Stunde erholen würde, konnte er beim Verkauf schlicht nicht wissen.","Er hat nur auf den Kurs einer Nacht geschaut, und so kurze Ausschnitte schwanken stark, sodass ein Blick auf längere Zeit ihn beruhigt hätte."],"correctIndex":0,"explanation":"Die Angst an sich war nicht das Problem. Gefühle geben Orientierung, Priorität und Dringlichkeit, und dass ihn der Kurssturz alarmiert hat, ist als Datenpunkt sogar nützlich. Zum Problem wurde die Lage erst, als die starke Emotion das Nachdenken komplett ersetzt hat: Er hat weder nachgerechnet noch Gründe für oder gegen den Verkauf geprüft. Dann entscheidet das Gefühl allein, und das Ergebnis sind impulsive, kurzsichtige Handlungen. Ein Denken ganz ohne Gefühl wäre dagegen nicht besser, sondern orientierungslos: Patienten mit gestörter Verbindung zwischen Gefühl und Verstand zerdenken schon einfache Terminwahlen endlos. Sinnvoll ist, das Gefühl ernst zu nehmen und dann zu prüfen, welche Fakten es stützen oder widerlegen.","coreRule":"⚡ Gefühle beraten gut, aber sie dürfen nicht allein regieren.","beleg":"Werkstück H.1.4 (Der Kipppunkt; Red Flags: emotionale Kaperung)","status":"entwurf","scenario":"","kurz":"Nicht die Angst war das Problem, sondern dass sie das Nachdenken komplett ersetzt hat: Er hat weder nachgerechnet noch Gründe geprüft. Das Gefühl allein entschied, und so kam eine überstürzte Handlung heraus.","prueffrage":"Was geschah zwischen dem Moment, in dem er den Kurssturz sah, und dem Verkauf?","rueckmeldung":[{"option":1,"text":"Dass sich Gefühle in Geldentscheidungen mischen, wirkt wie ein Fehler, der sich leicht beheben ließe. Die Angst war aber ein nützlicher Alarm und gehört zu guten Entscheidungen. Zum Problem wurde sie erst, als sie die Rechnung ersetzt hat."},{"option":2,"text":"Ohne Hellseherei konnte er die Erholung tatsächlich nicht kennen. Aber auch bei weiter fallendem Kurs wäre ein Verkauf ohne jede Prüfung ein schwaches Vorgehen gewesen. Bewertet wird die Art der Entscheidung, nicht ihr Ausgang."},{"option":3,"text":"Ein längerer Zeitraum hätte ihn womöglich beruhigt, und das ist eine mögliche Prüfung. Entscheidend ist aber, dass er gar nichts geprüft hat. Auch mit längerem Blick auf den Kurs hätte die Angst das Nachdenken ersetzen können."}],"familie":"innehalten-bei-druck","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Dunn, Dalgleish & Lawrence (2006): The somatic marker hypothesis: A critical evaluation (Autorenmanuskript, MRC CBU)","oeffentlich":true,"url":"https://www.mrc-cbu.cam.ac.uk/personal/tim.dalgleish/dunnsmhreview.pdf","seite":"4–5 (Manuskriptzählung)","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Peters, E. (2011): Affect and Emotion. In: Fischhoff, Brewer & Downs (Hg.): Communicating Risks and Benefits: An Evidence-Based User's Guide. FDA","oeffentlich":false}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"11a09b6c8db45301"}},{"id":"qx-h-024","clusterId":"H","werkstueckRef":"H.1.4","stufe":4,"question":"Eine Wissenschaftsjournalistin schreibt: „Der Neurologe Antonio Damasio hat bewiesen, dass Körpersignale unsere Entscheidungen lenken. Der Beweis ist ein Kartenspiel-Experiment.“ Welche Rückfrage prüft diese Behauptung am besten?","options":["Wer hat das Kartenspiel-Experiment bezahlt, und hätte der Geldgeber ein Interesse an einem Ergebnis zugunsten der Körpersignale gehabt?","Lässt sich das Ergebnis des Kartenspiels auch ohne Körpersignale erklären, etwa weil die Teilnehmer die günstige Strategie bewusst kannten?","Wurde das Experiment mit den vier Kartenstapeln vor der Veröffentlichung von unabhängigen Fachleuten begutachtet, und wo ist es erschienen?","Hat die Journalistin die Originalarbeit zum Kartenspiel selbst gelesen oder nur die Zusammenfassung eines anderen Artikels übernommen?"],"correctIndex":1,"explanation":"Wer „bewiesen“ sagt, muss ausschließen, dass es eine einfachere Erklärung für dasselbe Ergebnis gibt. Genau das ist hier fraglich: Maia und McClelland (2004) fanden, dass Teilnehmer dieses Kartenspiels die günstige Strategie bewusst kennen, und zwar zuverlässiger, als sie danach handeln. Dann lässt sich das Verhalten möglicherweise auch ohne unbewusste Körpersignale erklären. Dunn u. a. (2006) kommen zu dem Schluss, dass die Einwände die Hypothese nicht widerlegen; sie sei eine elegante Theorie, die zusätzliche empirische Stützung braucht. „Bewiesen“ ist also zu stark. Gesichert ist nur: Die Hypothese ist einflussreich, aber umstritten, und bislang weder bewiesen noch widerlegt. Die anderen Rückfragen sind für sich sinnvoll, klären aber nicht, ob die Deutung des Ergebnisses trägt: Die Frage nach dem Geldgeber zielt auf mögliche Befangenheit, wofür das Szenario keinen Hinweis gibt. Eine Begutachtung spricht für Sorgfalt, ist aber noch kein Beweis für die Deutung. Ob die Journalistin das Original gelesen hat, betrifft ihre Quelle, nicht die Frage, ob eine sparsamere Erklärung offen bleibt.","coreRule":"⚡ Bevor du „bewiesen“ akzeptierst, frage: Gibt es eine einfachere Erklärung für dasselbe Ergebnis?","beleg":"Werkstück H.1.4 (Kernidee; Kontext & Tiefe); Fn. gl-h-somatisch (Damasio 1994, Kap. 8–9; Dunn/Dalgleish/Lawrence 2006, S. 239–271; Maia/McClelland 2004, PNAS 101(45), S. 16075–16080, hier S. 16075)","status":"entwurf","scenario":"Die Hypothese besagt, dass Körpersignale („somatische Marker“) Entscheidungen lenken, noch bevor wir die Regeln bewusst durchschauen. Als zentraler Beleg gilt ein Kartenspiel-Experiment, in dem gesunde Testpersonen und Patienten mit Schäden im Stirnhirn aus vier Kartenstapeln mit unterschiedlichem Gewinn- und Verlustrisiko ziehen.","kurz":"„Bewiesen“ verlangt, dass es keine einfachere Erklärung für dasselbe Ergebnis gibt. Hier wäre eine denkbar: Wer die günstige Strategie bewusst kennt, spielt womöglich auch ohne Körpersignale so. Dann bliebe die Hypothese offen, aber unbewiesen.","prueffrage":"Was genau taten die Testpersonen im Kartenspiel, und was davon wurde tatsächlich gemessen?","rueckmeldung":[{"option":0,"text":"Wer eine Studie bezahlt hat, kann ihr Ergebnis färben, das ist eine berechtigte Sorge. Für Befangenheit nennt das Szenario aber keinen Hinweis, und selbst dann bliebe offen, ob das Ergebnis eine einfachere Deutung zulässt."},{"option":2,"text":"Begutachtung und Erscheinungsort sprechen für sorgfältige Arbeit. Dass das Experiment sauber durchgeführt wurde, sagt aber noch nicht, ob die Deutung „Körpersignale lenken Entscheidungen“ die einzig mögliche ist."},{"option":3,"text":"Eine Übernahme aus zweiter Hand kann Fehler weitertragen, und Originale zu lesen ist gute Praxis. Die Rückfrage betrifft aber die Quelle der Journalistin, nicht die Frage, ob dasselbe Ergebnis auch anders erklärbar bleibt."}],"familie":"sparsamste-erklaerung","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Maia, T. V. & McClelland, J. L. (2004): A reexamination of the evidence for the somatic marker hypothesis. PNAS 101(45), 16075–16080 (PMC-Fassung)","oeffentlich":true,"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC528759/","abruf":"2026-10-12"},{"typ":"url","kurz":"Dunn, Dalgleish & Lawrence (2006): The somatic marker hypothesis: A critical evaluation (Autorenmanuskript, MRC CBU)","oeffentlich":true,"url":"https://www.mrc-cbu.cam.ac.uk/personal/tim.dalgleish/dunnsmhreview.pdf","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"2a44a73aa122db77"}},{"id":"qx-h-025","clusterId":"H","werkstueckRef":"H.1.5","stufe":1,"question":"Welche Schlussfolgerung ist am besten begründet?","options":["Beide überziehen: Dass die Feeds seine Konzentration geschwächt haben, ist plausibel, wie stark sich das im Gehirn zeigt, aber offen; Üben kann helfen, am ehesten am Lesen selbst.","Die Schwester liegt eher richtig: Dass die Feeds seine Konzentration geschwächt haben, ist plausibel, und was sich über Jahre eingeschliffen hat, lässt sich kaum noch durch Üben am Lesen zurückholen.","Der Bruder liegt eher richtig: Dass die Feeds seine Konzentration geschwächt haben, ist plausibel, und das lernfähige Gehirn holt sie durch regelmäßiges Üben in aller Regel vollständig zurück.","Keiner von beiden kann es wissen: Ob die Feeds seine Konzentration geschwächt haben, ist ohne Hirnscans nicht zu sagen, und ob Üben hilft, ebenso wenig."],"correctIndex":0,"explanation":"Die Schwester nimmt an, das erwachsene Gehirn sei starr. Das ist überholt: Auch das erwachsene Gehirn verändert sich durch Erfahrung, wie stark und wie dauerhaft, ist allerdings umstritten; ihr „da lässt sich nichts mehr machen“ ist daher zu sicher. Der Bruder liegt in der Richtung näher an der Sache, denn Konzentration lässt sich üben, am ehesten an genau der Tätigkeit, für die man sie braucht; dass Üben es sicher und vollständig wieder richtet, ist aber ebenso wenig gesichert, und beliebig formbar ist das Gehirn nicht. Dass jahrelange Feed-Gewohnheiten die Konzentration geschwächt haben, ist plausibel, ob und wie stark sich das im Gehirn selbst zeigt, ist offen. Die anderen Schlüsse haben je einen richtigen Kern, ziehen daraus aber zu viel: Dass Gewohnheiten prägen, heißt nicht, dass sich kaum etwas zurückholen lässt. Dass das Gehirn lernfähig bleibt, heißt nicht, dass Üben allein alles vollständig zurückholt. Und ohne Hirnscans lässt sich zwar nicht sagen, wie stark sich Feeds im Gehirn zeigen, wohl aber, dass das Üben einer Tätigkeit sie in der Regel verbessert.","coreRule":"⚡ Das Gehirn formt sich nach dem, was du wiederholst, ohne Rücksicht auf den Nutzen. Wie stark und wie dauerhaft, bleibt eine offene Frage.","quote":"","quoteLabel":"","beleg":"Werkstück H.1.5 (Kernidee; Kontext & Tiefe)","status":"entwurf","scenario":"Jemand verbringt seit Jahren fast jede freie Minute mit kurzen Videos und Nachrichten-Feeds. Heute fällt es ihm schwer, länger als ein paar Minuten bei einem anspruchsvollen Text zu bleiben. Seine Schwester sagt: „Ich bin mir sicher, dass sich sein Gehirn dadurch dauerhaft verschlechtert hat, da lässt sich nichts mehr machen.“ Er antwortet: „Das glaube ich nicht. Ich muss nur wieder üben, dann wird es besser.“","kurz":"Dass Feeds die Konzentration geschwächt haben, ist plausibel, wie stark das im Gehirn steckt, bleibt offen. Üben am Lesen hilft meist; „nichts mehr zu machen“ und „wird sicher ganz wieder gut“ sind beide zu sicher.","prueffrage":"Was lässt sich in seinem Alltag tatsächlich beobachten, wenn er statt Feeds regelmäßig längere Texte liest?","rueckmeldung":[{"option":1,"text":"Dass jahrelange Gewohnheiten prägen, stimmt. Daraus folgt aber nicht, dass sich kaum etwas zurückholen lässt: Auch das erwachsene Gehirn verändert sich durch Erfahrung, und Lesen lässt sich meist üben."},{"option":2,"text":"Richtig ist, dass das Gehirn lernfähig bleibt und Üben in die richtige Richtung geht. „Vollständig“ und „in aller Regel“ sind aber mehr, als sich sagen lässt; das Gehirn ist nicht beliebig formbar."},{"option":3,"text":"Wie stark sich Feeds im Gehirn zeigen, ist ohne Messung tatsächlich offen. Das heißt aber nicht, dass man gar nichts sagen kann: Konzentration lässt sich durch Üben meist verbessern, und eine Schwächung ist plausibel."}],"familie":"befund-reichweite","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Malik, Stemplewski & Maciaszek (2022): The Effect of Juggling as Dual-Task Activity on Human Neuroplasticity: A Systematic Review. Int. J. Environ. Res. Public Health 19(12), 7102","oeffentlich":true,"doi":"10.3390/ijerph19127102","abruf":"2026-10-12"},{"typ":"doi","kurz":"Fan, Wu, Fossella & Posner (2001): Assessing the heritability of attentional networks. BMC Neuroscience 2, 14","oeffentlich":true,"doi":"10.1186/1471-2202-2-14"},{"typ":"literatur","kurz":"Thomas, C. & Baker, C. I. (2013): Teaching an adult brain new tricks: a critical review of evidence for training-dependent structural plasticity in humans. NeuroImage 73, 225–236","oeffentlich":false}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"8820676a6a4abbfb"}},{"id":"qx-h-026","clusterId":"H","werkstueckRef":"H.1.5","stufe":2,"question":"Welcher Plan ist am ehesten geeignet, Konzentration wieder aufzubauen, und warum?","scenario":"Du merkst, dass du kaum noch ein langes Buch am Stück lesen kannst und bei jeder Mikropause zum Smartphone greifst. Du willst deine Konzentration gezielt trainieren und überlegst, wie du vorgehst.","options":["Jeden Tag 15 bis 30 Minuten ununterbrochen eine einzige anspruchsvolle Aufgabe bearbeiten, ohne Smartphone in Sichtweite, damit sich die Konzentration schrittweise wieder aufbaut.","Jeden Tag 20 Minuten Denkspiele auf dem Tablet spielen, ohne Smartphone in Sichtweite, damit sich die Konzentration auch beim Lesen langer Texte verbessert.","Jeden Tag eine Stunde ein Hörbuch laufen lassen, ohne Smartphone in Sichtweite, und nebenbei Wäsche falten oder kochen, damit das Dranbleiben an langen Texten wächst.","Jeden Tag zehn Minuten achtsam atmen, ohne Smartphone in Sichtweite, damit sich die Ruhe auf lange Lesephasen überträgt, und sonst nichts verändern."],"correctIndex":0,"explanation":"Geübt wird, was man tatsächlich tut: Wer Konzentration will, muss genau diese Tätigkeit regelmäßig und in kleinen, machbaren Dosen üben. Sinnvoll sind dafür tägliche, ununterbrochene Übungsphasen von 15 bis 30 Minuten. Am Anfang wird das Gehirn rebellieren und nach Ablenkung verlangen, mit konsequenter Wiederholung wird der Weg der Konzentration aber wieder frei. Unterschiede in der Aufmerksamkeitssteuerung sind zum Teil erblich, aber auch geübt werden kann sie; besser wird man dabei vor allem in dem, was man übt, ohne sicheren Übertrag auf ungeübte Aufgaben (Owen u. a. 2010). Für die Übung der Konzentration spricht also einiges; ob ständige Ablenkung das Gehirn messbar umgebaut hat, ist dagegen noch offen. Die anderen Pläne klingen vernünftig, passen aber nicht: Denkspiele verbessern vor allem das Spielen dieser Spiele, ein sicherer Übertrag aufs Lesen ist auch ohne Smartphone nicht belegt. Beim Hörbuch mit Nebentätigkeit übst du geteilte Aufmerksamkeit statt ununterbrochenen Dranbleibens. Eine Atemübung kann entspannen, ersetzt aber nicht das Üben der Tätigkeit, um die es geht.","coreRule":"⚡ Wer eine Fähigkeit stärken will, übt sie regelmäßig und gezielt an genau der Tätigkeit, für die er sie braucht.","beleg":"Werkstück H.1.5 (Die Schmiede-Übung; Anwendung & Relevanz); Fn. gl-h-aufmerksamkeit (Fan u. a. 2001; Rueda u. a. 2005)","status":"entwurf","kurz":"Konzentration wird dort besser, wo man sie tatsächlich übt: täglich 15 bis 30 Minuten ununterbrochen an einer anspruchsvollen Aufgabe. Naheliegend ist, ähnlich klingende Übungen für gleichwertig zu halten, doch gebessert wird vor allem, was geübt wird.","prueffrage":"Was genau tust du während der Zeit, die du als Training einplanst, und wie oft kommt das vor?","rueckmeldung":[{"option":1,"text":"Die Spiele fordern Konzentration, und ohne Smartphone in Sichtweite ist die Idee gut gemeint. Besser wird man aber vor allem in dem, was man übt, hier also im Spielen; ein sicherer Übertrag aufs Lesen langer Texte ist nicht belegt."},{"option":2,"text":"Ein Hörbuch ohne Smartphone klingt nach Training für lange Texte. Wäsche und Kochen nebenbei teilen aber die Aufmerksamkeit, geübt wird also geteilte Aufmerksamkeit statt ununterbrochenen Dranbleibens an einer Sache."},{"option":3,"text":"Achtsames Atmen kann entspannen, und das Smartphone aus der Sichtweite zu nehmen hilft. Es ersetzt aber nicht das Üben der Tätigkeit selbst; wer sonst nichts ändert, übt das ununterbrochene Dranbleiben an einer Aufgabe gar nicht."}],"familie":"befund-reichweite","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Owen, Hampshire, Grahn u. a. (2010): Putting brain training to the test. Nature 465(7299), 775–778 (frei als PMC2884087)","oeffentlich":true,"doi":"10.1038/nature09042","abruf":"2026-10-12"},{"typ":"doi","kurz":"Rueda, Rothbart, McCandliss, Saccomanno & Posner (2005): Training, maturation, and genetic influences on the development of executive attention. PNAS 102(41), 14931–14936 (frei als PMC1253585)","oeffentlich":true,"doi":"10.1073/pnas.0506897102","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"ebcb83068d408893"}},{"id":"qx-h-027","clusterId":"H","werkstueckRef":"H.1.5","stufe":3,"question":"Welche Schlussfolgerung stützt eine große Online-Studie mit über 11.000 Teilnehmern, in der sechs Wochen lang Denkspiele geübt wurden, am besten?","scenario":"Ein Werbetext verspricht: „Zehn Minuten Gehirntraining täglich verbessern Ihre Konzentration im ganzen Alltag.“ Zur Prüfung des Versprechens liegt eine große Online-Studie vor: Über 11.000 Menschen übten sechs Wochen lang Denkspiele. Alle geübten Aufgaben wurden deutlich besser. Bei ungeübten Aufgaben, auch bei eng verwandten, zeigte sich keine Verbesserung.","options":["Wer eine Aufgabe übt, wird vor allem in dieser Aufgabe besser; für ungeübte Aufgaben belegt die Studie keinen Gewinn.","Wer Denkspiele übt, braucht länger als sechs Wochen; die Studie war für einen Gewinn bei ungeübten Aufgaben wohl zu kurz.","Wer Denkspiele übt, verschwendet seine Zeit; die Studie belegt, dass solches Training die Konzentration nicht verändert.","Wer allgemeine Denkspiele übt, stärkt seine Konzentration im Alltag; die Studie macht das durch ihre hohe Teilnehmerzahl verlässlich."],"correctIndex":0,"explanation":"Die Teilnehmer wurden in den geübten Aufgaben deutlich besser, in ungeübten Aufgaben aber nicht, selbst wenn diese den geübten kognitiv nahestanden. Das stützt: Übung wirkt vor allem dort, wo geübt wurde. Der Werbeslogan behauptet aber genau den Sprung vom Spiel auf den „ganzen Alltag“. Dafür fehlt hier der Beleg. Wer Konzentration für eine bestimmte Tätigkeit braucht, übt sie deshalb am besten an dieser Tätigkeit selbst. Dass Aufmerksamkeit trainierbar ist, bleibt davon unberührt: Die geübten Aufgaben wurden ja besser. Eine hohe Teilnehmerzahl macht ein Ergebnis verlässlicher, kann den fehlenden Gewinn bei den ungeübten Aufgaben aber nicht in einen Nutzen verwandeln.","coreRule":"⚡ Übung wirkt vor allem im Geübten: Trainiere Konzentration an der Tätigkeit, die du brauchst, nicht an Ersatzspielen.","beleg":"Werkstück H.1.5 (Kontext & Tiefe: Konzentration als Fähigkeit); Fn. gl-h-aufmerksamkeit (Owen u. a. 2010, Nature 465(7299), S. 775–778)","status":"entwurf","kurz":"Die Teilnehmer wurden nur in den geübten Aufgaben besser, selbst bei eng verwandten Aufgaben blieb der Gewinn aus. Daraus lässt sich nicht auf „den ganzen Alltag“ schließen; ein solcher Sprung ist hier nicht belegt, auch nicht durch viele Teilnehmer.","prueffrage":"In welchen Aufgaben genau zeigte sich eine Verbesserung, und wie weit liegen diese vom beworbenen „ganzen Alltag“ entfernt?","rueckmeldung":[{"option":1,"text":"Ob längeres Üben mehr bringen würde, lässt die Studie offen, und das ist ein berechtigter Einwand gegen jede Studie. Die Antwort macht daraus aber eine Vermutung ohne Beleg: Gezeigt ist nur, dass sich nach sechs Wochen bei ungeübten Aufgaben nichts verbessert hat."},{"option":2,"text":"Dass der versprochene Alltagsnutzen hier fehlt, stimmt. „Nichts verändert“ geht aber zu weit: Die geübten Aufgaben wurden deutlich besser, also lässt sich Aufmerksamkeit durchaus trainieren. Die Studie zeigt, wo der Gewinn bleibt, nicht dass es keinen gibt."},{"option":3,"text":"Eine große Stichprobe macht ein Ergebnis verlässlicher, aber verlässlich ist hier gerade der ausbleibende Gewinn bei ungeübten Aufgaben. Die Teilnehmerzahl kann aus diesem Befund keinen Nutzen für den Alltag machen, den das Ergebnis nicht hergibt."}],"familie":"befund-reichweite","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Owen, Hampshire, Grahn u. a. (2010): Putting brain training to the test. Nature 465(7299), 775–778 (frei als PMC2884087)","oeffentlich":true,"doi":"10.1038/nature09042","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"443e73517e07b0f8"}},{"id":"qx-h-028","clusterId":"H","werkstueckRef":"H.1.5","stufe":4,"question":"In einem Vortrag zitiert jemand den Satz „Neurons that fire together, wire together“ und fügt hinzu: „Das hat Donald Hebb 1949 wörtlich so geschrieben.“ Du willst die Aussage prüfen. Welche Überlegung bringt dich am weitesten?","options":["Ob die Aussage heute als wissenschaftlich gesichert gilt, entscheidet über ihr Gewicht, das lässt sich in neueren Studien prüfen.","Eine so eingängige Formel stammt eher aus einer späteren Zusammenfassung, das lässt sich an der Originalquelle prüfen.","Wer fachkundig vorträgt, zitiert meist genauer, das lässt sich an Beruf und Veröffentlichungen der Person prüfen.","Vortragende wählen Zitate oft nach ihrem eigenen Interesse aus, das lässt sich an den Absichten hinter dem Vortrag prüfen."],"correctIndex":1,"explanation":"Eine Zuschreibung ist erst belegt, wenn man die Originalquelle kennt. Hier ist das besonders wichtig: Die Formel ist so griffig, dass sie eher wie eine spätere Verdichtung klingt als wie ein Satz aus einer Fachpublikation. Tatsächlich ist die Kurzformel keine Originalformulierung Hebbs („The Organization of Behavior“, 1949), sondern eine spätere, griffigere Zusammenfassung seines Postulats. Sie wird meist Carla Shatz zugeschrieben („cells that fire together wire together“, Scientific American, 1992); populär wurde sie erst rund vier Jahrzehnte nach Hebb. Hebbs eigener Wortlaut ist deutlich sperriger: Wenn das Axon einer Zelle A nah genug ist, um eine Zelle B zu erregen, und wiederholt an deren Aktivierung beteiligt ist, tritt in einer oder beiden Zellen ein Wachstums- oder Stoffwechselprozess ein, der die Effizienz von A bei der Erregung von B erhöht. Selbst inhaltlich trifft die Kurzformel Hebb nur ungefähr: Bei ihm ist A an der Erregung von B ursächlich beteiligt, die Formel spricht nur von gleichzeitigem Feuern. Die Behauptung „wörtlich so geschrieben“ stimmt jedenfalls nicht. Ob die Theorie heute als gesichert gilt, ist eine eigene, sinnvolle Frage, sie sagt aber nichts darüber, wer diese Worte geschrieben hat. Wie fachkundig jemand ist, ersetzt den Blick in die Quelle nicht, denn auch Fachleute geben Sätze ungenau wieder. Und selbst wenn man die Absichten der Person kennt, weiß man noch nicht, was Hebb tatsächlich formuliert hat.","coreRule":"⚡ Griffige Zitate prüfen: Je eingängiger die Formel, desto eher lohnt der Blick in die Originalquelle, bevor man sie einer Person zuschreibt.","beleg":"Werkstück H.1.5 (Kontext & Tiefe); Fn. gl-h-3 (Hebb, The Organization of Behavior, 1949; Shatz, Scientific American, September 1992)","status":"entwurf","scenario":"","kurz":"Eine Zuschreibung ist erst belegt, wenn man die Originalquelle kennt. Der Satz ist so griffig, dass er eher nach späterer Verdichtung klingt als nach einer Fachpublikation. Tatsächlich stammt die Kurzformel nicht von Hebb selbst, sondern ist eine spätere Zusammenfassung.","prueffrage":"Behauptet der Vortragende nur, dass der Gedanke von Hebb stammt, oder auch, dass Hebb genau diese Worte benutzt hat?","rueckmeldung":[{"option":0,"text":"Ob die Theorie heute als gesichert gilt, ist eine sinnvolle Frage, und Studien können sie beantworten. Sie sagt aber nichts darüber, wer diese Worte wann geschrieben hat, und genau das wurde behauptet."},{"option":2,"text":"Fachleute zitieren oft genauer, das stimmt. Aber auch sie geben Sätze ungenau oder aus zweiter Hand wieder; Beruf und Veröffentlichungen ersetzen deshalb den Blick in die Quelle nicht."},{"option":3,"text":"Zitate werden tatsächlich oft nach Interesse ausgewählt, und das kann die Skepsis schärfen. Selbst wenn du die Absichten kennst, weißt du noch nicht, was Hebb formuliert hat; dafür führt kein Weg an der Quelle vorbei."}],"familie":"zitat-am-original-pruefen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Liberman, M. (21.04.2016): Language Log, Beitrag zu „fire together, wire together“","oeffentlich":true,"url":"https://languagelog.ldc.upenn.edu/nll/?p=25194","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Hebb, D. O. (1949): The Organization of Behavior. New York: Wiley","oeffentlich":false},{"typ":"literatur","kurz":"Shatz, C. J. (1992): The developing brain. Scientific American 267(3)","oeffentlich":false}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"a84b9ebf449f1b0c"}},{"id":"qx-h-029","clusterId":"H","werkstueckRef":"H.1.6","stufe":1,"question":"Was erklärt am besten, warum du ihr nicht helfen konntest und selbst erschöpft bist?","scenario":"Tante Gerda ruft panisch an: „Die da oben vergiften das Trinkwasser!“ Du hörst zu und schwingst ganz mit ihr mit: Ihre Angst wird zu deiner Angst, ihre Wut zu deiner Wut. Nach dem Anruf zitterst du, fühlst dich hoffnungslos und erschöpft. Gerda hat sich nicht beruhigt, und dir graut vor dem nächsten Anruf.","options":["Du stehst Gerda so nahe, dass ihre Angst um das Trinkwasser dich fast zwangsläufig mittrifft, daher war deine Erschöpfung kaum zu vermeiden und Hilfe schwer möglich.","Du hast Gerda zu viel Mitgefühl geschenkt, und wer sich so sehr um andere sorgt, brennt auf Dauer aus, daher wäre weniger Anteilnahme hilfreicher gewesen.","Du hast Gerdas Panik wegen des Trinkwassers übernommen statt dich davon zu lösen, daher warst du selbst überwältigt und konntest ihr keinen ruhigen Halt bieten.","Du hattest es mit einer tief sitzenden Angst um das Trinkwasser zu tun, die ein Anruf kaum lösen kann, daher blieb Gerda unruhig und das vergebliche Bemühen zermürbte dich."],"correctIndex":2,"explanation":"Wer die Gefühle des anderen ungefiltert übernimmt, schwingt voll mit ihm mit. Bei Panik heißt das: Zwei Menschen sind gleichzeitig aufgewühlt, und keiner ist übrig, der Halt geben könnte. Dieses Mitschwingen kann zu „Empathic Distress“ führen, einer emotionalen Überwältigung, die bis zu Lähmung, Rückzug oder Burnout reichen kann. Wer dagegen die Angst versteht, ohne sie zu übernehmen, und ruhig, aber warm bleibt, kann tatsächlich helfen; die Erschöpfung kommt hier nicht vom Sorgen an sich, sondern vom Übernehmen fremder Panik.","coreRule":"⚡ Wer die Panik des anderen spiegelt, kann ihm nicht helfen: Verstehen und Fürsorge brauchen Abstand zum fremden Gefühl.","beleg":"Werkstück H.1.6 (Der Anruf bei Tante Gerda, Szenario 1; Kontext & Tiefe)","status":"entwurf","kurz":"Wer Gerdas Panik ungefiltert übernimmt, ist genauso aufgewühlt wie sie, und niemand bleibt übrig, der Halt geben kann. Die Erschöpfung stammt nicht vom Mitgefühl, sondern vom Übernehmen. Wer die Angst versteht, ohne sie zu teilen, kann ruhig und warm helfen.","prueffrage":"Was hast du während des Anrufs gesagt oder getan, das Gerda hätte beruhigen können?","rueckmeldung":[{"option":0,"text":"Nähe macht es tatsächlich leichter, von Gefühlen angesteckt zu werden. Zwangsläufig ist das aber nicht: Man kann die Angst verstehen, ohne sie zu übernehmen, und so ruhig und warm bleiben. Das Mitschwingen war deshalb vermeidbar und ließ Hilfe nicht von vornherein aussichtslos sein."},{"option":1,"text":"Dass dauerhaft Überforderte ausbrennen, ist bekannt. Hier lag es aber nicht an zu viel Mitgefühl, sondern daran, dass Gerdas Panik ungefiltert übernommen wurde. Verstehen ohne Mitschwingen, ruhig und warm, wäre hilfreicher gewesen als weniger Anteilnahme."},{"option":3,"text":"Eine tief verwurzelte Angst löst ein einzelner Anruf in der Tat selten. Das erklärt aber nicht deine Erschöpfung: Sie kam vom Mitschwingen mit der Panik, nicht vom Misserfolg. Wer die Angst versteht und selbst ruhig bleibt, kann Gerda tatsächlich Halt geben."}],"familie":"gefuehl-zuerst-aufgreifen","fertigkeit":"F3","quellen":[{"typ":"doi","kurz":"Klimecki, Leiberg, Ricard & Singer (2014): Differential Pattern of Functional Brain Plasticity After Compassion and Empathy Training. Social Cognitive and Affective Neuroscience 9(6)","oeffentlich":true,"doi":"10.1093/scan/nst060","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC4040103/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Singer & Klimecki (2014): Empathy and Compassion. Current Biology 24(18), R875–R878 (Verlagsseite hier nicht geöffnet; Register b2a0fd0f299 am Volltext bestätigt)","oeffentlich":false,"doi":"10.1016/j.cub.2014.06.054"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"1454cc68fc3d055b"}},{"id":"qx-h-030","clusterId":"H","werkstueckRef":"H.1.6","stufe":2,"question":"Wie reagierst du in diesem Gespräch am besten?","options":["Du überlegst, warum sie das glaubt, sagst dann kurz, dass du ihre Angst wahrnimmst, und bleibst danach ruhig und zugewandt, um ihr beim Einordnen zu helfen.","Du schickst ihr sofort die Berichte über die Trinkwasserkontrollen und bleibst am Telefon, bis sie die Zahlen gelesen hat, damit sie die Lage selbst einordnen kann.","Du sagst ihr freundlich, dass du ihre Angst wahrnimmst, und bittest sie, sich erst zu beruhigen und später noch einmal anzurufen, weil Gespräche in der Panik wenig bringen.","Du fragst zuerst nach, woher sie ihre Informationen über das Trinkwasser hat, und gehst jede Quelle einzeln mit ihr durch, bevor du auf ihre Angst eingehst."],"correctIndex":0,"explanation":"Hilfreich ist eine Abfolge: erst verstehen, warum die Person so denkt, dann ihr Gefühl kurz spiegeln („Ich höre, dass dir das Angst macht“) und schließlich ruhig und warm Halt geben. Das kurze Spiegeln signalisiert, dass du ihre Angst ernst nimmst, ohne dass sie auf dich übergeht.","coreRule":"⚡ Verstehen, kurz spiegeln, dann ruhig und warm Halt geben.","quote":"Du fühlst nicht mit ihr, du fühlst für sie.","quoteLabel":"Merksatz:","beleg":"Werkstück H.1.6 (Szenario 3: Die Warme Brücke; Kontext & Tiefe: strategische Abfolge)","status":"entwurf","scenario":"Deine Tante ruft dich panisch an: Sie ist überzeugt, dass „die da oben“ das Trinkwasser vergiften. Sie redet schnell, ihre Stimme zittert. Du willst ihr helfen, ohne selbst in ihre Panik hineingezogen zu werden und ohne sie wie einen Fall zu behandeln.","kurz":"Erst verstehen, warum sie so denkt, dann ihre Angst kurz spiegeln und ruhig bleiben: So fühlt sie sich ernst genommen, ohne dass die Panik auf dich übergeht. Der naheliegende Fehler ist, sofort Fakten oder Sachargumente zu liefern, die in der Aufregung nicht ankommen.","prueffrage":"Was hättest du an ihrer Stelle in diesem Moment von der Person am anderen Ende der Leitung gebraucht?","rueckmeldung":[{"option":1,"text":"Berichte und Zahlen sind eine gute Grundlage, wenn sie wieder ruhig ist. Mitten in der Panik kommen sie aber kaum an, und sie hat womöglich den Eindruck, dass ihre Angst gar nicht gehört wurde."},{"option":2,"text":"Ihre Angst freundlich zu benennen ist richtig, und in der Panik bringt ein Gespräch tatsächlich wenig. Wer sie aber auf später vertröstet, lässt sie in diesem Moment mit der Angst allein."},{"option":3,"text":"Zu wissen, woher die Befürchtung kommt, kann beim Verstehen helfen. Wenn du aber zuerst jede Quelle einzeln durchgehst, wirkt das schnell wie ein Verhör, und ihr Gefühl bleibt dabei unbeachtet."}],"familie":"gefuehl-zuerst-aufgreifen","fertigkeit":"F3","quellen":[{"typ":"doi","kurz":"Klimecki, Leiberg, Ricard & Singer (2014): Differential Pattern of Functional Brain Plasticity After Compassion and Empathy Training. Social Cognitive and Affective Neuroscience 9(6)","oeffentlich":true,"doi":"10.1093/scan/nst060","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC4040103/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Singer & Klimecki (2014): Empathy and Compassion. Current Biology 24(18), R875–R878 (Verlagsseite hier nicht geöffnet; Register b2a0fd0f299 am Volltext bestätigt)","oeffentlich":false,"doi":"10.1016/j.cub.2014.06.054"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"7f50ad0553558483"}},{"id":"qx-h-031","clusterId":"H","werkstueckRef":"H.1.6","stufe":3,"question":"Wo liegt das Risiko in dieser Haltung des Kollegen?","scenario":"Ein Kollege sagt über seinen Onkel, der an eine Verschwörungserzählung glaubt: „Ich durchschaue seine Logik perfekt und kann jeden Schritt nachvollziehen. Aber er wirft mir vor, kalt zu sein, und fühlt sich wie unter dem Mikroskop.“","options":["Er versteht die Logik des Onkels so genau, dass er sie womöglich selbst übernimmt; so droht er, in die Erzählung hineingezogen zu werden.","Er hält sein Verständnis für perfekt und prüft es nicht mehr; so übersieht er womöglich, was er am Denken des Onkels noch nicht begriffen hat.","Er nutzt das Verstehen nur zum Analysieren, ohne Fürsorge für den Onkel; so wirkt es wie Sezieren und dient nicht mehr dem Helfen.","Er hält die Gefühle des Onkels auf Abstand, statt sie mitzuspüren und zu teilen; so fehlt ihm das Mitleiden, ohne das er ihn kaum erreicht."],"correctIndex":2,"explanation":"Der Kollege versteht den Onkel gedanklich sehr gut, aber dieses Verstehen bleibt ohne Wärme und ohne den Wunsch zu helfen. Der Onkel spürt das: Er fühlt sich analysiert statt ernst genommen. Das Problem ist also nicht zu wenig Verständnis, sondern zu wenig Fürsorge. Wer nur versteht, kann sein Gegenüber im schlimmsten Fall zum Untersuchungsobjekt machen oder sich überlegen fühlen. Wer dagegen zu stark mitleidet, wird von den fremden Gefühlen überschwemmt und zieht sich irgendwann erschöpft zurück; dafür gibt es hier aber keinen Hinweis, denn der Kollege fühlt ja gerade wenig. Ein Gespräch kommt in Gang, wenn zum Verstehen die Sorge um den anderen dazukommt, ohne dessen Panik zu übernehmen. Ein einseitiges Bild durch Bestätigungsfehler setzte voraus, dass er nur Passendes sammelt, doch davon ist keine Rede. Auch ein vorschnelles Urteil über den Charakter des Onkels steht nicht im Szenario, er versteht ja gerade die Gründe seines Denkens.","coreRule":"⚡ Verstehen ohne Fürsorge wird kalt, Fürsorge ohne Abstand wird Panik.","quote":"","quoteLabel":"","beleg":"Werkstück H.1.6 (Der Kipppunkt; Red Flags: Anzeichen für ein Ungleichgewicht; Szenario 2: Die Kalte Analyse)","status":"entwurf","kurz":"Der Kollege versteht gut, aber ohne Wärme und ohne den Wunsch zu helfen, und der Onkel spürt das. Man nimmt leicht an, mehr Verständnis löse alles. Hier fehlt aber die Fürsorge, und ohne sie wird aus dem Verstehen ein Untersuchen.","prueffrage":"Was sagt der Kollege über sein eigenes Verständnis, und was sagt der Onkel über das Gespräch?","rueckmeldung":[{"option":0,"text":"Wer jemandes Denken so genau kennt, könnte tatsächlich in Versuchung geraten, mitzugehen. Davon steht im Szenario nichts: Nachvollziehen heißt nicht zustimmen. Der Onkel klagt über Kälte, nicht über eine Ansteckung."},{"option":1,"text":"Selbstsicherheit mit dem eigenen Verständnis kann blind machen. Hier nennt das Szenario aber weder eine Lücke noch ein Nachlassen im Prüfen. Der Onkel leidet daran, wie er behandelt wird, nicht daran, dass der Kollege ihn falsch versteht."},{"option":3,"text":"Dass dem Kollegen etwas Gefühlsmäßiges fehlt, trifft zu. Ein Mitleiden mit allem Drum und Dran wäre aber selbst riskant: Es überschwemmt und führt zum Rückzug. Gesucht ist Sorge um den anderen, ohne seine Panik zu übernehmen."}],"familie":"gefuehl-zuerst-aufgreifen","fertigkeit":"F3","quellen":[{"typ":"doi","kurz":"Klimecki, Leiberg, Ricard & Singer (2014): Differential Pattern of Functional Brain Plasticity After Compassion and Empathy Training. Social Cognitive and Affective Neuroscience 9(6)","oeffentlich":true,"doi":"10.1093/scan/nst060","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC4040103/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Singer & Klimecki (2014): Empathy and Compassion. Current Biology 24(18), R875–R878 (Verlagsseite hier nicht geöffnet; Register b2a0fd0f299 am Volltext bestätigt)","oeffentlich":false,"doi":"10.1016/j.cub.2014.06.054"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"bf9f081828d723cc"}},{"id":"qx-h-032","clusterId":"H","werkstueckRef":"H.1.6","stufe":4,"question":"Eine Kollegin sagt: „Mitleiden und Mitgefühl sind im Gehirn im Grunde dasselbe.“ Welche Beobachtung widerspricht dieser Behauptung am stärksten?","options":["Nach dem Mitempfinden-Training ist vor allem das Schmerz- und Negativsystem aktiver, nach dem Fürsorge-Training dagegen das Belohnungs- und Zugehörigkeitssystem.","Nach beiden Trainings ist vor allem das Schmerz- und Negativsystem aktiver, nach dem Fürsorge-Training kommt das Belohnungs- und Zugehörigkeitssystem noch hinzu.","Nach dem Mitempfinden-Training ist das Schmerz- und Negativsystem deutlich stärker aktiv als nach dem Fürsorge-Training, andere Systeme unterscheiden sich kaum.","Nach dem Mitempfinden-Training erleben die Teilnehmer nach eigener Auskunft vor allem belastende, nach dem Fürsorge-Training vor allem wohltuende Gefühle gegenüber anderen."],"correctIndex":0,"explanation":"Die Behauptung setzt Mitleiden und Mitgefühl gleich. Am stärksten widerspricht ihr ein Befund, in dem beide Trainings jeweils ein anderes Hirnsystem ansprechen. Genau das zeigten Trainingsstudien von Klimecki und Kollegen (2014): Nach dem Empathie-Training waren Insula und anteriorer cingulärer Cortex aktiver (Schmerz, negativer Affekt), nach dem Mitgefühls-Training ventrales Striatum und medialer orbitofrontaler Cortex (Belohnung, Zugehörigkeit). Die Begriffe folgen der Arbeitsgruppe um Singer und Klimecki; andere Autoren teilen anders ein.","coreRule":"⚡ Wenn zwei Dinge angeblich dasselbe sind, prüfe, ob sie sich unter Test unterschiedlich verhalten: Mitleiden und Mitgefühl lassen sich im Gehirn unterscheiden.","beleg":"Werkstück H.1.6 (Kontext & Tiefe); Fn. gl-h-empathie (Singer/Klimecki 2014, Current Biology 24(18), S. R875–R878; Klimecki u. a. 2014, SCAN 9(6), S. 873–879)","status":"entwurf","scenario":"In einer Trainingsstudie übt eine Gruppe zunächst, die Gefühle anderer mitzuempfinden, und anschließend, sich fürsorglich um andere zu sorgen. Dabei wird die Hirnaktivität gemessen.","kurz":"Die Behauptung spricht von „im Gehirn“. Widerlegen kann sie nur, wenn jedes Training ein anderes Hirnsystem anspricht. Wer nur Erleben, Stärke oder Überlappung vergleicht, lässt „im Grunde dasselbe“ stehen.","prueffrage":"Was genau behauptet die Kollegin über das Gehirn, und welches Messergebnis wäre mit ihrer Behauptung noch vereinbar?","rueckmeldung":[{"option":1,"text":"Dass beide Trainings dasselbe System ansprechen, passt eher zur Gleichsetzung. Der Zusatz beim Fürsorge-Training ändert daran wenig, denn eine gemeinsame Basis mit einem Extra ist noch kein getrenntes Muster. Widerlegen würde erst ein Befund, in dem das Hauptmuster auseinandergeht."},{"option":2,"text":"Ein deutlicher Unterschied in nur einem System zeigt vor allem einen Unterschied in der Stärke. Das ist mit „im Grunde dasselbe“ vereinbar, denn dasselbe System kann mal mehr und mal weniger aktiv sein. Es fehlt ein eigenes Muster für das zweite Training."},{"option":3,"text":"Belastend gegenüber wohltuend ist ein plausibler Unterschied im Erleben. Die Behauptung betrifft aber das Gehirn, und Selbstauskünfte messen es nicht. Dieselbe Hirnaktivität könnte verschieden empfunden werden, daher widerspricht dieser Befund nicht am stärksten."}],"familie":"widerlegung-benennen","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Klimecki, Leiberg, Ricard & Singer (2014): Differential Pattern of Functional Brain Plasticity After Compassion and Empathy Training. Social Cognitive and Affective Neuroscience 9(6)","oeffentlich":true,"doi":"10.1093/scan/nst060","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC4040103/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Singer & Klimecki (2014): Empathy and Compassion. Current Biology 24(18), R875–R878 (Verlagsseite hier nicht geöffnet; Register b2a0fd0f299 am Volltext bestätigt)","oeffentlich":false,"doi":"10.1016/j.cub.2014.06.054"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v9","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"ok","pruefsumme":"94a1e393e44f1b92"}},{"id":"qx-h-033","clusterId":"H","werkstueckRef":"H.2.1","stufe":1,"question":"Welche Reaktion ist in diesem Moment am sinnvollsten und warum?","options":["„Das klingt, als würdest du dich von Leuten wie mir nicht ernst genommen fühlen. Habe ich das richtig verstanden?“","„Du sprichst von ‚Blase‘ und ‚echtem Leben‘. Wollen wir gemeinsam nachschlagen, was Studien zu Akademikern und ihrer Lebenserfahrung sagen?“","„‚Alle‘ ist ein großes Wort, Onkel. Das ist eine Verallgemeinerung über Studierte, oder kennst du wirklich keinen, der anders ist?“","„Vielleicht hast du recht, und wir sitzen oft in unserer Blase. Sollen wir das Thema wechseln, damit der Abend ruhig bleibt?“"],"correctIndex":0,"explanation":"In einem eskalierten Gespräch hat das emotionale System 1 die Kontrolle, und System 2 arbeitet nur noch als dessen Anwalt. Ein Fakten-Argument kommt in diesem Zustand kaum an und nährt eher den Streit. Wer stattdessen das Gefühl aufgreift, ohne der Behauptung zuzustimmen, nimmt dem Gegenüber das Bedürfnis, lauter zu werden, und öffnet eine Tür für ein echtes Gespräch. Gemeinsames Nachschlagen klingt kooperativ, macht das Gespräch aber zum Wettstreit um das Rechthaben. Eine Verallgemeinerung zu benennen ist ein anerkanntes Denkwerkzeug, trifft hier aber auf einen Menschen, der sich gerade nicht ernst genommen fühlt, und wirkt wie ein Angriff. Das bloße Zustimmen und Themawechseln gibt die eigene Position auf, nur um Ruhe zu haben. Ein hitziger Moment verlangt, das Gespräch zu retten, statt Recht zu haben.","coreRule":"⚡ Im Feuer erst das Gefühl aufgreifen, nicht den Inhalt bestätigen und nicht mit Fakten kontern.","quote":"","quoteLabel":"","beleg":"Werkstück H.2.1 (Die Taktische Matrix: vier Kern-Techniken; Kontext & Tiefe)","status":"freigegeben","freigabe":{"datum":"2026-10-15","pruefsumme":"940f5fad41c158a5","vermerk":"Prüfpult (Sturm, erste Charge nach den neuen falschen Optionen)"},"scenario":"Bei einer Familienfeier sagt dein Onkel laut: „Ihr Studierten seid doch alle gleich! Ihr sitzt in eurer arroganten Blase und habt keine Ahnung vom echten Leben!“ Du merkst, wie dein Puls steigt und du am liebsten sofort mit Fakten kontern würdest.","kurz":"Wer das Gefühl hinter dem Vorwurf aufgreift, ohne ihm zuzustimmen, entzieht dem Streit den Treibstoff und lässt ein Gespräch zu. Der naheliegende Fehler, sofort mit Fakten zu kontern, trifft im aufgeheizten Moment kaum an und nährt eher den Streit.","prueffrage":"Was verrät der Ton deines Onkels über seinen Zustand, und wie viel Offenheit für Zahlen ist da gerade zu erwarten?","rueckmeldung":[{"option":1,"text":"Gemeinsames Nachschlagen klingt kooperativ und sachlich. Es macht den Moment aber zum Wettstreit um das Rechthaben, und sein Gefühl, nicht ernst genommen zu werden, bleibt unbeachtet. So wird er eher lauter."},{"option":2,"text":"Eine Verallgemeinerung zu benennen ist ein gutes Denkwerkzeug, und „alle“ stimmt hier tatsächlich nicht. Bei jemandem, der sich gerade nicht ernst genommen fühlt, kommt der Hinweis aber wie ein Angriff an und stützt seinen Eindruck eher."},{"option":3,"text":"Den Abend ruhig zu halten ist ein verständliches Anliegen. Mit der Zustimmung gibst du aber deine eigene Position auf, nur um Ruhe zu haben, und gehst weder auf sein Gefühl noch auf die Behauptung ein. Ein echtes Gespräch entsteht so nicht."}],"familie":"gefuehl-zuerst-aufgreifen","fertigkeit":"F3","quellen":[{"typ":"doi","kurz":"Richmond, Berlin, Fishkind u. a. (2012): Verbal De-escalation of the Agitated Patient: Consensus Statement of the American Association for Emergency Psychiatry Project BETA De-escalation Workgroup. West J Emerg Med 13(1)","oeffentlich":true,"doi":"10.5811/westjem.2011.9.6864","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC3298202/","abruf":"2026-10-12"},{"typ":"url","kurz":"Lewandowsky, Cook, Ecker u. a. (2020): The Debunking Handbook 2020 (doi 10.17910/b7.1182; geöffnet als PDF bei Skeptical Science)","oeffentlich":true,"url":"https://skepticalscience.com/docs/DebunkingHandbook2020.pdf","seite":"9","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"940f5fad41c158a5"}},{"id":"qx-h-034","clusterId":"H","werkstueckRef":"H.2.1","stufe":2,"question":"Welche Antwort ist am ehesten geeignet, die Lage zu beruhigen und das Gespräch zu retten, ohne dem Vorwurf zuzustimmen?","scenario":"In einer hitzigen Diskussion ruft dein Gegenüber laut: „Ihr Wissenschaftsgläubigen seid doch alle gleich! Ihr steckt in eurer arroganten Blase und habt keine Ahnung vom echten Leben!“ Du merkst, wie sich dein eigener Puls beschleunigt.","options":["„Du hast völlig recht: Wir Wissenschaftsgläubigen sind arrogant. Lass uns das Thema einfach fallen lassen, bevor es noch unangenehmer wird.“","„Wenn du jetzt pauschal alle über einen Kamm scherst, ist das kein Argument. Ich gehe auf Beleidigungen nicht ein und antworte erst wieder sachlich.“","„Es klingt, als wärst du frustriert und hättest das Gefühl, dass Leute wie ich auf dich herabschauen. Habe ich das richtig verstanden?“","„Ich verstehe deine Wut, aber sie kommt nur daher, dass du die Studienlage nicht kennst. Hier sind die wichtigsten Zahlen dazu.“"],"correctIndex":2,"explanation":"In einem eskalierten Gespräch bestimmen Gefühle und schnelle, intuitive Reaktionen das Geschehen, und Argumente kommen kaum noch an. Wer den Köder ignoriert und stattdessen das dahinterliegende Gefühl benennt, nimmt dem Streit Energie und öffnet eine kleine Tür zum Gespräch. Die richtige Antwort tut genau das und fragt nach, statt zu urteilen. Die Zustimmung zum Vorwurf ist keine Deeskalation, sondern Unterwerfung: Du stimmst einer Aussage zu, die du selbst nicht teilst; ein Gefühl zu validieren ist nicht dasselbe wie den Inhalt zu validieren. Der Hinweis auf „Beleidigungen“ ist ein Gegenvorwurf und verschiebt den Streit auf die Frage, wer sich falsch verhält. Die Antwort mit „Ich verstehe deine Wut, aber …“ behauptet, das Gegenüber kenne die Studienlage nicht, und wirft ein Fakten-Argument ins Feuer, das kaum ankommt und den Streit eher nährt.","coreRule":"⚡ Antworte auf das Gefühl, nicht auf den Köder.","beleg":"Werkstück H.2.1 (Die Geschichte, Reaktion B; Technik 1: Gefühle validieren; Der Kipppunkt: Deeskalation ist keine Unterwerfung; Kontext & Tiefe: Fakten-Argument im Feuer)","status":"entwurf","kurz":"Im Streit ist das Gegenüber emotional aufgewühlt und Argumente kommen kaum an. Wer das Gefühl hinter dem Vorwurf benennt und nachfragt, nimmt dem Streit Energie, ohne dem Inhalt zuzustimmen oder zurückzuschlagen.","prueffrage":"Wie laut und wie sachlich spricht dein Gegenüber gerade, und wie viel von dem, was du sagst, kommt in diesem Zustand bei ihm an?","rueckmeldung":[{"option":0,"text":"Nachzugeben beendet den Streit schnell und fühlt sich nach Frieden an. Du stimmst aber einer Aussage zu, die du selbst nicht teilst. Das ist Unterwerfung: Ein Gefühl ernst zu nehmen heißt nicht, den Inhalt zu bestätigen."},{"option":1,"text":"Die pauschale Zuschreibung ist wirklich kein Argument, und Grenzen zu setzen ist legitim. Der Satz klingt aber nach Gegenvorwurf und kündigt Rückzug an. So geht es bald darum, wer sich falsch verhält, und das Gefühl dahinter bleibt unbeachtet."},{"option":3,"text":"Sachlich zu bleiben und Zahlen zu nennen wirkt vernünftig. Doch das „aber“ entwertet das Verständnis, die Unterstellung, er kenne die Studienlage nicht, ist ein neuer Vorwurf, und Zahlen kommen in so einer Lage kaum an."}],"familie":"gefuehl-zuerst-aufgreifen","fertigkeit":"F3","quellen":[{"typ":"doi","kurz":"Richmond, Berlin, Fishkind u. a. (2012): Verbal De-escalation of the Agitated Patient: Consensus Statement of the American Association for Emergency Psychiatry Project BETA De-escalation Workgroup. West J Emerg Med 13(1)","oeffentlich":true,"doi":"10.5811/westjem.2011.9.6864","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC3298202/","abruf":"2026-10-12"},{"typ":"url","kurz":"Lewandowsky, Cook, Ecker u. a. (2020): The Debunking Handbook 2020 (doi 10.17910/b7.1182; geöffnet als PDF bei Skeptical Science)","oeffentlich":true,"url":"https://skepticalscience.com/docs/DebunkingHandbook2020.pdf","seite":"9","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"5ed412c5560bad2d"}},{"id":"qx-h-035","clusterId":"H","werkstueckRef":"H.2.1","stufe":2,"question":"Dein Onkel hat beim Familienfest gerade behauptet, die Impfstudien seien alle gekauft. Du willst widersprechen, ohne dass er sofort in die Verteidigung geht. Welche Formulierung beschreibt deine eigene Wahrnehmung, statt ihm etwas zuzuschreiben?","options":["„Mich beunruhigt, dass du den Studien so wenig traust. Du lässt dich offenbar von Misstrauen leiten.“","„Unabhängige Fachleute prüfen solche Studien mehrfach. Die Ergebnisse sind in der Fachwelt breit anerkannt.“","„Ich habe den Eindruck, dass du dich nicht gründlich informiert hast. Du bleibst lieber bei deiner Meinung.“","„Die Studien, die ich bisher gesehen habe, deuten für mich in eine andere Richtung. Das verwirrt mich.“"],"correctIndex":3,"explanation":"Eine Aussage, die deine eigene Wahrnehmung beschreibt, ist eine persönliche Zustandsbeschreibung: Sie ist unangreifbar und lädt zur Klärung ein. Wer dem anderen dagegen eine Eigenschaft zuschreibt, erhebt eine Anklage, auch wenn ein „ich“ oder ein Gefühl im Satz steht („Ich habe den Eindruck, dass du dich nicht gründlich informiert hast“; „Mich beunruhigt, dass du den Studien so wenig traust“). Solche Anklagen zwingen das Gegenüber in eine Verteidigungshaltung. Der Verweis auf Fachleute ist sachlich zutreffend, beschreibt aber nicht dein eigenes Erleben, sondern stellt eine Autorität gegen den Onkel und lädt zur Gegenwehr ein. Eskaliert ein Gespräch, geht es nur noch um Gewinnen und Verlieren. Eine Aussage über dein eigenes Erleben dagegen greift ihn nicht an.","coreRule":"⚡ Prüfe nicht, ob „ich“ im Satz steht, sondern ob du beschreibst, was bei dir ankommt, oder sagst, was der andere ist.","beleg":"Werkstück H.2.1 (Die Taktische Matrix: Technik 2, „Ich“-Botschaften)","status":"entwurf","scenario":"Beim Familienfest wird die Stimmung hitzig. Dein Onkel sagt laut: „Die Impfstudien sind doch alle von der Industrie gekauft!“ Du willst dagegenhalten, aber das Gespräch nicht noch weiter anheizen.","kurz":"Wer beschreibt, was er selbst wahrnimmt, macht eine Aussage, die niemand widerlegen kann und die zur Klärung einlädt. Ein „ich“ im Satz reicht nicht: Eine Zuschreibung wie „du vertraust nicht“ bleibt eine Anklage und ruft Verteidigung hervor.","prueffrage":"Worüber sagt der Satz etwas aus: über das, was du erlebst, oder über die Person, der du antwortest?","rueckmeldung":[{"option":0,"text":"Ein Gefühl am Satzanfang lässt ihn nach einer Ich-Botschaft klingen. Doch „Du lässt dich von Misstrauen leiten“ ist eine Zuschreibung an ihn, also eine Anklage, auf die er sich verteidigen wird."},{"option":1,"text":"Der Hinweis auf unabhängige Prüfung ist sachlich zutreffend. Er beschreibt aber nicht, was du selbst wahrnimmst, sondern stellt eine Autorität gegen deinen Onkel. Das lädt eher zur Gegenwehr ein als zur Klärung."},{"option":2,"text":"„Ich habe den Eindruck“ klingt nach eigener Sicht, doch gesagt wird, er habe sich nicht gründlich informiert und hänge an seiner Meinung. Das ist eine Eigenschaft, die du ihm zuschreibst, und er wird sich dagegen wehren."}],"familie":"gefuehl-zuerst-aufgreifen","fertigkeit":"F3","quellen":[{"typ":"doi","kurz":"Rogers, Howieson & Neame (2018): I understand you feel that way, but I feel this way: the benefits of I-language and communicating perspective during conflict. PeerJ 6:e4831","oeffentlich":true,"doi":"10.7717/peerj.4831","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC5961625/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"414682ce74178680"}},{"id":"qx-h-036","clusterId":"H","werkstueckRef":"H.2.1","stufe":3,"question":"Welche der vier Reaktionen sorgt zwar für Ruhe, gibt dafür aber eine falsche Behauptung preis?","scenario":"Dein Onkel behauptet am Familientisch, Echsenmenschen kontrollierten die Regierung, und wird dabei immer lauter. Du willst verhindern, dass der Abend eskaliert.","options":["„Ich verstehe deine Sorge. Der Regierung nicht blind zu vertrauen, kann ich gut nachvollziehen.“","„Na gut, vielleicht ist da was dran. Hauptsache, wir haben heute Abend unseren Frieden.“","„Darüber reden wir lieber ein andermal in Ruhe. Heute Abend lass uns einfach gemütlich essen.“","„Du hast ein Recht auf deine Meinung. Heute Abend muss keiner von uns den anderen überzeugen.“"],"correctIndex":1,"explanation":"Beruhigen und zustimmen sind zwei verschiedene Dinge. Du kannst das Gefühl deines Gegenübers anerkennen, eine Pause vorschlagen oder eine gemeinsame Absicht benennen, ohne dabei die Sachbehauptung gelten zu lassen. Dein Onkel erfährt in diesen Fällen: Ich nehme dich ernst, aber ich teile deine Aussage nicht. „Vielleicht ist da was dran“ dagegen signalisiert Zustimmung zu einer unbelegten Behauptung, nur um Ruhe zu haben. Der Frieden wird damit mit einer Unwahrheit erkauft, und der Onkel fühlt sich in seiner Überzeugung bestätigt. Deeskalieren soll das Gespräch offenhalten, nicht die eigene Position aufgeben.","coreRule":"⚡ Gefühle darfst du bestätigen, falsche Behauptungen nicht.","beleg":"Werkstück H.2.1 (Der Kipppunkt; Die Taktische Matrix)","status":"entwurf","kurz":"Wer sagt „Vielleicht ist da was dran“, kauft sich Ruhe mit einer Unwahrheit und bestärkt den Onkel. Beruhigen geht auch ohne Zustimmung: Gefühl anerkennen, Pause vorschlagen, die Aussage aber nicht gelten lassen.","prueffrage":"Was erfährt dein Onkel über deine Sicht auf seine Behauptung, wenn er nur deine Antwort hört?","rueckmeldung":[{"option":0,"text":"Hier wird das Misstrauen gegenüber der Regierung ernst genommen, die Behauptung über Echsenmenschen aber nicht bestätigt. Genau so lässt sich beruhigen, ohne etwas preiszugeben; deshalb ist das hier nicht die gesuchte Reaktion."},{"option":2,"text":"Das Thema auf später zu verschieben, wirkt ausweichend, ist aber eine zulässige Deeskalation. Die Behauptung wird dabei weder bestätigt noch als wahr behandelt, es wird lediglich eine Pause gesetzt."},{"option":3,"text":"Das Recht auf eine eigene Meinung zu betonen und den Überzeugungsdruck herauszunehmen, nimmt Tempo aus dem Streit. Dabei wird nichts für wahr erklärt: Die Aussage über die Echsenmenschen bleibt unbestätigt."}],"familie":"gefuehl-zuerst-aufgreifen","fertigkeit":"F3","quellen":[{"typ":"doi","kurz":"Richmond, Berlin, Fishkind u. a. (2012): Verbal De-escalation of the Agitated Patient: Consensus Statement of the American Association for Emergency Psychiatry Project BETA De-escalation Workgroup. West J Emerg Med 13(1)","oeffentlich":true,"doi":"10.5811/westjem.2011.9.6864","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC3298202/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"103ee7837c5f7190"}},{"id":"qx-h-037","clusterId":"H","werkstueckRef":"H.2.2","stufe":1,"question":"Du sprichst mit einer Kollegin, die fest überzeugt ist, dass ihr Wundermittel gegen Migräne hilft. Du willst herausfinden, wie sie zu dieser Überzeugung gekommen ist, ohne sie anzugreifen. Welche Frage hilft dir, ihre Überzeugung genauer zu fassen und die Methode dahinter zu klären?","options":["„Wie sicher bist du auf einer Skala von 0 bis 100, und was ist der Hauptgrund für diese Einschätzung?“","„Was genau meinst du mit ‚hilft‘, und werden die Anfälle dadurch seltener oder nur schwächer?“","„Bist du dir da wirklich so sicher, oder könnte die Wirkung nicht auch einfach Zufall sein?“","„Wie oft hast du das Mittel schon ausprobiert, und wie schnell setzt die Wirkung bei dir ein?“"],"correctIndex":0,"explanation":"„Absolut sicher“ ist ein Entweder-oder, über das sich schlecht reden lässt. Eine Skala von 0 bis 100 macht daraus ein flexibles Spektrum, an dem man gemeinsam ansetzen kann: Warum 95 und nicht 60? Die anschließende Frage nach dem Hauptgrund deckt die Methode auf, auf der die Sicherheit beruht (zum Beispiel eigene Erfahrung oder ein Tipp einer Freundin). Genau diese Methode lässt sich dann auf ihre Verlässlichkeit prüfen, ohne dass du die Schlussfolgerung angreifst. Die Frage nach Dauer und Häufigkeit der Anfälle zeigt Anteilnahme, klärt aber nicht, worauf ihre Sicherheit beruht. Nebenwirkungen und Beipackzettel sind ein sinnvolles Thema, doch hier geht es um ihre Überzeugung, nicht um das Mittel. Wie die Anfälle den Arbeitsalltag belasten, rückt die Person in den Blick, nicht aber den Weg zu ihrer Überzeugung.","coreRule":"⚡ Frag erst nach dem Grad der Sicherheit, dann nach dem Grund dafür, nicht nach dem Urteil.","beleg":"Werkstück H.2.2 (Kontext & Tiefe: Schritte 3 und 4, 6)","status":"entwurf","scenario":"Deine Kollegin sagt: „Ich bin mir absolut sicher, dass dieses Mittel gegen Migräne hilft.“ Du möchtest weder streiten noch sofort Studien auf den Tisch legen, sondern verstehen, worauf ihre Sicherheit beruht.","kurz":"Eine Skala von 0 bis 100 macht aus „absolut sicher“ ein Spektrum, an dem man ansetzen kann, und die Frage nach dem Hauptgrund legt offen, worauf die Sicherheit beruht. So prüfst du die Methode, ohne ihre Schlussfolgerung anzugreifen.","prueffrage":"Was hat deine Kollegin bisher tatsächlich gesagt: Nennt sie einen Grund für ihre Sicherheit oder nur die Sicherheit selbst?","rueckmeldung":[{"option":1,"text":"Zu klären, was „hilft“ heißt, ist sinnvoll, denn Anfälle können seltener oder schwächer werden. Es sagt aber nichts darüber, woher ihre Sicherheit kommt; dafür müsstest du nach dem Grund fragen."},{"option":2,"text":"Wer die Sicherheit gleich anzweifelt und den Zufall ins Spiel bringt, löst eher Verteidigung aus. Die Frage greift die Schlussfolgerung an, statt zu klären, worauf sie beruht, und unterstellt schon eine Antwort."},{"option":3,"text":"Wie oft sie das Mittel genommen hat und wann es wirkt, zeigt Interesse und liefert Hintergrund. Ob ihre Sicherheit auf eigener Erfahrung, einem Tipp oder etwas anderem beruht, bleibt damit aber offen."}],"familie":"nach-weg-und-kriterium-fragen","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Street Epistemology International: Using a Confidence Scale in Street Epistemology (31.05.2026)","oeffentlich":true,"url":"https://www.streetepistemology.com/blog/nb-m08-using-a-confidence-scale-in-street-epistemology","abruf":"2026-10-12"},{"typ":"url","kurz":"Street Epistemology International: What Is Street Epistemology? A Beginner's Introduction (12.04.2026)","oeffentlich":true,"url":"https://www.streetepistemology.com/blog/nb-m01-what-is-street-epistemology","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"a36a2320b70530b6"}},{"id":"qx-h-038","clusterId":"H","werkstueckRef":"H.2.2","stufe":2,"question":"Welche Anschlussfrage ist dafür am besten geeignet?","scenario":"Ein Kollege ist zu 95 Prozent sicher, dass Rosenquarz Kopfschmerzen heilt. Seine Begründung: Eine Freundin hat es empfohlen, und bei ihm selbst hörten die Beschwerden danach auf. Du möchtest mit ihm ins Gespräch kommen, ohne dass er sich angegriffen fühlt, und ihm helfen, die Verlässlichkeit seiner Begründung selbst zu prüfen.","options":["„Du verlässt dich also auf den Rat deiner Freundin. Wie lange benutzt sie den Stein schon? Haben ihr die Kopfschmerzen danach auch aufgehört?“","„Du hast also gemerkt, dass deine Kopfschmerzen nach dem Kristall aufhörten. Wann genau ließen sie nach? Wie hat sich das angefühlt?“","„Du bist dir also zu 95 Prozent sicher. Hast du auch eine Ärztin zu deinen Kopfschmerzen gefragt? Was sagte sie zum Rosenquarz?“","„Du verlässt dich also auf deine Erfahrung. Wie ließe sich prüfen, ob wirklich der Kristall geholfen hat? Welcher Weg wäre am verlässlichsten?“"],"correctIndex":3,"explanation":"Wer die Überzeugung eines Menschen direkt angreift, löst meist Abwehr aus, und mit Abwehr endet das Nachdenken. Besser ist es, zuerst zu verstehen, worauf sich die Sicherheit stützt, und dann gemeinsam zu prüfen, ob dieser Weg verlässlich ist. Hier ist die Begründung eine einzelne Erfahrung: Die Kopfschmerzen hörten nach dem Kristall auf. Das passt aber ebenso zum Placebo-Effekt oder dazu, dass sie von allein vergangen wären. Die Frage, wie man das auseinanderhalten könnte, lädt zum Mitdenken ein, ohne ein Urteil zu fällen.","coreRule":"⚡ Frag nach dem Weg zur Überzeugung und lade zum gemeinsamen Prüfen ein, statt das Ergebnis anzugreifen.","beleg":"Werkstück H.2.2 (Die Geschichte, Ansatz B; Kontext & Tiefe: Schritt 5; Red Flags)","status":"freigegeben","freigabe":{"datum":"2026-10-15","pruefsumme":"48aed6a9b773193e","vermerk":"Prüfpult (Sturm, erste Charge nach den neuen falschen Optionen)"},"kurz":"Die Frage nach einer Prüfmöglichkeit lädt zum Mitdenken ein, ohne ihn anzugreifen. Seine Begründung ist eine Einzelerfahrung, die ebenso zu Placebo oder zu Kopfschmerzen passt, die von allein vergingen. Wie man das auseinanderhält, findet er am besten selbst heraus.","prueffrage":"Worauf stützt dein Kollege seine 95 Prozent, und welche Anschlussfrage knüpft an genau diese Stütze an?","rueckmeldung":[{"option":0,"text":"Interesse an der Quelle seiner Sicherheit ist ein guter Einstieg. Doch eine weitere Erfahrung derselben Art prüft nichts: Auch bei der Freundin können Placebo oder von selbst abklingende Beschwerden im Spiel sein."},{"option":1,"text":"Zuhören und Nachfragen nimmt ihm die Abwehr. Wann und wie die Schmerzen nachließen, klärt aber nicht, ob der Stein oder etwas anderes sie beendet hat, und führt ihn nicht dazu, seine Begründung selbst zu prüfen."},{"option":2,"text":"Bei Kopfschmerzen ist ärztlicher Rat vernünftig. Hier soll er aber seine eigene Begründung prüfen, und das übernimmt die Ärztin an seiner Stelle. So lernt er nicht, wie man Erfahrung von Zufall unterscheidet."}],"familie":"nach-weg-und-kriterium-fragen","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Street Epistemology International: What Is Street Epistemology? A Beginner's Introduction (12.04.2026)","oeffentlich":true,"url":"https://www.streetepistemology.com/blog/nb-m01-what-is-street-epistemology","abruf":"2026-10-12"},{"typ":"url","kurz":"Lewandowsky & Cook (2020): The Conspiracy Theory Handbook (Skeptical Science)","oeffentlich":true,"url":"https://skepticalscience.com/docs/ConspiracyTheoryHandbook.pdf","seite":"10","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Boghossian, P. (2013): A Manual for Creating Atheists. Pitchstone Publishing (Begriffsprägung; Register b7b36492df7, sekundär bestätigt)","oeffentlich":false}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"48aed6a9b773193e"}},{"id":"qx-h-039","clusterId":"H","werkstueckRef":"H.2.2","stufe":3,"question":"Bei wem lässt du die Methodenfragen besser weg und stellst einfach richtig?","options":["Bei Nina, denn ihre Berufswahl ist eine persönliche Entscheidung, über deren Methode Fremde nicht mit ihr streiten sollten.","Bei Tarek, denn er ist sich bei den Horoskopen absolut sicher, sodass Fragen nach seiner Methode an ihm abprallen würden.","Bei Ole, denn ob Paris die Hauptstadt Deutschlands ist, ist eine schlichte Tatsache, die eine kurze Richtigstellung klärt.","Bei Ines, denn ihr Weltbild beruht auf Gefühl und Gruppe statt auf Belegen, sodass es keine Methode gibt, nach der man fragt."],"correctIndex":2,"explanation":"Fragen nach der Methode lohnen sich bei tiefen, identitätsstiftenden Überzeugungen: Dort steht die Zuverlässigkeit des Wegs zur Überzeugung im Mittelpunkt, und genau das lässt sich gemeinsam erkunden. Bei einer reinen Tatsachenfrage wie der nach der Hauptstadt Deutschlands ist eine sokratische Befragung dagegen meist überflüssig; bei Ole genügt eine einfache Richtigstellung. Ninas Intuition ist gerade der Weg, dessen Zuverlässigkeit sich gemeinsam erkunden lässt, und ihre eigenen Zweifel bieten dafür einen Anfang. Tareks große Sicherheit ist kein Grund zum Verzicht, denn auch hier geht es um den Weg zu einer tiefen Überzeugung. Bei Ines ist die Übernahme aus der Gruppe selbst die Methode, nach deren Zuverlässigkeit man fragen kann.","coreRule":"⚡ Faktenfragen beantwortest du, Überzeugungen erkundest du.","beleg":"Werkstück H.2.2 (Red Flags: Wann man SE nicht anwenden sollte)","status":"freigegeben","freigabe":{"datum":"2026-10-15","pruefsumme":"e48f97ea4513b98e","vermerk":"Prüfpult (Sturm, erste Charge nach den neuen falschen Optionen)"},"scenario":"Du übst Gespräche, in denen du nicht widersprichst, sondern nach der Methode fragst: „Wie bist du zu dieser Überzeugung gekommen? Wie zuverlässig ist dieser Weg?“ Heute triffst du vier Menschen. Ole hält Paris für die Hauptstadt Deutschlands und beruft sich auf eine vage Erinnerung an eine Schulstunde vor vielen Jahren. Nina ist zu 90 Prozent sicher, dass ihre Intuition ihr den richtigen Beruf zeigt, und bleibt trotz eigener Zweifel dabei. Tarek hält Horoskope für absolut zutreffend und erzählt ausführlich, wie sehr sie ihm im Leben helfen. Ines hat vor Kurzem in einer Gruppe ein Weltbild übernommen und verteidigt es mit viel Gefühl und wenigen echten Belegen.","quote":"","quoteLabel":"","kurz":"Eine reine Tatsachenfrage wie die nach Deutschlands Hauptstadt klärt meist eine kurze Richtigstellung. Der Denkfehler wäre, überall zu befragen: Methodenfragen lohnen sich bei tiefen, identitätsstiftenden Überzeugungen, nicht bei Nachschlagbarem.","prueffrage":"Lässt sich die Überzeugung in Sekunden nachschlagen, oder hängt an ihr etwas, das der Person wichtig ist?","rueckmeldung":[{"option":0,"text":"Berufswahl ist persönlich, und Fremde sollten nicht belehren. Doch Fragen nach der Methode sind kein Streit, sondern gemeinsames Erkunden. Ninas eigene Zweifel an ihrer Intuition bieten dafür sogar einen guten Anfang."},{"option":1,"text":"Tarek wirkt unerschütterlich, und das lässt Fragen aussichtslos erscheinen. Große Sicherheit ist aber kein Grund zum Verzicht: Auch bei ihm geht es um den Weg zu einer tiefen Überzeugung, nach dessen Zuverlässigkeit man fragen kann."},{"option":3,"text":"Ines stützt sich tatsächlich kaum auf Belege. Aber auch das ist ein Weg: Die Übernahme aus der Gruppe ist ihre Methode, und nach deren Zuverlässigkeit lässt sich gerade fragen, statt einfach richtigzustellen."}],"familie":"nach-weg-und-kriterium-fragen","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Street Epistemology International: What Is Street Epistemology? A Beginner's Introduction (12.04.2026)","oeffentlich":true,"url":"https://www.streetepistemology.com/blog/nb-m01-what-is-street-epistemology","abruf":"2026-10-12"},{"typ":"url","kurz":"Lewandowsky, Cook, Ecker u. a. (2020): The Debunking Handbook 2020 (doi 10.17910/b7.1182; geöffnet als PDF bei Skeptical Science)","oeffentlich":true,"url":"https://skepticalscience.com/docs/DebunkingHandbook2020.pdf","seite":"9","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"e48f97ea4513b98e"}},{"id":"qx-h-040","clusterId":"H","werkstueckRef":"H.2.2","stufe":4,"question":"Welche Frage bringt ihn am ehesten dazu, selbst zu prüfen, wie belastbar seine Überzeugung ist?","scenario":"Ein Kollege sagt dir im Gespräch: „Ich bin zu 95 % sicher, dass Heilkristalle Krankheiten heilen. Meine Kopfschmerzen sind verschwunden, als ich einen Rosenquarz benutzt habe, und eine Freundin schwört auch darauf.“ Du willst ihn nicht belehren, sondern ihn zum Nachdenken über seine eigene Überzeugung bringen, ohne dass er sich angegriffen fühlt.","options":["„Was meinst du genau mit ‚Krankheiten heilen‘, und welche gehören für dich dazu?“","„Wie bist du zu dieser Überzeugung gekommen, und wie verlässlich ist dieser Weg?“","„Wie wirkt der Rosenquarz deiner Meinung nach, und warum gerade bei Kopfschmerzen?“","„Was hat deine Freundin erlebt, und hat es bei ihr ähnlich gewirkt wie bei dir?“"],"correctIndex":1,"explanation":"Wer eine tief gehaltene Überzeugung frontal widerlegt, macht sein Gegenüber defensiv, und das Gespräch endet. Wirksamer ist es, nicht die Schlussfolgerung („Kristalle heilen nicht“) anzugreifen, sondern das Verfahren zu untersuchen, mit dem die Person dorthin gekommen ist: Worauf stützt sich die Sicherheit, und kann dieser Weg auch zu falschen Ergebnissen führen? Hier ist der Weg die persönliche Erfahrung („Kopfschmerzen sind verschwunden“). Ob sie verlässlich ist, lässt sich gemeinsam fragen: Wäre der Schmerz vielleicht auch von allein vergangen, oder spielt der Placebo-Effekt eine Rolle? Die Frage, was „Krankheiten heilen“ genau heißen soll, schärft die Aussage, prüft aber nicht den Weg zu ihr.","coreRule":"⚡ Frag nach der Methode, nicht nach der Schlussfolgerung.","beleg":"Werkstück H.2.2 (Street Epistemology); Fn. gl-h-4 (Boghossian 2013, A Manual for Creating Atheists)","status":"entwurf","quote":"","quoteLabel":"","kurz":"Wer fragt, wie jemand zu seiner Überzeugung kam und wie verlässlich dieser Weg ist, greift nicht die Schlussfolgerung an und lädt zum Selbstprüfen ein. Der naheliegende Fehler ist, direkt zu widerlegen, wodurch das Gegenüber defensiv wird und das Gespräch endet.","prueffrage":"Welche Gründe nennt dein Kollege selbst für seine 95 Prozent, und welche davon hat er selbst erlebt?","rueckmeldung":[{"option":0,"text":"Die Frage klärt, was behauptet wird, und das ist ein sinnvoller Gesprächsbeginn. Sie lässt aber offen, wie sicher der Kollege seiner Sache sein darf: Ein genau gefasster Satz kann immer noch auf einem wackligen Weg zustande gekommen sein."},{"option":2,"text":"Die Frage setzt stillschweigend voraus, dass der Rosenquarz wirkt, und bittet nur noch um eine Erklärung dafür. Damit bleibt gerade offen, ob die Erfahrung als Beleg taugt, und der Kollege soll einen Mechanismus liefern, den er vermutlich gar nicht kennt."},{"option":3,"text":"Die Frage ist freundlich und klingt nach Neugier auf die Freundin. Doch auch deren Erfahrung ist eine Einzelerfahrung. Zwei ähnliche Berichte nebeneinander zu stellen kann die Überzeugung eher festigen, als sie auf Verlässlichkeit zu prüfen."}],"familie":"nach-weg-und-kriterium-fragen","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Street Epistemology International: What Is Street Epistemology? A Beginner's Introduction (12.04.2026)","oeffentlich":true,"url":"https://www.streetepistemology.com/blog/nb-m01-what-is-street-epistemology","abruf":"2026-10-12"},{"typ":"url","kurz":"Street Epistemology International: Using a Confidence Scale in Street Epistemology (31.05.2026)","oeffentlich":true,"url":"https://www.streetepistemology.com/blog/nb-m08-using-a-confidence-scale-in-street-epistemology","abruf":"2026-10-12"},{"typ":"url","kurz":"Lewandowsky & Cook (2020): The Conspiracy Theory Handbook (Skeptical Science)","oeffentlich":true,"url":"https://skepticalscience.com/docs/ConspiracyTheoryHandbook.pdf","seite":"10","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"b0331a6a3338a99e"}},{"id":"qx-h-041","clusterId":"H","werkstueckRef":"H.2.3","stufe":1,"question":"Was ist am Vorgehen von Jonas in diesem Gespräch das Problem?","options":["Jonas hört nur so lange zu, bis er einen Punkt zum Widerlegen gefunden hat. Was Mehmet meint und fühlt, bleibt ungeklärt.","Jonas unterbricht Mehmet, sobald dieser Luft holt. Hätte er ihn ausreden lassen, wäre seine Widerlegung eher angekommen.","Jonas widerspricht mit „längst widerlegt“ zu schroff. Vorsichtiger formuliert, hätte Mehmet die Studien eher angenommen.","Jonas ist vom Handy abgelenkt und bekommt nur Bruchstücke mit. Deshalb redet er an Mehmets Schilderung vorbei."],"correctIndex":0,"explanation":"Jonas hört nur scheinbar zu: Die Worte laufen durch seine eigene Agenda, während der Kopf schon die Widerlegung baut. Damit bleibt offen, was Mehmet eigentlich sagen will und was ihn antreibt, etwa Sorge oder Misstrauen. Verstehen entsteht eher, wenn man die Aussage in eigenen Worten zurückgibt, Gefühle benennt, offen nachfragt und Ablenkungen wie das Handy weglässt; erst dann lässt sich prüfen, worüber man überhaupt streitet. Das Handy ist das Werkzeug seines Plans: Er hat Mehmets Zweifel durchaus aufgenommen, sonst könnte er nicht „längst widerlegt“ sagen, er hört nur nicht, um zu verstehen.","coreRule":"⚡ Hör zu, um zu verstehen, nicht um zu antworten.","quote":"","quoteLabel":"","beleg":"Werkstück H.2.3 (Kernidee; Kontext & Tiefe; Werkbank-Frage)","status":"entwurf","scenario":"Jonas' Schwager Mehmet erzählt aufgebracht, dass er nach der Impfung seiner Tochter ernste Zweifel an Medizin und Behörden habe. Jonas nickt, schaut aber nebenbei auf sein Handy und überlegt schon, mit welchen Studien er gleich alles widerlegen kann. Als Mehmet Luft holt, setzt Jonas sofort an: „Das ist alles längst widerlegt, und zwar so …“ Mehmet winkt ab und sagt: „Du hörst mir gar nicht zu.“","kurz":"Jonas hört zu, um zu widerlegen, nicht um zu verstehen. Dass er Mehmets Zweifel aufnimmt, heißt nicht, dass er klärt, was dahintersteckt, etwa Sorge oder Misstrauen. Erst dann lässt sich prüfen, worüber man überhaupt streitet.","prueffrage":"Was tut Jonas, während Mehmet spricht, und was tut er, sobald Mehmet Luft holt?","rueckmeldung":[{"option":1,"text":"Dass Jonas sofort ansetzt, fällt auf. Doch auch mit Ausreden-Lassen würde seine Widerlegung kaum ankommen, solange er innerlich nur auf den Gegenpunkt wartet. Das Problem liegt nicht im Timing, sondern darin, wozu er zuhört."},{"option":2,"text":"Der Ton spielt in solchen Gesprächen eine Rolle. Aber auch eine sanftere Formulierung würde nichts daran ändern, dass Jonas nie geklärt hat, was Mehmet meint und was ihn antreibt. Sie ließe das Nicht-Verstehen nur freundlicher klingen."},{"option":3,"text":"Das Handy lenkt tatsächlich vom Gespräch ab. Gehört hat Jonas Mehmets Zweifel aber durchaus, sonst könnte er nicht „längst widerlegt“ sagen. Er hat zugehört, um zu widerlegen statt zu verstehen, und das Handy dient genau diesem Plan."}],"familie":"fair-wiedergeben","fertigkeit":"F3","quellen":[{"typ":"doi","kurz":"Richmond, Berlin, Fishkind u. a. (2012): Verbal De-escalation of the Agitated Patient: Consensus Statement of the American Association for Emergency Psychiatry Project BETA De-escalation Workgroup. West J Emerg Med 13(1)","oeffentlich":true,"doi":"10.5811/westjem.2011.9.6864","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC3298202/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Kalla & Broockman (2020): Reducing Exclusionary Attitudes through Interpersonal Conversation: Evidence from Three Field Experiments (APSR 114(2), doi 10.1017/S0003055419000923; frei als SocArXiv-Vorabfassung vom 17.01.2020)","oeffentlich":true,"doi":"10.31235/osf.io/2ra9x","seite":"Abstract (S. 1 der Vorabfassung)","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"40daa0bc720be181"}},{"id":"qx-h-042","clusterId":"H","werkstueckRef":"H.2.3","stufe":2,"question":"Welche deiner möglichen Antworten erreicht das am besten?","scenario":"Dein Freund erzählt dir seit einigen Minuten, wie sehr ihn ein Streit mit seiner Chefin beschäftigt. Er sagt: „Ich habe ihr gestern gesagt, dass ich so nicht weiterarbeiten will, und sie hat nur gesagt, das sei kein guter Zeitpunkt. Ich komme mir vor, als wäre ich ihr egal.“ Du willst, dass er sich verstanden fühlt und dass du selbst sicher bist, ihn richtig verstanden zu haben.","options":["„Das kenne ich: Mein früherer Vorgesetzter hat meine Anliegen auch ständig abgetan, und das hat mich damals lange beschäftigt. Du bist nicht allein damit.“","„An deiner Stelle würde ich ihr in Ruhe schreiben, dass du so nicht weiterarbeiten willst, und um ein Gespräch bitten. Dann klärt sich vieles.“","„Wenn ich dich richtig verstehe, stört dich vor allem, dass sie das Gespräch vertagt hat. Du willst bald einen neuen Termin. Stimmt das so?“","„Wenn ich dich richtig verstehe, ärgert dich vor allem, dass sie dein Anliegen abgetan hat. Du fühlst dich nicht ernst genommen. Stimmt das so?“"],"correctIndex":3,"explanation":"Du willst zwei Dinge erreichen: Er soll sich verstanden fühlen, und du willst wissen, ob dein Bild von seiner Lage stimmt. Das gelingt, wenn du in eigenen Worten wiedergibst, was du gehört hast, und ihm die Chance gibst, dich zu korrigieren. So ist dein Verständnis geprüft, bevor du irgendetwas bewertest oder rätst. Eine eigene Geschichte kann Nähe schaffen, macht aber dich zum Mittelpunkt und prüft nicht, ob du ihn richtig verstanden hast. Der Vorschlag, ihr zu schreiben, ist in anderer Lage ein brauchbarer Rat, kommt hier aber, bevor klar ist, was ihn beschäftigt. Die Wiedergabe, es gehe ihm um den verschobenen Termin, wirkt wie Zuhören, trifft aber nicht, was er gesagt hat: Sein Satz, er komme sich vor, als wäre er ihr egal, handelt davon, nicht ernst genommen zu werden, nicht vom Zeitpunkt.","coreRule":"⚡ Gib zurück, was du gehört hast, und frag, ob es stimmt.","beleg":"Werkstück H.2.3 (Technik 1: Paraphrasieren; Red Flags; Werkbank-Frage)","status":"entwurf","kurz":"Wenn du in eigenen Worten sagst, was du gehört hast, und ihn korrigieren lässt, fühlt er sich verstanden und du weißt, ob dein Bild stimmt. Bewerten oder Raten käme vor dieser Prüfung zu früh.","prueffrage":"Was von dem, was der Freund gesagt hat, kannst du wörtlich belegen, und was hast du bisher nur selbst dazugedacht?","rueckmeldung":[{"option":0,"text":"Eine eigene Erfahrung kann Nähe schaffen. Sie rückt aber dich in den Mittelpunkt und zeigt nicht, ob du verstanden hast, was ihn gerade beschäftigt. Ob seine Lage deiner gleicht, ist offen."},{"option":1,"text":"Der Vorschlag ist gut gemeint und in anderer Lage ein brauchbarer Rat. Hier kommt er, bevor klar ist, was ihn belastet, und lässt sein Gefühl, ihr egal zu sein, unbeantwortet."},{"option":2,"text":"Das klingt nach Zuhören, und der Termin kam tatsächlich vor. Sein Satz, er komme sich vor, als wäre er ihr egal, handelt aber davon, nicht ernst genommen zu werden, nicht vom Zeitpunkt. Den Wunsch nach einem neuen Termin hat er auch nicht geäußert."}],"familie":"fair-wiedergeben","fertigkeit":"F3","quellen":[{"typ":"doi","kurz":"Richmond, Berlin, Fishkind u. a. (2012): Verbal De-escalation of the Agitated Patient: Consensus Statement of the American Association for Emergency Psychiatry Project BETA De-escalation Workgroup. West J Emerg Med 13(1)","oeffentlich":true,"doi":"10.5811/westjem.2011.9.6864","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC3298202/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"5190adc0f1abd2f3"}},{"id":"qx-h-043","clusterId":"H","werkstueckRef":"H.2.3","stufe":3,"question":"Was ist jetzt der beste nächste Schritt?","scenario":"Du streitest mit deiner Schwester über die Pflege eurer Mutter. Du bist überzeugt, dass sie sich zu wenig kümmert. Bevor du deinen Standpunkt darlegst, willst du sicherstellen, dass du ihre Sicht wirklich verstanden hast, und fasst sie zusammen: „Du sagst also, dass du dich überfordert fühlst und dir von mir mehr Anerkennung wünschst.“ Sie antwortet: „Na ja, so ungefähr.“","options":["Du erklärst jetzt deinen Standpunkt zur Pflege eurer Mutter, denn sie hat deine Zusammenfassung mit „so ungefähr“ immerhin nicht zurückgewiesen.","Du fragst nach, was an deiner Zusammenfassung noch nicht stimmt, und fasst ihren Standpunkt neu zusammen, bis sie ihn als zutreffend bestätigt.","Du versprichst ihr, ihre Überforderung ernst zu nehmen und ihr mehr Anerkennung zu zeigen, denn das scheint ihr Hauptanliegen zu sein.","Du schlägst vor, die Pflege eurer Mutter nach Wochentagen aufzuteilen, damit sich ihre Überforderung verringert und ihr schnell zu einer Einigung kommt."],"correctIndex":1,"explanation":"Ein halbherziges „so ungefähr“ ist kein Zeichen, dass du sie verstanden hast. Es zeigt eher, dass noch etwas fehlt oder verzerrt ist. Wer jetzt weiterredet, antwortet auf ein Bild von ihr, das sie selbst nicht teilt, und sie fühlt sich weiter missverstanden. Erst wenn sie deine Zusammenfassung aus eigener Sicht als zutreffend bestätigt, etwa mit „Ja, genau“, weißt du, dass ihre Position richtig bei dir angekommen ist. Dafür musst du ihr nicht zustimmen: Verstehen ist nicht Einverstandensein. Es reicht, ihren Standpunkt so zu fassen, dass sie ihn als ihren erkennt. Das Nachfragen kostet anfangs Zeit, verändert aber die Dynamik des Gesprächs, weil sie spürt, dass du ihre Sicht ernsthaft erfassen willst.","coreRule":"⚡ Erst wenn der andere sagt „Ja, genau“, bist du an der Reihe.","beleg":"Werkstück H.2.3 (Die Schmiede-Übung: Die Papageien-Regel)","status":"entwurf","kurz":"Ein halbherziges „so ungefähr“ zeigt eher, dass noch etwas fehlt oder verzerrt ist. Erst wenn sie deine Zusammenfassung als zutreffend bestätigt, weißt du, dass ihre Sicht angekommen ist, und dafür musst du ihr nicht zustimmen.","prueffrage":"Welche Teile deiner Zusammenfassung hat deine Schwester ausdrücklich aufgegriffen oder bestätigt?","rueckmeldung":[{"option":0,"text":"Ihr „so ungefähr“ ist zwar keine Zurückweisung, aber auch keine Bestätigung. Wer jetzt weiterredet, antwortet auf ein ungeprüftes Bild von ihr, und sie fühlt sich womöglich weiter missverstanden."},{"option":2,"text":"Das Versprechen klingt entgegenkommend, stützt sich aber auf eine Zusammenfassung, die sie nicht bestätigt hat. Anerkennung ist vielleicht gar nicht ihr Kern, dann geht das Angebot an ihr vorbei."},{"option":3,"text":"Eine Aufteilung kann später sehr sinnvoll sein, aber erst, wenn beide wissen, worum es dem anderen geht. Dass sie überfordert ist, ist bisher nur deine Deutung, und darauf baut der Vorschlag."}],"familie":"fair-wiedergeben","fertigkeit":"F3","quellen":[{"typ":"doi","kurz":"Richmond, Berlin, Fishkind u. a. (2012): Verbal De-escalation of the Agitated Patient: Consensus Statement of the American Association for Emergency Psychiatry Project BETA De-escalation Workgroup. West J Emerg Med 13(1)","oeffentlich":true,"doi":"10.5811/westjem.2011.9.6864","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC3298202/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"e522ec0f4a3783b0"}},{"id":"qx-h-044","clusterId":"H","werkstueckRef":"H.2.3","stufe":4,"question":"Welche Antwort setzt aktives Zuhören um, wenn dein Ziel ist, dass das Gespräch mit Alex weitergeht?","scenario":"Alex, ein alter Freund, meldet sich nach Monaten: Er schlafe kaum, analysiere nachts „Drops“ und habe Angst um alle, die „es nicht sehen“. Er schreibt: „Manchmal denke ich, ich werde verrückt. Du hältst mich wahrscheinlich für einen Idioten.“","options":["„Danke, dass du dich meldest. Ich höre, dass du kaum schläfst und Angst hast. Ich halte dich nicht für einen Idioten. Magst du erzählen, was dich nachts am meisten beunruhigt?“","„Danke, dass du dich meldest. Ich sehe, dass du kaum schläfst und dich in etwas verrennst. Deshalb schicke ich dir gleich drei Faktenchecks zu den Drops, die das widerlegen.“","„Danke, dass du dich meldest. Ich verstehe dich vollkommen: Wer nachts die Drops analysiert, sieht, was andere nicht sehen. Du bist kein Idiot, und wir ziehen das gemeinsam durch.“","„Danke, dass du dich meldest. Ich höre, dass du kaum schläfst. Du bist nicht verrückt und kein Idiot, das gibt sich wieder. Lass die Drops für heute liegen und schlaf erst mal.“"],"correctIndex":0,"explanation":"Wer verstehen will, was jemand erlebt, nimmt zuerst auf, was er sagt und fühlt: das Gefühl benennen (Angst, Erschöpfung), das Gehörte in eigenen Worten wiedergeben und offen nachfragen. Das hält die Tür offen und liefert dir die Informationen, die du für jedes weitere Gespräch brauchst. Du musst Alex nicht zustimmen, um ihn zu verstehen. Faktenchecks können später ihren Platz haben, antworten jetzt aber auf den Inhalt und überhören den Menschen. Die volle Zustimmung klingt nach Nähe, verwechselt aber Mitgefühl mit Zustimmung, denn du hast den Inhalt weder verstanden noch geprüft. Die schnelle Beruhigung nimmt seine Sorge auf den ersten Blick ernst, übergeht aber seine Angst und lädt ihn nicht ein, mehr zu erzählen, sodass das Gespräch versandet.","coreRule":"⚡ Biete Verbindung an, keine Korrektur: Hör zu, um zu verstehen, nicht um zu antworten.","beleg":"Werkstück H.2.3 (Techniken: Paraphrasieren, Emotionen benennen, klärende Fragen); Fn. gl-h-zuhoeren (Braun/Burian/Diefenbacher 2016; Wilke 1994; Kraft 2016). Buchbezug „im Sinne von H.2.3“ aus der Frage entfernt; Optionen auf gleiche Bauart und ähnliche Länge angeglichen (Option 3 hat kein Begründungsanhängsel mehr als die übrigen).","status":"entwurf","kurz":"Aktives Zuhören greift auf, was Alex sagt und fühlt, und fragt offen nach, statt zu widerlegen, zuzustimmen oder zu beruhigen. Verstehen heißt nicht zustimmen, aber es hält das Gespräch offen und liefert, was du für alles Weitere brauchst.","prueffrage":"Was schreibt Alex über sich selbst, und was befürchtet er am Ende seiner Nachricht?","rueckmeldung":[{"option":1,"text":"Faktenchecks können später durchaus hilfreich sein. Jetzt antworten sie aber nur auf den Inhalt der Drops, nicht auf Alex, der Angst hat und kaum schläft. Er bekommt keine Einladung zu erzählen und fühlt sich wohl eher belehrt."},{"option":2,"text":"Hier steckt echte Nähe, und dass Alex gut nachdenken kann, stimmt. Aber du stimmst dem Inhalt voll zu, ohne ihn verstanden oder geprüft zu haben. Mitgefühl mit seiner Lage ist etwas anderes als Zustimmung zu seinen Annahmen."},{"option":3,"text":"Hier wird die Sorge aufgenommen und beruhigt, und Alex hört, dass er nicht verrückt ist. Doch „das gibt sich wieder“ übergeht seine Angst und lädt nicht zum Erzählen ein. So endet das Gespräch, bevor es richtig begonnen hat."}],"familie":"fair-wiedergeben","fertigkeit":"F3","quellen":[{"typ":"doi","kurz":"Richmond, Berlin, Fishkind u. a. (2012): Verbal De-escalation of the Agitated Patient: Consensus Statement of the American Association for Emergency Psychiatry Project BETA De-escalation Workgroup. West J Emerg Med 13(1)","oeffentlich":true,"doi":"10.5811/westjem.2011.9.6864","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC3298202/","abruf":"2026-10-12"},{"typ":"url","kurz":"Lewandowsky & Cook (2020): The Conspiracy Theory Handbook (Skeptical Science)","oeffentlich":true,"url":"https://skepticalscience.com/docs/ConspiracyTheoryHandbook.pdf","seite":"10","abruf":"2026-10-12"},{"typ":"doi","kurz":"Kalla & Broockman (2020): Reducing Exclusionary Attitudes through Interpersonal Conversation: Evidence from Three Field Experiments (APSR 114(2), doi 10.1017/S0003055419000923; frei als SocArXiv-Vorabfassung vom 17.01.2020)","oeffentlich":true,"doi":"10.31235/osf.io/2ra9x","seite":"Abstract (S. 1 der Vorabfassung)","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"08cb5e1470ec08e7"}},{"id":"qx-h-045","clusterId":"H","werkstueckRef":"H.2.4","stufe":1,"question":"Welche Entscheidung ist hier die klügste?","options":["Das Gespräch ruhig beenden („Wir reden nicht mehr über die Sache, deshalb höre ich hier auf“), weil kein Austausch von Argumenten mehr stattfindet.","Ruhig weiterdiskutieren („Ich bleibe dran“), weil sich Beharrlichkeit in schwierigen Gesprächen auszahlt, sobald der andere merkt, dass man nicht lockerlässt.","Eine klärende Nachfrage stellen („Was genau meinst du damit?“), weil hinter scharfen Aussagen oft ein Missverständnis steckt, das sich so ausräumen lässt.","Weitere Quellen und Zahlen anführen („Dann zeige ich dir die Daten“), weil sich sachliche Streitfragen am besten mit Belegen klären lassen."],"correctIndex":0,"explanation":"Ein Gespräch lebt davon, dass beide auf Argumente eingehen und eine gemeinsame Wirklichkeit anerkennen. Hier wird beides gebrochen: Er greift die Person statt der Sache an und leugnet, was er selbst gesagt hat. Solange das so bleibt, bringt jeder weitere Beitrag nichts, denn es geht ihm nicht mehr ums Überzeugen, und weiteres Mitspielen kostet nur zusätzliche Kraft. Ruhig und begründet auszusteigen schützt deine Energie und lässt dir die Souveränität. Beharrlichkeit lohnt, wenn sich der andere bewegt; hier ist schon der dritte Versuch gescheitert. Nachfragen helfen bei Missverständnissen, aber er beantwortet jede Gegenfrage nur mit Angriffen. Belege nützen nur, wenn Gegenargumente überhaupt zählen, und das tun sie hier nicht.","coreRule":"⚡ Wer das Brett umwirft, spielt nicht mehr Schach: Dann darfst du aufstehen.","beleg":"Werkstück H.2.4 (Die Geschichte; Kernidee; Kontext & Tiefe; Anwendung & Relevanz – Wie man den Ausstieg vollzieht)","status":"entwurf","scenario":"Du diskutierst seit einer Stunde mit einem Bekannten über ein politisches Thema. Auf jede Gegenfrage antwortet er nur noch mit Angriffen auf deine Person („Du hast ja keine Ahnung“). Als du dich auf seine eigene Aussage von vorhin beziehst, behauptet er, das nie gesagt zu haben. Dein Versuch, zur Sache zurückzukehren, scheitert zum dritten Mal. Du bist erschöpft, und das Gespräch dreht sich seit Minuten im Kreis.","quote":"","quoteLabel":"","kurz":"Wenn er die Person statt der Sache angreift und eigene Aussagen leugnet, gibt es keinen Austausch von Argumenten mehr. Mehr Einsatz ändert daran nichts, ruhig und begründet auszusteigen schützt dagegen deine Kraft.","prueffrage":"Geht er mit seinen letzten Antworten noch auf das ein, was du sagst, oder nur auf dich als Person?","rueckmeldung":[{"option":1,"text":"Durchhalten wirkt stark und lohnt sich oft, wenn sich der andere bewegt. Hier sind aber schon drei Versuche gescheitert, ohne dass er sich einen Schritt bewegt hat, und jede weitere Runde kostet nur zusätzliche Kraft."},{"option":2,"text":"Eine Nachfrage kann ein echtes Missverständnis ausräumen. Hier ist aber keines erkennbar: Er beantwortet jede Gegenfrage mit Angriffen und streitet ab, was er gesagt hat, die Nachfrage liefe also ins Leere."},{"option":3,"text":"Belege sind bei Sachfragen meist das beste Mittel. Sie wirken aber nur, wenn Gegenargumente für den anderen überhaupt zählen. Wer Personen angreift und eigene Aussagen leugnet, lässt auch neue Zahlen abprallen."}],"familie":"kraefte-und-ausstieg","fertigkeit":"F3","quellen":[{"typ":"doi","kurz":"Petrov, Chan, Lau u. a. (2023): Sunk Cost Effects for Time Versus Money: Replication and Extensions Registered Report of Soman (2001). International Review of Social Psychology 36(1), Art. 17","oeffentlich":true,"doi":"10.5334/irsp.883","url":"https://rips-irsp.com/articles/10.5334/irsp.883","abruf":"2026-10-12"},{"typ":"url","kurz":"Hansen, H. (2015/2024): Fallacies. Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/fallacies/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Arkes & Blumer (1985): The Psychology of Sunk Cost. Organizational Behavior and Human Decision Processes 35(1) (nicht frei, laut OpenAlex geschlossen; in Landkarte B.6 geprüft)","oeffentlich":false,"doi":"10.1016/0749-5978(85)90049-4"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"1a623f12408fcf3a"}},{"id":"qx-h-046","clusterId":"H","werkstueckRef":"H.2.4","stufe":2,"question":"Welcher Abschlusssatz beendet das Gespräch in dieser Lage am besten?","scenario":"Dein Gegenüber wirft dir seit einer Weile Halbwahrheiten im Minutentakt hin, geht auf keinen deiner Punkte ein und wird persönlich. Zwei Versuche, das Gespräch zu beruhigen und zur Sache zurückzuführen, sind gescheitert. Du merkst, dass dich jede weitere Antwort nur Kraft kostet, ohne dass etwas geklärt wird.","options":["„Ich habe das Gefühl, dass dieses Gespräch nicht mehr produktiv ist, weil wir nicht mehr über die Sache, sondern übereinander reden. Ich möchte es hier beenden.“","„Ich sehe, dass du auf keinen meiner Punkte eingehst, weil es dir nicht um Klärung geht, sondern ums Rechthaben. Deshalb beende ich das Gespräch an dieser Stelle.“","„Lass uns eine neutrale Person bitten, deine Behauptungen Punkt für Punkt zu prüfen und zwischen uns zu vermitteln. Danach sprechen wir gern weiter.“","„Ich schlage vor, wir machen jetzt eine Pause und sprechen morgen weiter, wenn wir beide ruhiger sind und uns wieder auf die Sache einlassen können.“"],"correctIndex":0,"explanation":"Ein Gespräch lohnt sich nur, solange beide Seiten sich auf die Sache einlassen; hier geht die andere Seite auf keinen deiner Punkte ein, und zwei Versuche, zur Sache zurückzukehren, sind gescheitert. Der beste Abschlusssatz bleibt ruhig, benennt sachlich den Grund (ihr redet nicht mehr über die Sache, sondern übereinander) und beendet das Gespräch, ohne die Person abzuwerten.","coreRule":"⚡ Steige ruhig, bestimmt und begründet aus: Benenne sachlich den Grund, ohne die Person abzuwerten.","beleg":"Werkstück H.2.4 (Wie man den Ausstieg vollzieht: Meta-Kommunikation)","status":"entwurf","kurz":"Hier lohnt sich das Gespräch nicht mehr, denn auf keinen Punkt wird eingegangen. Ein guter Schlusssatz nennt diesen sachlichen Grund und beendet das Gespräch, statt dem Gegenüber Motive zu unterstellen.","prueffrage":"Ist das Gespräch nach deinem letzten Satz wirklich beendet, und was erfährt dein Gegenüber darin über den Grund?","rueckmeldung":[{"option":1,"text":"Dass auf keinen Punkt eingegangen wird, stimmt. „Es geht dir ums Rechthaben“ unterstellt aber ein Motiv, das du nicht prüfen kannst, und macht die Person zum Thema. Das lädt zu neuem Streit ein."},{"option":2,"text":"Bei echten Sachfragen kann eine Vermittlung helfen. Sie setzt aber voraus, dass beide weitersprechen wollen. Hier würde das Gespräch dadurch nicht beendet, sondern verlängert, und es kostet dich weiter Kraft."},{"option":3,"text":"Eine Pause klingt nach vernünftiger Beruhigung. Zwei Beruhigungsversuche sind aber schon gescheitert, und das Problem ist nicht die Stimmung: Auf keinen Punkt wird eingegangen. Eine Nacht ändert daran nichts, das Gespräch wäre nur vertagt."}],"familie":"kraefte-und-ausstieg","fertigkeit":"F3","quellen":[{"typ":"doi","kurz":"Rogers, Howieson & Neame (2018): I understand you feel that way, but I feel this way: the benefits of I-language and communicating perspective during conflict. PeerJ 6:e4831","oeffentlich":true,"doi":"10.7717/peerj.4831","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC5961625/","abruf":"2026-10-12"},{"typ":"url","kurz":"Hansen, H. (2015/2024): Fallacies. Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/fallacies/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"be82425b4b7cde8e"}},{"id":"qx-h-047","clusterId":"H","werkstueckRef":"H.2.4","stufe":3,"question":"Ein Gespräch über Wohnungspolitik läuft seit einer Stunde. Du hast zweimal ruhig angeboten, zur Sachfrage zurückzukehren. Welche Beobachtung rechtfertigt es am ehesten, das Gespräch jetzt zu beenden?","options":["Er geht auf keinen deiner Punkte inhaltlich ein, und nach einer Stunde seid ihr euch in der Wohnungsfrage noch keinen Schritt nähergekommen.","Er wertet dich fortwährend ab, und es ist vernünftig, ein Gespräch zu verlassen, sobald es für dich spürbar unangenehm wird.","Er nennt dich ahnungslos und wertet dich ab, und wer so mit dir spricht, hat sich eine weitere Antwort von dir nicht mehr verdient.","Er greift dich fortlaufend persönlich an, und deine zwei ruhigen Versuche, zur Sache zurückzukehren, beantwortet er mit neuen Angriffen."],"correctIndex":3,"explanation":"Ein Abbruch ist dann begründet, wenn das Gegenüber nicht mehr nach den Regeln des ehrlichen Diskurses spielt: Unehrliche Mittel wie persönliche Angriffe sind nicht mehr vereinzelte Ausrutscher, sondern die primäre Kommunikationsstrategie, und mehrfache Versuche, das Gespräch auf die sachliche Ebene zurückzuführen, scheitern. Dann ist das Spiel manipuliert, und jeder weitere Beitrag kostet mentale Energie, ohne dass ein echter Austausch von Ideen möglich ist. Sachlicher Widerspruch ist dagegen der Normalfall eines guten Gesprächs, auch wenn er unbequem ist. Ein einzelner Fehler, der sofort korrigiert wird, zeigt gerade Redlichkeit, denn dort ist der Einzelfall kein Dauerzustand. Und eigenes Unbehagen oder fehlende Gegenargumente sind kein Ausstiegsgrund: Ein Ausstieg setzt voraus, dass das Gegenüber systematisch unehrliche Taktiken einsetzt, und nicht, dass das Gespräch für dich selbst schwierig wird.","coreRule":"⚡ Ein Gespräch zu verlassen ist angemessen bei systematischer Unehrlichkeit und gescheiterten Rückführungsversuchen, nicht bei bloßem Unbehagen oder Gegenwind.","beleg":"Werkstück H.2.4 (Anwendung & Relevanz: Wann man den Tisch verlässt; Red Flags)","status":"entwurf","scenario":"Dein Gesprächspartner antwortet auf keinen deiner Punkte inhaltlich. Stattdessen wertet er dich bei jedem Beitrag persönlich ab („Typisch du, du hast ja keine Ahnung“). Deine zwei freundlichen Rückführungen auf die Sache hat er jeweils mit neuen Angriffen beantwortet.","kurz":"Hier ist der Angriff keine Entgleisung mehr, sondern die Strategie des Gegenübers, und zwei ruhige Rückführungen blieben wirkungslos. Dann ist ein ehrlicher Austausch nicht mehr möglich. Ein einzelner Ausrutscher oder bloßes Unbehagen reichte dafür nicht.","prueffrage":"Woran erkennst du im Gesprächsverlauf, ob jemand dir nur widerspricht oder ob er gar nicht mehr über die Sache redet?","rueckmeldung":[{"option":0,"text":"Ausbleibender Fortschritt nach einer Stunde fällt auf und ist frustrierend. Er kann aber viele Ursachen haben, etwa echte Uneinigkeit oder ein schwieriges Thema, und beweist keine unehrliche Gesprächsführung. Entscheidend sind hier die Angriffe und die gescheiterten Rückführungen."},{"option":1,"text":"Die ständige Abwertung ist real, und ein unangenehmes Gespräch zu verlassen, ist nachvollziehbar. Als Maßstab trägt dein Unbehagen aber nicht: Auch ein unbequemes Gespräch kann ehrlich sein. Belastbar wird der Abbruch erst durch sein Verhalten, das sich trotz deiner Versuche nicht ändert."},{"option":2,"text":"Dass er dich abwertet, stimmt, doch „hat sich eine Antwort nicht verdient“ macht daraus eine Frage von Verdienst und Vergeltung. Der Abbruch ist begründet, weil unter diesen Bedingungen kein echter Austausch mehr möglich ist. Dazu gehört, dass deine zwei ruhigen Rückführungen ins Leere liefen."}],"familie":"kraefte-und-ausstieg","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Hansen, H. (2015/2024): Fallacies. Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/fallacies/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v7","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"26e743302191b3bb"}},{"id":"qx-h-048","clusterId":"H","werkstueckRef":"H.2.4","stufe":4,"question":"Was ist an dieser Antwort deines Cousins das eigentliche Problem für ein sinnvolles Gespräch?","scenario":"Dein Cousin antwortet auf jeden Beleg: „Genau das sagen sie ja, damit wir es nicht merken. Dein Beleg ist Teil der Vertuschung.“","options":["Er weist deine Belege zurück, ohne selbst einen Beleg für die Vertuschung zu nennen, sodass die Beweislast nur bei dir liegt.","Er wertet jeden Beleg gegen die Vertuschung selbst als Teil der Vertuschung, sodass nichts ihn mehr widerlegen könnte.","Er greift nicht den Inhalt deiner Belege an, sondern die Leute dahinter, sodass er die Quelle statt der Sache abwertet.","Er geht auf den Inhalt deiner Belege nicht ein, sodass erst stärkere Belege das Gespräch wieder voranbringen könnten."],"correctIndex":1,"explanation":"Eine Behauptung, die jeden Gegenbeweis als Beweis für die Verschwörung umdeutet, lässt sich durch nichts mehr widerlegen. Dann ist kein echter Austausch von Ideen mehr möglich: Weitere Belege kosten dich nur Zeit und Energie. Ein ruhiger, begründeter Ausstieg („Wir kommen hier nicht weiter, lass uns das Thema beenden.“) ist dann die vernünftigere Wahl, als weiter zu argumentieren.","coreRule":"⚡ Wo jeder Beleg zum Beweis für die Verschwörung wird, ist das Spiel versiegelt: Dann hilft nur der ruhige Ausstieg.","beleg":"Werkstück H.2.4 (Anwendung & Relevanz: ‚Wenn der Verschwörungsmythos sich versiegelt‘)","status":"entwurf","kurz":"Wenn jeder Beleg gegen die Vertuschung als Teil der Vertuschung gilt, kann nichts mehr widerlegen, und das Gespräch dreht sich im Kreis. Weitere Belege bringen dann nichts; ein ruhiger Ausstieg ist vernünftiger.","prueffrage":"Was hat dein Cousin auf deine bisherigen Belege geantwortet, und hing seine Antwort davon ab, was im jeweiligen Beleg stand?","rueckmeldung":[{"option":0,"text":"Dass er selbst nichts vorlegt, stimmt. Er verlangt von dir aber keinen Gegenbeweis, sondern erklärt deinen Beleg im Voraus für wertlos. Selbst wenn die Beweislast fair verteilt wäre, bliebe das Problem bestehen."},{"option":2,"text":"Hier geht es nicht um Personen: Er greift weder dich noch die Urheber des Belegs an, sondern deutet den Beleg selbst um. Eine Quellenabwertung wäre ein anderer Denkfehler als dieser."},{"option":3,"text":"Er geht tatsächlich nicht auf den Inhalt ein. Stärkere Belege würden aber nichts ändern, denn auch sie würden als Teil der Vertuschung gedeutet. Mehr Aufwand bringt das Gespräch deshalb nicht voran."}],"familie":"kraefte-und-ausstieg","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Lewandowsky & Cook (2020): The Conspiracy Theory Handbook (Skeptical Science)","oeffentlich":true,"url":"https://skepticalscience.com/docs/ConspiracyTheoryHandbook.pdf","seite":"7","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v9","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"ok","pruefsumme":"7f82ffdc0bb88e7a"}}]`);export{t as n,n as t};